package com.seasonalscape;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Small, depth-tested ground decorations. All methods run on the client thread.
 * Objects have no menus, collision data, animations or gameplay effects.
 */
public final class GroundCover
{
    // An existing low-polygon snow-particle mesh in the game cache. The mesh is
    // cloned before its vertices, colors, textures or transparency are changed.
    private static final int FLAKE_MODEL_ID = 27835;
    private static final int SECTOR_TILES = 8;
    private static final int MAX_OBJECTS = 200;
    private static final int VARIANT_COUNT = 4;
    private static final int MAX_FLAKES = 16;
    private static final int MAX_CORNER_HEIGHT_DIFFERENCE = 64;

    private final Client client;
    private final Map<Long, RuneLiteObject> objects = new HashMap<>();
    private Scene currentScene;
    private int baseX;
    private int baseY;
    private Season modelSeason;
    private Model[] models;
    private List<Candidate> cachedCandidates;
    private int cachedDensity = -1;
    private Season cachedSeason;

    public GroundCover(Client client)
    {
        this.client = client;
    }

    public int getCount()
    {
        return objects.size();
    }

    /** Unregisters every decoration immediately, including objects offscreen. */
    public void clear()
    {
        for (RuneLiteObject object : objects.values())
        {
            object.setActive(false);
        }
        objects.clear();
        currentScene = null;
        invalidate();
    }

    /** Recheck outdoor eligibility after a scene/configuration/object refresh. */
    public void invalidate()
    {
        cachedCandidates = null;
        cachedDensity = -1;
        cachedSeason = null;
    }

    /**
     * Every nonwinter season covers the loaded outdoor scene with evenly spread
     * decorations. Default density places up to 120 flowers or 200 leaf piles;
     * all seasons retain a hard limit of 200 objects.
     * Density continues to select the same percentage of eligible world tiles.
     */
    public void update(Scene scene, SeasonalSceneRecolorer recolorer, Season season,
        boolean enabled, int density)
    {
        WorldView world = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        LocalPoint playerPoint = player == null ? null : player.getLocalLocation();
        if (!enabled || density <= 0 || season == null
            || season == Season.WINTER
            || client.getGameState() != GameState.LOGGED_IN || scene == null || recolorer == null
            || world == null || !world.isTopLevel() || world.getScene() != scene
            || world.isInstance() || scene.isInstance() || world.getPlane() != 0
            || playerPoint == null || playerPoint.getWorldView() != world.getId()
            || !SeasonalWorldArea.contains(scene.getBaseX() + playerPoint.getSceneX(),
                scene.getBaseY() + playerPoint.getSceneY()))
        {
            clear();
            return;
        }

        if (currentScene != scene || baseX != scene.getBaseX() || baseY != scene.getBaseY()
            || modelSeason != season)
        {
            clear();
            currentScene = scene;
            baseX = scene.getBaseX();
            baseY = scene.getBaseY();
        }
        if (models == null || modelSeason != season)
        {
            models = createModels(season);
            modelSeason = season;
            if (models == null)
            {
                return; // A cache model may not have been downloaded yet; retry later.
            }
        }

        Tile[][][] tiles = scene.getTiles();
        CollisionData[] collisionMaps = world.getCollisionMaps();
        // WorldView heights use the same regular scene coordinates as getTiles();
        // Scene heights can include the extended-scene border.
        int[][][] heights = world.getTileHeights();
        if (tiles == null || tiles.length == 0 || tiles[0] == null
            || collisionMaps == null || collisionMaps.length == 0 || collisionMaps[0] == null
            || heights == null || heights.length == 0 || heights[0] == null)
        {
            clear();
            return;
        }

        int[][] collisionFlags = collisionMaps[0].getFlags();
        int chance = Math.min(100, density);
        int limit = Math.min(MAX_OBJECTS, chance * (season == Season.AUTUMN ? 8 : 4));
        List<Candidate> candidates;
        if (cachedCandidates != null && cachedDensity == chance && cachedSeason == season
            && candidatesStillEligible(cachedCandidates, tiles, collisionFlags, heights[0], recolorer))
        {
            candidates = cachedCandidates;
        }
        else
        {
            candidates = distributeAcrossSectors(
                candidates(tiles, collisionFlags, heights[0], recolorer, chance), limit);
            cachedCandidates = candidates;
            cachedDensity = chance;
            cachedSeason = season;
        }

        // Desired positions are independent of both player and camera;
        // walking through a stable scene retains the same registered objects.
        Set<Long> desired = new HashSet<>();
        for (int i = 0; i < Math.min(limit, candidates.size()); i++)
        {
            desired.add(candidates.get(i).key);
        }
        Iterator<Map.Entry<Long, RuneLiteObject>> iterator = objects.entrySet().iterator();
        while (iterator.hasNext())
        {
            Map.Entry<Long, RuneLiteObject> entry = iterator.next();
            if (!desired.contains(entry.getKey()))
            {
                entry.getValue().setActive(false);
                iterator.remove();
            }
        }
        for (int i = 0; i < Math.min(limit, candidates.size()); i++)
        {
            Candidate candidate = candidates.get(i);
            if (!objects.containsKey(candidate.key))
            {
                LocalPoint center = candidate.tile.getLocalLocation();
                int jitterX = (int) ((candidate.seed >>> 8) % 17) - 8;
                int jitterY = (int) ((candidate.seed >>> 16) % 17) - 8;
                LocalPoint location = new LocalPoint(center.getX() + jitterX,
                    center.getY() + jitterY, world.getId());
                int variant = (int) ((candidate.seed >>> 24) & (VARIANT_COUNT - 1));
                Model model = GroundCoverPlacement.model(client, season, variant, location, heights[0]);
                if (model == null)
                {
                    continue;
                }
                RuneLiteObject object = client.createRuneLiteObject();
                object.setModel(model);
                object.setLocation(location, 0);
                object.setZ(object.getZ() - 2);
                // The mesh already has varied decoration angles and follows the
                // terrain at this location, so rotating it would undo that fit.
                object.setOrientation(0);
                object.setActive(true);
                objects.put(candidate.key, object);
            }
        }
    }

    private List<Candidate> candidates(Tile[][][] tiles, int[][] collisionFlags,
        int[][] heights, SeasonalSceneRecolorer recolorer, int chance)
    {
        List<Candidate> candidates = new ArrayList<>();
        for (int x = 1; x < tiles[0].length - 1; x++)
        {
            if (tiles[0][x] == null)
            {
                continue;
            }
            for (int y = 1; y < tiles[0][x].length - 1; y++)
            {
                long key = worldKey(baseX + x, baseY + y);
                long seed = mix(key);
                Tile tile = tiles[0][x][y];
                if (Math.floorMod(seed, 100) < chance
                    && eligible(tile, x, y, tiles, collisionFlags, heights, recolorer))
                {
                    candidates.add(new Candidate(key, seed, tile, x, y));
                }
            }
        }

        return candidates;
    }

    private static boolean candidatesStillEligible(List<Candidate> candidates, Tile[][][] tiles,
        int[][] collision, int[][] heights, SeasonalSceneRecolorer recolorer)
    {
        for (Candidate candidate : candidates)
        {
            int x = candidate.x, y = candidate.y;
            if (x >= tiles[0].length || tiles[0][x] == null || y >= tiles[0][x].length
                || tiles[0][x][y] != candidate.tile
                || !eligible(candidate.tile, x, y, tiles, collision, heights, recolorer))
            {
                return false;
            }
        }
        return true;
    }

    /** Give every occupied world sector a decoration before filling any sector again. */
    private static List<Candidate> distributeAcrossSectors(List<Candidate> candidates, int limit)
    {
        Map<Long, List<Candidate>> sectors = new HashMap<>();
        for (Candidate candidate : candidates)
        {
            int worldX = (int) (candidate.key >> 32);
            int worldY = (int) candidate.key;
            long sector = worldKey(Math.floorDiv(worldX, SECTOR_TILES),
                Math.floorDiv(worldY, SECTOR_TILES));
            sectors.computeIfAbsent(sector, unused -> new ArrayList<>()).add(candidate);
        }
        List<Long> order = new ArrayList<>(sectors.keySet());
        order.sort(Comparator.comparingLong(GroundCover::mix));
        for (List<Candidate> sector : sectors.values())
        {
            sector.sort(Comparator.comparingLong(candidate -> candidate.seed));
        }
        List<Candidate> result = new ArrayList<>(Math.min(limit, candidates.size()));
        for (int round = 0; result.size() < limit; round++)
        {
            boolean found = false;
            for (long key : order)
            {
                List<Candidate> sector = sectors.get(key);
                if (round < sector.size())
                {
                    result.add(sector.get(round));
                    found = true;
                    if (result.size() == limit) { break; }
                }
            }
            if (!found) { break; }
        }
        return result;
    }

    private static boolean eligible(Tile tile, int x, int y, Tile[][][] tiles,
        int[][] collision, int[][] heights, SeasonalSceneRecolorer recolorer)
    {
        if (tile == null || tile.getPlane() != 0 || tile.getRenderLevel() != 0
            || tile.getBridge() != null || tile.getWallObject() != null
            || tile.getDecorativeObject() != null
            || tile.getItemLayer() != null || !recolorer.isSeasonalGround(tile)
            || collision == null || x >= collision.length || collision[x] == null
            || y >= collision[x].length || collision[x][y] != 0)
        {
            return false;
        }
        GameObject[] gameObjects = tile.getGameObjects();
        if (gameObjects != null)
        {
            for (GameObject object : gameObjects)
            {
                if (object != null)
                {
                    return false;
                }
            }
        }
        for (int plane = 1; plane < tiles.length; plane++)
        {
            if (tiles[plane] != null && x < tiles[plane].length && tiles[plane][x] != null
                && y < tiles[plane][x].length && tiles[plane][x][y] != null)
            {
                return false; // Roofs, bridges and upper floors.
            }
        }
        if (x + 1 >= heights.length || heights[x] == null || heights[x + 1] == null
            || y + 1 >= heights[x].length || y + 1 >= heights[x + 1].length)
        {
            return false;
        }
        int min = Math.min(Math.min(heights[x][y], heights[x + 1][y]),
            Math.min(heights[x][y + 1], heights[x + 1][y + 1]));
        int max = Math.max(Math.max(heights[x][y], heights[x + 1][y]),
            Math.max(heights[x][y + 1], heights[x + 1][y + 1]));
        return max - min <= MAX_CORNER_HEIGHT_DIFFERENCE;
    }

    private Model[] createModels(Season season)
    {
        ModelData source = client.loadModelData(FLAKE_MODEL_ID);
        if (source == null || source.getVerticesCount() < 3 || source.getFaceCount() == 0
            || source.getVerticesCount() > 8192 || source.getFaceCount() > 8192)
        {
            return null;
        }
        Model[] result = new Model[VARIANT_COUNT];
        for (int variant = 0; variant < VARIANT_COUNT; variant++)
        {
            ModelData data = source.shallowCopy().cloneVertices().cloneColors();
            // Untextured cache models have no texture array to clone.
            if (data.getFaceTextures() != null)
            {
                data.cloneTextures();
            }
            data.cloneTransparencies(true);
            reshapeFlakes(source, data, season, variant);
            if (data.getFaceTextures() != null)
            {
                Arrays.fill(data.getFaceTextures(), (short) -1);
            }
            Arrays.fill(data.getFaceTransparencies(), (byte) 0);
            // Exercise the normal transform path after direct vertex edits as
            // a precaution against cached derived geometry before lighting.
            data.translate(0, 0, 0);
            result[variant] = data.light(80, ModelData.DEFAULT_CONTRAST,
                ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
        }
        return result;
    }

    /** Reuses mesh topology without ever changing the cache's face indices. */
    static void reshapeFlakes(ModelData source, ModelData target, Season season, int variant)
    {
        int count = source.getVerticesCount();
        int[] roots = new int[count];
        for (int i = 0; i < count; i++)
        {
            roots[i] = i;
        }
        int[] faceA = source.getFaceIndices1();
        int[] faceB = source.getFaceIndices2();
        int[] faceC = source.getFaceIndices3();
        for (int i = 0; i < source.getFaceCount(); i++)
        {
            union(roots, faceA[i], faceB[i]);
            union(roots, faceA[i], faceC[i]);
        }
        Map<Integer, List<Integer>> components = new LinkedHashMap<>();
        for (int i = 0; i < count; i++)
        {
            components.computeIfAbsent(root(roots, i), unused -> new ArrayList<>()).add(i);
        }
        float[][] original = {source.getVerticesX(), source.getVerticesY(), source.getVerticesZ()};
        float[] x = target.getVerticesX();
        float[] y = target.getVerticesY();
        float[] z = target.getVerticesZ();
        Map<Integer, Integer> pieces = new HashMap<>();
        int flake = 0;
        for (Map.Entry<Integer, List<Integer>> component : components.entrySet())
        {
            List<Integer> vertices = component.getValue();
            if (vertices.size() < 3 || flake >= MAX_FLAKES)
            {
                for (int index : vertices)
                {
                    x[index] = 0;
                    y[index] = 0;
                    z[index] = 0;
                }
                continue;
            }
            pieces.put(component.getKey(), flake);
            float[] min = {Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY};
            float[] max = {Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY};
            for (int index : vertices)
            {
                for (int axis = 0; axis < 3; axis++)
                {
                    min[axis] = Math.min(min[axis], original[axis][index]);
                    max[axis] = Math.max(max[axis], original[axis][index]);
                }
            }
            Integer[] axes = {0, 1, 2};
            Arrays.sort(axes, (a, b) -> Float.compare(max[b] - min[b], max[a] - min[a]));
            int first = axes[0];
            int second = axes[1];
            float spanA = Math.max(1, max[first] - min[first]);
            float spanB = Math.max(1, max[second] - min[second]);
            float winding = 1;
            for (int face = 0; face < source.getFaceCount(); face++)
            {
                if (root(roots, faceA[face]) != component.getKey())
                {
                    continue;
                }
                float area = (original[first][faceB[face]] - original[first][faceA[face]])
                    * (original[second][faceC[face]] - original[second][faceA[face]])
                    - (original[second][faceB[face]] - original[second][faceA[face]])
                    * (original[first][faceC[face]] - original[first][faceA[face]]);
                if (Math.abs(area) > 0.01f)
                {
                    winding = Math.signum(area);
                    break;
                }
            }
            long seed = mix(0x534541534f4eL + flake * 97L + variant * 7919L);
            double angle = ((seed >>> 8) & 1023) * (2 * Math.PI / 1024);
            double distance = Math.sqrt(((seed >>> 20) & 255) / 255.0)
                * (season == Season.AUTUMN ? 28 : 33);
            float centerX = (float) (Math.cos(angle) * distance);
            float centerZ = (float) (Math.sin(angle) * distance);
            double rotation = ((seed >>> 30) & 1023) * (2 * Math.PI / 1024);
            float cosine = (float) Math.cos(rotation);
            float sine = (float) Math.sin(rotation);
            float length = season == Season.WINTER ? 18 + (seed & 7) : 9 + (seed & 7);
            float width = season == Season.WINTER ? 14 + ((seed >>> 3) & 7)
                : season == Season.SPRING ? 5 : 7;
            for (int index : vertices)
            {
                float u = (original[first][index] - min[first]) / spanA - 0.5f;
                float v = ((original[second][index] - min[second]) / spanB - 0.5f) * winding;
                if (SeasonalFlowerGeometry.appliesTo(season))
                {
                    SeasonalFlowerGeometry.vertex(season, variant, flake, u, v, x, y, z, index);
                    continue;
                }
                float along = u * length;
                float across = v * width;
                x[index] = centerX + along * cosine - across * sine;
                z[index] = centerZ + along * sine + across * cosine;
                y[index] = -0.25f - (1 - Math.abs(u * 2)) * (1 - Math.abs(v * 2));
                if (season == Season.AUTUMN) { y[index] -= flake * 0.03f; }
            }
            flake++;
        }
        short[] colors = target.getFaceColors();
        for (int face = 0; face < source.getFaceCount(); face++)
        {
            int shade = Math.floorMod(root(roots, faceA[face]) + variant, 4);
            colors[face] = SeasonalFlowerGeometry.appliesTo(season)
                ? SeasonalFlowerGeometry.color(season, variant,
                    pieces.getOrDefault(root(roots, faceA[face]), 0))
                : flakeColor(season, shade);
        }
    }

    private static short flakeColor(Season season, int shade)
    {
        if (season == Season.WINTER)
        {
            return JagexColor.packHSL(36, 0, 108 + shade * 4);
        }
        if (season == Season.SPRING)
        {
            return JagexColor.packHSL(59 + shade % 2, 2, 91 + shade * 6);
        }
        int[] hues = {3, 6, 9, 11};
        return JagexColor.packHSL(hues[shade], 5, 40 + shade * 7);
    }

    private static int root(int[] parents, int index)
    {
        while (parents[index] != index)
        {
            parents[index] = parents[parents[index]];
            index = parents[index];
        }
        return index;
    }

    private static void union(int[] parents, int first, int second)
    {
        parents[root(parents, second)] = root(parents, first);
    }

    private static long worldKey(int x, int y)
    {
        return ((long) x << 32) | (y & 0xffffffffL);
    }

    private static long mix(long value)
    {
        value ^= value >>> 30;
        value *= 0xbf58476d1ce4e5b9L;
        value ^= value >>> 27;
        value *= 0x94d049bb133111ebL;
        return value ^ (value >>> 31);
    }

    private static final class Candidate
    {
        private final long key;
        private final long seed;
        private final Tile tile;
        private final int x;
        private final int y;

        private Candidate(long key, long seed, Tile tile, int x, int y)
        {
            this.key = key;
            this.seed = seed;
            this.tile = tile;
            this.x = x;
            this.y = y;
        }
    }
}

package com.seasonalscape;

import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.coords.LocalPoint;

/** Fits each decoration to the ground without modifying its cached source. */
final class GroundCoverPlacement
{
    private GroundCoverPlacement()
    {
    }

    static Model model(Client client, Season season, int variant, LocalPoint location, int[][] heights)
    {
        float centerHeight = height(heights, location.getX(), location.getY());
        if (!Float.isFinite(centerHeight))
        {
            return null;
        }
        ModelData source = client.loadModelData(27835);
        if (source == null || source.getVerticesCount() < 3 || source.getFaceCount() == 0
            || source.getVerticesCount() > 8192 || source.getFaceCount() > 8192)
        {
            return null;
        }
        // Four overlapping leaf layers fill each autumn pile without creating
        // more world objects or changing the spacing between piles.
        ModelData[] layers = new ModelData[season == Season.AUTUMN ? 4 : 1];
        for (int layer = 0; layer < layers.length; layer++)
        {
            ModelData data = source.shallowCopy().cloneVertices().cloneColors();
            if (data.getFaceTextures() != null)
            {
                data.cloneTextures();
                Arrays.fill(data.getFaceTextures(), (short) -1);
            }
            data.cloneTransparencies(true);
            Arrays.fill(data.getFaceTransparencies(), (byte) 0);
            GroundCover.reshapeFlakes(source, data, season, variant + layer * 4);

            float[] x = data.getVerticesX();
            float[] y = data.getVerticesY();
            float[] z = data.getVerticesZ();
            for (int vertex = 0; vertex < data.getVerticesCount(); vertex++)
            {
                float groundHeight = height(heights, location.getX() + x[vertex],
                    location.getY() + z[vertex]);
                if (!Float.isFinite(groundHeight)) { return null; }
                // Negative Y is uphill. Slightly separate the overlapping
                // layers to keep their leaf faces from flickering.
                y[vertex] += groundHeight - centerHeight - layer * 0.8f;
            }
            data.translate(0, 0, 0);
            layers[layer] = data;
        }
        ModelData data = layers.length == 1 ? layers[0] : client.mergeModels(layers);
        if (data == null) { return null; }
        return data.light(80, ModelData.DEFAULT_CONTRAST,
            ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
    }

    /** Bilinear terrain height at a position in ordinary scene-local units. */
    static float height(int[][] heights, float localX, float localY)
    {
        int x = (int) Math.floor(localX / 128.0f);
        int y = (int) Math.floor(localY / 128.0f);
        if (heights == null || x < 0 || y < 0 || x + 1 >= heights.length
            || heights[x] == null || heights[x + 1] == null
            || y + 1 >= heights[x].length || y + 1 >= heights[x + 1].length)
        {
            return Float.NaN;
        }
        float offsetX = localX / 128.0f - x;
        float offsetY = localY / 128.0f - y;
        float south = heights[x][y] * (1 - offsetX) + heights[x + 1][y] * offsetX;
        float north = heights[x][y + 1] * (1 - offsetX) + heights[x + 1][y + 1] * offsetX;
        return south * (1 - offsetY) + north * offsetY;
    }
}

package com.seasonalscape;

/** Selects the calendar used by automatic season detection. */
public enum Hemisphere
{
    NORTH("Northern hemisphere"),
    SOUTH("Southern hemisphere");

    private final String label;

    Hemisphere(String label)
    {
        this.label = label;
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.seasonalscape;

/** The four visual seasons. */
public enum Season
{
    SPRING("Spring"),
    SUMMER("Summer"),
    AUTUMN("Autumn"),
    WINTER("Winter");

    private final String label;

    Season(String label)
    {
        this.label = label;
    }

    public Season opposite()
    {
        switch (this)
        {
            case SPRING:
                return AUTUMN;
            case SUMMER:
                return WINTER;
            case AUTUMN:
                return SPRING;
            case WINTER:
                return SUMMER;
            default:
                throw new IllegalStateException("Unknown season: " + name());
        }
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.seasonalscape;

/** Automatic calendar detection or a fixed visual season. */
public enum SeasonMode
{
    AUTOMATIC("Automatic", null),
    SPRING("Spring", Season.SPRING),
    SUMMER("Summer", Season.SUMMER),
    AUTUMN("Autumn", Season.AUTUMN),
    WINTER("Winter", Season.WINTER);

    private final String label;
    private final Season fixedSeason;

    SeasonMode(String label, Season fixedSeason)
    {
        this.label = label;
        this.fixedSeason = fixedSeason;
    }

    /** Returns null for AUTOMATIC; use SeasonResolver to resolve that mode. */
    public Season getFixedSeason()
    {
        return fixedSeason;
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.seasonalscape;

import java.time.Clock;
import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Objects;

/** Calendar-only season detection, independent of RuneLite and rendering. */
public final class SeasonResolver
{
    private SeasonResolver()
    {
    }

    /** Defaults to the computer's date and the northern hemisphere. */
    public static Season resolve(SeasonMode mode)
    {
        return resolve(mode, Hemisphere.NORTH);
    }

    /** Uses the computer's local date, without requiring location services. */
    public static Season resolve(SeasonMode mode, Hemisphere hemisphere)
    {
        return resolve(mode, hemisphere, Clock.systemDefaultZone(), "");
    }

    /**
     * Uses meteorological seasons: March, June, September and December begin
     * spring, summer, autumn and winter in the northern hemisphere.
     *
     * An empty or invalid zone ID falls back to the supplied clock's zone.
     * Manual selections are used as-is in either hemisphere.
     */
    public static Season resolve(SeasonMode mode, Hemisphere hemisphere, Clock clock, String zoneId)
    {
        Objects.requireNonNull(mode, "mode");
        if (mode != SeasonMode.AUTOMATIC)
        {
            return mode.getFixedSeason();
        }

        Objects.requireNonNull(hemisphere, "hemisphere");
        Objects.requireNonNull(clock, "clock");
        ZoneId zone = clock.getZone();
        if (zoneId != null && !zoneId.trim().isEmpty())
        {
            try
            {
                zone = ZoneId.of(zoneId.trim());
            }
            catch (DateTimeException ignored)
            {
                // A malformed preference must not stop scene rendering.
            }
        }

        int month = LocalDate.now(clock.withZone(zone)).getMonthValue();
        Season season;
        if (month >= 3 && month <= 5)
        {
            season = Season.SPRING;
        }
        else if (month >= 6 && month <= 8)
        {
            season = Season.SUMMER;
        }
        else if (month >= 9 && month <= 11)
        {
            season = Season.AUTUMN;
        }
        else
        {
            season = Season.WINTER;
        }
        return hemisphere == Hemisphere.SOUTH ? season.opposite() : season;
    }
}

package com.seasonalscape;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Sparse, depth-tested spring petals and summer butterflies, on the client thread. */
final class SeasonalAir
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();
    private static final int RADIUS = 7 * 128;
    private static final int FRAMES = 8;

    private SeasonalAir() {}

    static int particleCount(Season season, boolean enabled, int density)
    {
        if (!enabled || density <= 0) { return 0; }
        int amount = Math.min(100, density);
        if (season == Season.SPRING) { return Math.min(40, 6 + amount / 2); }
        if (season == Season.SUMMER) { return Math.min(12, 2 + amount / 6); }
        return 0;
    }

    static void update(Object owner, Client client, Scene scene, SeasonalSceneRecolorer recolorer,
        Season season, boolean enabled, int density)
    {
        int count = particleCount(season, enabled, density);
        if (count == 0) { clear(owner); return; }
        WorldView world = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        LocalPoint point = player == null ? null : player.getLocalLocation();
        DrawCallbacks renderer = client.getDrawCallbacks();
        if (client.getGameState() != GameState.LOGGED_IN || world == null || scene == null
            || recolorer == null || (renderer != null && !(renderer instanceof GpuPlugin))
            || !world.isTopLevel() || world.isInstance() || scene.isInstance()
            || world.getPlane() != 0 || world.getScene() != scene || point == null
            || point.getWorldView() != world.getId()
            || !SeasonalWorldArea.contains(scene.getBaseX() + point.getSceneX(), scene.getBaseY() + point.getSceneY())
            || !WinterSnowfall.clearSky(world.getTileSettings(), point.getSceneX(), point.getSceneY()))
        {
            clear(owner);
            return;
        }
        State state = STATES.get(owner);
        if (state != null && (state.scene != scene || state.world != world || state.season != season
            || state.baseX != scene.getBaseX() || state.baseY != scene.getBaseY()
            || state.particles.size() != count))
        {
            clear(owner);
            state = null;
        }
        if (state == null)
        {
            Model[][] models = createModels(client, season);
            if (models == null) { return; }
            state = new State(client, world, scene, recolorer, season, models, count);
            STATES.put(owner, state);
        }
        state.center = point;
        state.refresh();
        for (Particle particle : state.particles)
        {
            if (!particle.isActive()) { particle.respawn(true); }
        }
    }

    static void clear(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return; }
        state.cleared = true;
        for (Particle particle : state.particles) { particle.setActive(false); }
    }

    static int getCount(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return 0; }
        int count = 0;
        for (Particle particle : state.particles) { if (particle.isActive()) { count++; } }
        return count;
    }

    private static Model[][] createModels(Client client, Season season)
    {
        ModelData source = client.loadModelData(27835);
        if (source == null || source.getVerticesCount() < 3 || source.getVerticesCount() > 8192
            || source.getFaceCount() == 0 || source.getFaceCount() > 8192) { return null; }
        Model[][] models = new Model[3][season == Season.SUMMER ? FRAMES : 1];
        for (int variant = 0; variant < models.length; variant++)
        {
            for (int frame = 0; frame < models[variant].length; frame++)
            {
                ModelData data = source.shallowCopy().cloneVertices().cloneColors();
                if (data.getFaceTextures() != null)
                {
                    data.cloneTextures();
                    Arrays.fill(data.getFaceTextures(), (short) -1);
                }
                data.cloneTransparencies(true);
                Arrays.fill(data.getFaceTransparencies(), (byte) (season == Season.SPRING ? 18 : 0));
                reshape(source, data, season, frame);
                int[] spring = {60 << 10 | 2 << 7 | 110, 58 << 10 | 3 << 7 | 100, 115};
                int[] summer = {7 << 10 | 6 << 7 | 76, 40 << 10 | 5 << 7 | 84, 13 << 10 | 3 << 7 | 108};
                Arrays.fill(data.getFaceColors(), (short) (season == Season.SPRING ? spring[variant] : summer[variant]));
                data.translate(0, 0, 0);
                models[variant][frame] = data.light(90, ModelData.DEFAULT_CONTRAST,
                    ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
            }
        }
        return models;
    }

    /** Keep one cache component and fold a small pair of wings; never edit cached topology. */
    static void reshape(ModelData source, ModelData target, Season season, int frame)
    {
        WinterSnowfall.reshape(source, target, 1);
        float[][] values = {target.getVerticesX(), target.getVerticesY(), target.getVerticesZ()};
        float[] spans = new float[3];
        for (int axis = 0; axis < 3; axis++)
        {
            for (float value : values[axis]) { spans[axis] = Math.max(spans[axis], Math.abs(value)); }
        }
        Integer[] axes = {0, 1, 2};
        Arrays.sort(axes, (a, b) -> Float.compare(spans[b], spans[a]));
        float[] u = values[axes[0]].clone(), v = values[axes[1]].clone();
        float fold = (float) (0.15 + 0.85 * (0.5 + 0.5 * Math.cos(frame * Math.PI * 2 / FRAMES)));
        for (int i = 0; i < target.getVerticesCount(); i++)
        {
            float across = u[i] / Math.max(0.001f, spans[axes[0]]);
            float along = v[i] / Math.max(0.001f, spans[axes[1]]);
            values[0][i] = across * (season == Season.SUMMER ? 9 * fold : 3.5f);
            values[1][i] = season == Season.SUMMER ? -Math.abs(across) * 9 * (1 - fold) : along * 1.5f;
            values[2][i] = along * (season == Season.SUMMER ? 6 : 5);
        }
    }

    private static final class State
    {
        final Client client;
        final WorldView world;
        final Scene scene;
        final SeasonalSceneRecolorer recolorer;
        final Season season;
        final int baseX, baseY;
        final Random random;
        final List<Particle> particles = new ArrayList<>();
        Tile[][][] tiles;
        byte[][][] flags;
        int[][] heights;
        LocalPoint center;
        boolean cleared;

        State(Client client, WorldView world, Scene scene, SeasonalSceneRecolorer recolorer,
            Season season, Model[][] models, int count)
        {
            this.client = client; this.world = world; this.scene = scene;
            this.recolorer = recolorer; this.season = season;
            baseX = scene.getBaseX(); baseY = scene.getBaseY();
            random = new Random(((long) baseX << 32) ^ baseY ^ season.ordinal());
            for (int i = 0; i < count; i++) { particles.add(new Particle(this, models[i % models.length])); }
        }

        void refresh()
        {
            tiles = scene.getTiles();
            flags = world.getTileSettings();
            int[][][] all = world.getTileHeights();
            heights = all == null || all.length == 0 ? null : all[0];
        }

        boolean meadow(int localX, int localY)
        {
            int x = localX >> 7, y = localY >> 7;
            if (x < 1 || y < 1 || tiles == null || tiles.length == 0 || tiles[0] == null
                || x >= tiles[0].length - 1 || tiles[0][x] == null || y >= tiles[0][x].length - 1)
            { return false; }
            Tile tile = tiles[0][x][y];
            return tile != null && tile.getRenderLevel() == 0 && tile.getBridge() == null
                && tile.getWallObject() == null && recolorer.isSeasonalGround(tile)
                && WinterSnowfall.clearSky(flags, x, y)
                && Float.isFinite(GroundCoverPlacement.height(heights, localX, localY));
        }
    }

    private static final class Particle extends RuneLiteObject
    {
        final State state;
        final Model[] frames;
        final float phase;
        float x, y, anchorX, anchorY, altitude, age;

        Particle(State state, Model[] frames)
        {
            super(state.client);
            this.state = state; this.frames = frames;
            phase = state.random.nextFloat() * 6.2831853f;
            setModel(frames[0]);
            setWorldView(state.world.getId());
            setLevel(0);
        }

        void respawn(boolean spread)
        {
            if (state.cleared || state.center == null) { return; }
            for (int attempt = 0; attempt < 16; attempt++)
            {
                double angle = state.random.nextDouble() * Math.PI * 2;
                double radius = Math.sqrt(state.random.nextDouble()) * RADIUS;
                x = state.center.getX() + (float) (Math.cos(angle) * radius);
                y = state.center.getY() + (float) (Math.sin(angle) * radius);
                if (!state.meadow((int) x, (int) y)) { continue; }
                anchorX = x; anchorY = y;
                altitude = state.season == Season.SPRING
                    ? (spread ? 40 + state.random.nextFloat() * 380 : 420) : 35;
                place();
                if (!isActive()) { setActive(true); }
                return;
            }
            setActive(false);
        }

        @Override
        public void tick(int ticksSinceLastFrame)
        {
            if (state.cleared || state.client.getGameState() != GameState.LOGGED_IN
                || state.world.getScene() != state.scene || state.world.getPlane() != 0)
            { setActive(false); return; }
            Player player = state.client.getLocalPlayer();
            LocalPoint point = player == null ? null : player.getLocalLocation();
            if (point == null || point.getWorldView() != getWorldView()
                || !WinterSnowfall.clearSky(state.flags, point.getSceneX(), point.getSceneY()))
            { setActive(false); return; }
            state.center = point;
            int elapsed = Math.max(0, Math.min(10, ticksSinceLastFrame));
            if (elapsed == 0) { return; }
            age += elapsed;
            if (state.season == Season.SPRING)
            {
                altitude -= elapsed * 0.7f;
                x += elapsed * (0.3f + 0.55f * (float) Math.sin(age * 0.03f + phase));
                y += elapsed * 0.35f * (float) Math.cos(age * 0.025f + phase);
                setOrientation(((int) (age * 3 + phase * 300)) & 2047);
            }
            else
            {
                float previousX = x, previousY = y;
                x = anchorX + 46 * (float) Math.sin(age * 0.016f + phase);
                y = anchorY + 32 * (float) Math.sin(age * 0.023f + phase);
                altitude = 34 + 13 * (float) Math.sin(age * 0.05f + phase);
                setOrientation(((int) (Math.atan2(x - previousX, y - previousY) * 1024 / Math.PI)) & 2047);
                setModel(frames[((int) (age / 2 + phase * 4)) % frames.length]);
            }
            float dx = x - point.getX(), dy = y - point.getY();
            if (altitude < 6 || dx * dx + dy * dy > (RADIUS + 128f) * (RADIUS + 128f)
                || !state.meadow((int) x, (int) y))
            { respawn(false); return; }
            place();
        }

        private void place()
        {
            setX((int) x); setY((int) y);
            setZ(Math.round(GroundCoverPlacement.height(state.heights, (int) x, (int) y) - altitude));
        }
    }
}

package com.seasonalscape;

import net.runelite.api.JagexColor;

/** Turns independent cache mesh pieces into two small flowers per decoration. */
final class SeasonalFlowerGeometry
{
    private SeasonalFlowerGeometry()
    {
    }

    static boolean appliesTo(Season season)
    {
        return season == Season.SPRING || season == Season.SUMMER;
    }

    /**
     * Five radial petals and a center share the first six pieces of each flower.
     * Spring's last two pieces are fallen petals; summer's are crossed stems.
     * Source UVs and face indices stay intact, preserving the cache topology.
     */
    static void vertex(Season season, int variant, int piece, float u, float v,
        float[] x, float[] y, float[] z, int index)
    {
        int flower = piece / 8;
        int role = piece % 8;
        double rotation = variant * 0.71 + flower * 2.4;
        double placement = rotation + 0.4;
        float centerX = (float) Math.cos(placement) * 20;
        float centerZ = (float) Math.sin(placement) * 20;
        float headHeight = season == Season.SUMMER ? 18 + (variant + flower * 3) % 7 : 1.6f;
        float along;
        float across;
        float height;
        if (role < 5)
        {
            rotation += role * Math.PI * 2 / 5;
            along = 0.7f + (u + 0.5f) * (season == Season.SUMMER ? 6.5f : 5.5f);
            across = v * (season == Season.SUMMER ? 5.2f : 4.6f);
            height = headHeight + (1 - Math.abs(u * 2)) * 0.7f;
        }
        else if (role == 5)
        {
            along = u * 3.4f;
            across = v * 3.4f;
            height = headHeight + 0.8f;
        }
        else if (season == Season.SUMMER)
        {
            // Two narrow upright planes keep the stem legible from different
            // camera angles. A slight lean also gives each face some top area.
            rotation += (role - 6) * Math.PI / 2;
            along = (u + 0.5f) * 1.5f;
            across = v * 1.4f;
            height = 0.25f + (u + 0.5f) * headHeight;
        }
        else
        {
            rotation += role * 1.7;
            along = 9 + u * 5;
            across = v * 3.4f;
            height = 0.35f + (1 - Math.abs(u * 2)) * 0.5f;
        }
        float cosine = (float) Math.cos(rotation);
        float sine = (float) Math.sin(rotation);
        x[index] = centerX + along * cosine - across * sine;
        z[index] = centerZ + along * sine + across * cosine;
        y[index] = -height;
    }

    static short color(Season season, int variant, int piece)
    {
        int flower = piece / 8;
        int role = piece % 8;
        if (role == 5)
        {
            return JagexColor.packHSL(9, season == Season.SUMMER ? 5 : 3,
                season == Season.SUMMER ? 70 : 83);
        }
        if (season == Season.SUMMER)
        {
            if (role >= 6)
            {
                return JagexColor.packHSL(20, 3, 42);
            }
            // Each clump pairs a buttercup-yellow flower with a white daisy.
            return (flower + variant) % 2 == 0
                ? JagexColor.packHSL(10, 5, 87 + role % 2 * 3)
                : JagexColor.packHSL(9, 0, 110 + role % 2 * 3);
        }
        int shade = (flower + variant) % 3;
        if (shade == 0)
        {
            return JagexColor.packHSL(9, 0, 111 + role % 2 * 3);
        }
        return JagexColor.packHSL(shade == 1 ? 61 : 47, 2, 103 + role % 2 * 3);
    }
}

package com.seasonalscape;

/** Terrain grass includes the yellow-green hues and dark corners beneath trees. */
final class SeasonalGroundColors
{
    private SeasonalGroundColors() {}

    static boolean isGrass(int color)
    {
        if (color < 0 || color > 65535) { return false; }
        int hue = color >>> 10;
        int saturation = color >>> 7 & 7;
        int lightness = color & 127;
        // Grass blended beside Varrock's buildings reaches olive hues 8 and 9.
        // The neighboring stone and dirt paths use hue 7 and remain unchanged.
        return hue >= 8 && hue <= 28 && saturation >= 2
            && lightness >= 2 && lightness <= 118;
    }

    static int ground(int color, Season season)
    {
        if (season == Season.WINTER && isGrass(color))
        {
            // Preserve terrain lighting while covering shaded grass continuously.
            return 36 << 10 | 83 + (color & 127) * 28 / 100;
        }
        return SeasonalPalette.ground(color, season);
    }
}

package com.seasonalscape;

/** Pure Jagex HSL transforms. Textured faces must be excluded by the caller. */
final class SeasonalPalette
{
    private SeasonalPalette() {}

    static boolean isVegetation(int color)
    {
        if (color < 0 || color > 65535)
        {
            return false;
        }
        int hue = color >>> 10;
        int saturation = color >>> 7 & 7;
        int lightness = color & 127;
        return hue >= 12 && hue <= 28 && saturation >= 2
            && lightness >= 8 && lightness <= 118;
    }

    static int ground(int color, Season season)
    {
        // Grass extends into olive hues and deep tree shadows that are not
        // safe to classify as leaves on an object model.
        if (SeasonalGroundColors.isGrass(color))
        {
            int lightness = color & 127;
            if (season == Season.SPRING) { return pack(20, 4, lightness + 9); }
            if (season == Season.SUMMER) { return pack(17, 4, lightness + 4); }
        }
        return recolor(color, season, false);
    }

    static int foliage(int color, Season season)
    {
        return recolor(color, season, true);
    }

    private static int recolor(int color, Season season, boolean foliage)
    {
        if (!isVegetation(color))
        {
            return color;
        }
        int lightness = color & 127;
        switch (season)
        {
            case SPRING:
                return pack(21, 5, lightness + 12);
            case SUMMER:
                return pack(22, 5, lightness - 3);
            case AUTUMN:
                return pack(foliage ? 3 + (color >>> 10) % 7 : 9,
                    foliage ? 6 : 3, lightness + (foliage ? 7 : 2));
            case WINTER:
                return foliage ? pack(20, 1, 78 + lightness * 22 / 100)
                    : pack(36, 0, 83 + lightness * 28 / 100);
            default:
                return color;
        }
    }

    private static int pack(int hue, int saturation, int lightness)
    {
        return hue << 10 | saturation << 7 | Math.max(2, Math.min(126, lightness));
    }
}

