@PluginDescriptor(name = "SeasonalScape", description = "Seasonal outdoor terrain, trees and ground cover",
    tags = {"season", "spring", "summer", "autumn", "winter", "snow", "leaves", "flowers"})
public class SeasonalScapePlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private AudioPlayer audioPlayer;
    @Inject private SeasonalScapeConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private SeasonalStatusOverlay overlay;

    private SeasonalSceneRecolorer recolorer;
    private GroundCover groundCover;
    private Scene lastScene;
    private DrawCallbacks lastRenderer;
    private int lastPlane = -1;
    private volatile Season activeSeason;
    private volatile String status = "Log in to preview";
    private volatile boolean running;
    private volatile boolean dirty;

    @Provides
    SeasonalScapeConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(SeasonalScapeConfig.class);
    }

    @Override
    protected void startUp()
    {
        running = true;
        dirty = true;
        recolorer = new SeasonalSceneRecolorer(client);
        groundCover = new GroundCover(client);
        overlayManager.add(overlay);
        SeasonalWinterAudio.start(this, client, getInjector().getInstance(ConfigManager.class), audioPlayer);
        SeasonalSceneSync.start(this, client, () -> {
            if (running) { dirty = true; update(); }
        });
        clientThread.invoke(this::update);
    }

    @Override
    protected void shutDown()
    {
        running = false;
        SeasonalWinterAudio.stop(this);
        SeasonalSceneSync.stop(this);
        overlayManager.remove(overlay);
        // Capture this session's state so a quick re-enable cannot restore a newer session.
        GroundCover oldCover = groundCover;
        SeasonalSceneRecolorer oldRecolorer = recolorer;
        clientThread.invoke(() -> {
            if (oldCover != null) { oldCover.clear(); }
            if (oldRecolorer != null) { SeasonalAir.clear(oldRecolorer); }
            if (oldRecolorer != null) { oldRecolorer.restore(); }
        });
        lastScene = null;
        lastRenderer = null;
        lastPlane = -1;
        activeSeason = null;
        status = "Disabled";
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        update();
        if (running && activeSeason == Season.WINTER && recolorer != null)
        {
            WorldView world = client.getTopLevelWorldView();
            WinterSnowfall.update(recolorer, client, world == null ? null : world.getScene());
            if (config.foliage()) { WinterTreeFrost.refresh(recolorer, client); }
        }
        else if (recolorer != null)
        {
            WinterSnowfall.clear(recolorer);
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        dirty = true;
        SeasonalSceneSync.requestRefresh(this);
    }

    @Subscribe(priority = 100)
    public void onPostClientTick(PostClientTick event)
    {
        // Spread surface work across client ticks, before GPU's zone uploads.
        if (running && recolorer != null)
        {
            WinterSurfaceSnow.tick(recolorer);
            WinterTreeFrost.tick(recolorer);
        }
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        if (recolorer != null) { WinterTreeFrost.remove(recolorer, event.getGameObject()); }
        dirty = true;
        SeasonalSceneSync.requestRefresh(this);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (SeasonalScapeConfig.GROUP.equals(event.getGroup())
            && "winterStructureSnow".equals(event.getKey()))
        {
            clientThread.invoke(() -> {
                if (!running || recolorer == null) { return; }
                // Remove existing coatings even during a map load. The normal
                // update recreates them only when enabled and the scene is ready.
                if (!config.winterStructureSnow()) { WinterSurfaceSnow.restore(recolorer); }
                else { update(); }
            });
            return;
        }
        if (SeasonalScapeConfig.GROUP.equals(event.getGroup())
            && ("winterAudio".equals(event.getKey()) || "winterAudioVolume".equals(event.getKey())))
        {
            // Sound controls do not require rebuilding any scene geometry.
            return;
        }
        if (SeasonalScapeConfig.GROUP.equals(event.getGroup())
            || ("gpu".equals(event.getGroup()) && "brightTextures".equals(event.getKey())))
        {
            dirty = true;
            clientThread.invoke(() -> { if (running) { recolorer.restore(); update(); } });
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        dirty = true;
        SeasonalWinterAudio.update(this, activeSeason, running);
        SeasonalSceneSync.requestRefresh(this);
        if (event.getGameState() != GameState.LOGGED_IN && recolorer != null)
        {
            SeasonalAir.clear(recolorer);
            WinterTreeFrost.restore(recolorer);
        }
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
        {
            groundCover.clear();
            recolorer.restore();
            lastScene = null;
            status = "Log in to preview";
        }
        else if (event.getGameState() == GameState.LOGGED_IN)
        {
            // Refresh a completed scene immediately instead of exposing its
            // original colors until the next server game tick.
            update();
        }
    }

    private void update()
    {
        if (!running || client.getGameState() != GameState.LOGGED_IN) { return; }
        WorldView view = client.getTopLevelWorldView();
        if (view == null || view.getScene() == null || client.getLocalPlayer() == null) { return; }
        Scene scene = view.getScene();
        Season season = SeasonResolver.resolve(config.season(), config.hemisphere(), Clock.systemDefaultZone(), config.timeZone());
        DrawCallbacks renderer = client.getDrawCallbacks();
        if (renderer != null && !(renderer instanceof GpuPlugin))
        {
            groundCover.clear();
            SeasonalAir.clear(recolorer);
            recolorer.restore();
            lastScene = null;
            activeSeason = season;
            SeasonalWinterAudio.update(this, season, running);
            status = "Use default graphics or GPU";
            return;
        }
        if (dirty || scene != lastScene || season != activeSeason || renderer != lastRenderer
            || view.getPlane() != lastPlane)
        {
            // Packed texture tints are valid only in GPU's bright-texture mode.
            // Switching renderer must restore them before software draws again.
            if (renderer != lastRenderer) { recolorer.restore(); }
            recolorer.apply(scene, season, config.terrain(), config.foliage());
            WinterSurfaceSnow.markDirty(recolorer);
            groundCover.invalidate();
            if (scene != lastScene || season != activeSeason) { groundCover.clear(); }
            lastScene = scene;
            lastRenderer = renderer;
            lastPlane = view.getPlane();
            activeSeason = season;
            dirty = false;
        }
        SeasonalWinterAudio.update(this, season, running);
        WinterSurfaceSnow.update(recolorer, client, scene,
            season == Season.WINTER && config.terrain() && config.winterStructureSnow());
        groundCover.update(scene, recolorer, season, config.groundCover(), config.density());
        SeasonalAir.update(recolorer, client, scene, recolorer, season, config.seasonalAir(), config.density());
        int x = client.getLocalPlayer().getWorldLocation().getX();
        int y = client.getLocalPlayer().getWorldLocation().getY();
        boolean inArea = SeasonalSceneRecolorer.supports(scene) && view.getPlane() == 0
            && SeasonalWorldArea.contains(x, y);
        status = inArea ? "Seasonal world active" : "Outdoor main-overworld areas only";
    }

    Season getActiveSeason() { return activeSeason; }
    String getStatus() { return status; }
}

package com.seasonalscape;

import java.lang.ref.WeakReference;
import java.util.Arrays;
import java.util.BitSet;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Client-thread-only seasonal changes to existing scene colors. */
public final class SeasonalSceneRecolorer
{
    private final Client client;
    private final Map<SceneTilePaint, Colors> paints = new WeakHashMap<>();
    // Arrays have identity equality; weak keys release models evicted from the game cache.
    private final Map<int[], Colors> arrays = new WeakHashMap<>();
    private final Set<Tile> ground = Collections.newSetFromMap(new WeakHashMap<>());
    private WeakReference<Scene> activeScene = new WeakReference<>(null);
    private final BitSet zones = new BitSet();
    private Season previousSeason;
    private boolean previousTerrain, previousFoliage, previousTextureTint, changedModels;
    private int changedTiles, changedTrees;
    private long mutationVersion;

    public SeasonalSceneRecolorer(Client client)
    {
        this.client = client;
    }

    public static boolean supports(Scene scene)
    {
        return scene != null && scene.getWorldViewId() == WorldView.TOPLEVEL && !scene.isInstance();
    }

    public void apply(Scene scene, Season season, boolean terrain, boolean foliage)
    {
        // Face tints preserve texture pixels and cutouts. Winter keeps textured
        // leaves unchanged; whitening them requires a supported material API.
        boolean tintTextures = foliage && season != Season.WINTER && SeasonalTextureTint.supported(client);
        if (scene != activeScene.get() || season != previousSeason
            || terrain != previousTerrain || foliage != previousFoliage || tintTextures != previousTextureTint)
        {
            restore();
        }
        changedTiles = changedTrees = 0;
        ground.clear();
        if (!supports(scene))
        {
            restore();
            return;
        }
        activeScene = new WeakReference<>(scene);
        previousSeason = season;
        previousTerrain = terrain;
        previousFoliage = foliage;
        previousTextureTint = tintTextures;
        Set<GameObject> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        Set<GameObject> affectedTrees = Collections.newSetFromMap(new IdentityHashMap<>());
        Tile[][][] tiles = scene.getExtendedTiles();
        if (tiles == null || tiles.length == 0 || tiles[0] == null)
        {
            WinterTreeFrost.restore(this);
            return;
        }
        int width = tiles[0].length;
        if (season == Season.WINTER && foliage) { WinterTreeFrost.begin(this); }
        BitSet dirty = new BitSet();
        BitSet treeZones = new BitSet();
        boolean treesMutated = false;
        boolean grassMutated = false;
        for (int x = 0; x < width; x++)
        {
            if (tiles[0][x] == null) { continue; }
            for (int y = 0; y < tiles[0][x].length; y++)
            {
                Tile tile = tiles[0][x][y];
                if (!outdoors(scene, tile, x, y)) { continue; }
                long before = mutationVersion;
                if (hasGrass(tile))
                {
                    ground.add(tile);
                    if (terrain && recolorGround(tile, season))
                    {
                        changedTiles++;
                    }
                    if (terrain && season == Season.WINTER && tile.getGroundObject() != null
                        && tile.getGroundObject().getRenderable() instanceof Model)
                    {
                        Model blades = (Model) tile.getGroundObject().getRenderable();
                        short[] textures = blades.getFaceTextures();
                        int[][] channels = {blades.getFaceColors1(), blades.getFaceColors2(), blades.getFaceColors3()};
                        long beforeGrass = mutationVersion;
                        boolean affectedGrass = false;
                        for (int[] channel : channels)
                        {
                            int[] source = original(channel);
                            for (int face = 0; face < channel.length; face++)
                            {
                                // Terrain also includes olive underlays, but
                                // those hues can be brown ground decorations.
                                if ((textures == null || textures[face] < 0)
                                    && (source[face] >>> 10) >= 10)
                                {
                                    affectedGrass |= change(channel, face,
                                        SeasonalGroundColors.ground(source[face], season));
                                }
                            }
                        }
                        if (affectedGrass)
                        {
                            changedModels = true;
                        }
                        grassMutated |= mutationVersion != beforeGrass;
                    }
                }
                int zone = (x >> 3) * zoneWidth(scene) + (y >> 3);
                if (mutationVersion != before) { dirty.set(zone); }
                if (foliage && tile.getGameObjects() != null)
                {
                    for (GameObject object : tile.getGameObjects())
                    {
                        before = mutationVersion;
                        if (object != null && seen.add(object) && recolorTree(object, season, tintTextures))
                        {
                            changedTrees++;
                            changedModels = true;
                            affectedTrees.add(object);
                        }
                        treesMutated |= mutationVersion != before;
                        if (affectedTrees.contains(object)) { markTreeZones(scene, object, treeZones); }
                    }
                }
            }
        }
        if (season == Season.WINTER && foliage) { WinterTreeFrost.end(this); }
        // Shared model colors and multi-tile objects can affect several upload zones.
        if (treesMutated) { dirty.or(treeZones); }
        if (grassMutated)
        {
            // Cached ground models can share face colors with placements on
            // roads or under roofs, outside the grass tiles visited above.
            // Rebuild every uploaded copy when those shared arrays change.
            int zoneCount = zoneWidth(scene);
            dirty.set(0, zoneCount * zoneCount);
        }
        zones.or(dirty);
        invalidate(scene, dirty);
    }

    public boolean isSeasonalGround(Tile tile)
    {
        return ground.contains(tile) && hasGrass(tile);
    }

    public int getChangedTiles() { return changedTiles; }
    public int getChangedTrees() { return changedTrees; }

    private boolean outdoors(Scene scene, Tile tile, int x, int y)
    {
        if (tile == null || tile.getPlane() != 0 || tile.getRenderLevel() != 0 || tile.getBridge() != null)
        {
            return false;
        }
        int wx = scene.getBaseX() + tile.getSceneLocation().getX();
        int wy = scene.getBaseY() + tile.getSceneLocation().getY();
        if (!SeasonalWorldArea.contains(wx, wy)) { return false; }
        byte[][][] flags = scene.getExtendedTileSettings();
        if (flags == null) { return false; }
        for (int plane = 1; plane < flags.length; plane++)
        {
            if (flags[plane] == null || x >= flags[plane].length || flags[plane][x] == null
                || y >= flags[plane][x].length) { return false; }
            int value = flags[plane][x][y];
            if ((value & 4) != 0 || (plane == 1 && (value & 2) != 0)) { return false; }
        }
        return true;
    }

    private boolean hasGrass(Tile tile)
    {
        SceneTilePaint paint = tile.getSceneTilePaint();
        if (paint != null)
        {
            if (paint.getTexture() >= 0) { return false; }
            Colors saved = paints.get(paint);
            int[] colors = saved == null ? paintColors(paint) : saved.original;
            return Arrays.stream(colors).allMatch(SeasonalGroundColors::isGrass);
        }
        SceneTileModel model = tile.getSceneTileModel();
        if (model == null || textured(model.getTriangleTextureId())) { return false; }
        int[] a = original(model.getTriangleColorA());
        int[] b = original(model.getTriangleColorB());
        int[] c = original(model.getTriangleColorC());
        for (int i = 0; i < a.length; i++)
        {
            if (SeasonalGroundColors.isGrass(a[i]) && SeasonalGroundColors.isGrass(b[i])
                && SeasonalGroundColors.isGrass(c[i])) { return true; }
        }
        return false;
    }

    private boolean recolorGround(Tile tile, Season season)
    {
        SceneTilePaint paint = tile.getSceneTilePaint();
        if (paint != null)
        {
            int[] current = paintColors(paint);
            Colors colors = paints.computeIfAbsent(paint, ignored -> new Colors(current));
            boolean affected = false;
            for (int i = 0; i < 4; i++)
            {
                affected |= colors.apply(current, i, SeasonalGroundColors.ground(colors.original[i], season));
            }
            if (!Arrays.equals(current, paintColors(paint))) { mutationVersion++; }
            setPaint(paint, current);
            return affected;
        }
        SceneTileModel model = tile.getSceneTileModel();
        int[] a = model.getTriangleColorA(), b = model.getTriangleColorB(), c = model.getTriangleColorC();
        int[] oa = arrays.computeIfAbsent(a, Colors::new).original;
        int[] ob = arrays.computeIfAbsent(b, Colors::new).original;
        int[] oc = arrays.computeIfAbsent(c, Colors::new).original;
        boolean affected = false;
        for (int i = 0; i < a.length; i++)
        {
            if (SeasonalGroundColors.isGrass(oa[i]) && SeasonalGroundColors.isGrass(ob[i])
                && SeasonalGroundColors.isGrass(oc[i]))
            {
                affected |= change(a, i, SeasonalGroundColors.ground(oa[i], season));
                affected |= change(b, i, SeasonalGroundColors.ground(ob[i], season));
                affected |= change(c, i, SeasonalGroundColors.ground(oc[i], season));
            }
        }
        return affected;
    }

    private boolean recolorTree(GameObject object, Season season, boolean tintTextures)
    {
        if (!(object.getRenderable() instanceof Model)) { return false; }
        ObjectComposition definition = client.getObjectDefinition(object.getId());
        if (definition == null || !Arrays.asList("Tree", "Oak", "Oak tree", "Willow", "Willow tree",
            "Yew", "Yew tree", "Maple tree")
            .contains(definition.getName())) { return false; }
        Model model = (Model) object.getRenderable();
        if (season == Season.WINTER) { WinterTreeFrost.update(this, client, object, model); }
        short[] textures = model.getFaceTextures();
        int[][] channels = {model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3()};
        boolean affected = false;
        for (int[] channel : channels)
        {
            int[] source = original(channel);
            for (int i = 0; i < channel.length; i++)
            {
                if (textures == null || textures[i] < 0)
                {
                    affected |= change(channel, i, SeasonalPalette.foliage(source[i], season));
                }
                else if (tintTextures && SeasonalTextureTint.isLeafTexture(textures[i]))
                {
                    affected |= change(channel, i, SeasonalTextureTint.foliage(source[i], textures[i], season));
                }
            }
        }
        return affected;
    }

    private int[] original(int[] current)
    {
        Colors saved = arrays.get(current);
        return saved == null ? current : saved.original;
    }

    private boolean change(int[] current, int index, int value)
    {
        if (value == current[index] && !arrays.containsKey(current)) { return false; }
        int before = current[index];
        boolean affected = arrays.computeIfAbsent(current, Colors::new).apply(current, index, value);
        if (current[index] != before) { mutationVersion++; }
        return affected;
    }

    public void restore()
    {
        WinterSnowfall.clear(this);
        WinterSurfaceSnow.restore(this);
        WinterTreeFrost.restore(this);
        for (Map.Entry<SceneTilePaint, Colors> entry : paints.entrySet())
        {
            int[] current = paintColors(entry.getKey());
            entry.getValue().restore(current);
            setPaint(entry.getKey(), current);
        }
        for (Map.Entry<int[], Colors> entry : arrays.entrySet()) { entry.getValue().restore(entry.getKey()); }
        WinterCanopySnow.restore(this);
        Scene scene = currentScene();
        if (changedModels && scene != null)
        {
            // Any zone may contain another placement of a cached recolored
            // model, including zones uploaded after the original mutation.
            // Restore their GPU copies even if the Scene object is unchanged.
            BitSet all = new BitSet();
            all.set(0, zoneWidth(scene) * zoneWidth(scene));
            invalidate(scene, all);
        }
        else { invalidate(activeScene.get(), zones); }
        paints.clear();
        arrays.clear();
        ground.clear();
        zones.clear();
        activeScene.clear();
        changedModels = false;
        changedTiles = changedTrees = 0;
    }

    private Scene currentScene()
    {
        WorldView world = client.getTopLevelWorldView();
        return world == null ? null : world.getScene();
    }

    private void markTreeZones(Scene scene, GameObject object, BitSet dirty)
    {
        int width = zoneWidth(scene);
        int offset = (scene.getExtendedTiles()[0].length - Constants.SCENE_SIZE) / 2;
        int minX = Math.max(0, (object.getSceneMinLocation().getX() + offset) >> 3);
        int minY = Math.max(0, (object.getSceneMinLocation().getY() + offset) >> 3);
        int maxX = Math.min(width - 1, (object.getSceneMaxLocation().getX() + offset) >> 3);
        int maxY = Math.min(width - 1, (object.getSceneMaxLocation().getY() + offset) >> 3);
        for (int x = minX; x <= maxX; x++)
        {
            for (int y = minY; y <= maxY; y++) { dirty.set(x * width + y); }
        }
    }

    private int zoneWidth(Scene scene)
    {
        Tile[][][] tiles = scene.getExtendedTiles();
        return tiles == null || tiles.length == 0 || tiles[0] == null ? 0 : (tiles[0].length + 7) >> 3;
    }

    private void invalidate(Scene scene, BitSet dirty)
    {
        DrawCallbacks callbacks = client.getDrawCallbacks();
        if (scene == null || scene != currentScene() || !(callbacks instanceof GpuPlugin)) { return; }
        int width = zoneWidth(scene);
        if (width == 0) { return; }
        for (int bit = dirty.nextSetBit(0); bit >= 0; bit = dirty.nextSetBit(bit + 1))
        {
            callbacks.invalidateZone(scene, bit / width, bit % width);
        }
    }

    private static boolean textured(int[] textures)
    {
        return textures != null && Arrays.stream(textures).anyMatch(texture -> texture >= 0);
    }

    private static int[] paintColors(SceneTilePaint p)
    {
        return new int[]{p.getSwColor(), p.getSeColor(), p.getNeColor(), p.getNwColor()};
    }

    private static void setPaint(SceneTilePaint p, int[] colors)
    {
        p.setSwColor(colors[0]); p.setSeColor(colors[1]); p.setNeColor(colors[2]); p.setNwColor(colors[3]);
    }

    static final class Colors
    {
        private final int[] original, last;
        private final BitSet conflicted = new BitSet();
        Colors(int[] colors) { original = colors.clone(); last = colors.clone(); }

        boolean apply(int[] current, int index, int desired)
        {
            if (current[index] != last[index]) { conflicted.set(index); }
            if (conflicted.get(index)) { return false; }
            current[index] = last[index] = desired;
            return desired != original[index];
        }

        void restore(int[] current)
        {
            for (int i = 0; i < current.length; i++)
            {
                if (!conflicted.get(i) && current[i] == last[i]) { current[i] = original[i]; }
            }
        }
    }
}

package com.seasonalscape;

import java.util.Map;
import java.util.Objects;
import java.util.WeakHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PostClientTick;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/** Refreshes a newly loaded scene before rendering, without rescanning stable frames. */
final class SeasonalSceneSync
{
    private static final Map<Object, SeasonalSceneSync> STATES = new WeakHashMap<>();

    private final EventBus eventBus;
    private final Client client;
    private final Runnable refresh;
    private final AtomicBoolean pending = new AtomicBoolean(true);
    private volatile boolean active = true;
    private Scene lastScene;
    private int baseX;
    private int baseY;

    SeasonalSceneSync(EventBus eventBus, Client client, Runnable refresh)
    {
        this.eventBus = Objects.requireNonNull(eventBus);
        this.client = Objects.requireNonNull(client);
        this.refresh = Objects.requireNonNull(refresh);
        eventBus.register(this);
    }

    static void start(Object owner, Client client, Runnable refresh)
    {
        start(owner, client, refresh, RuneLite.getInjector().getInstance(EventBus.class));
    }

    /** Event-bus injection keeps lifecycle tests independent of a RuneLite process. */
    static void start(Object owner, Client client, Runnable refresh, EventBus eventBus)
    {
        Objects.requireNonNull(owner);
        synchronized (STATES)
        {
            SeasonalSceneSync previous = STATES.remove(owner);
            if (previous != null) { previous.close(); }
            STATES.put(owner, new SeasonalSceneSync(eventBus, client, refresh));
        }
    }

    static void requestRefresh(Object owner)
    {
        synchronized (STATES)
        {
            SeasonalSceneSync state = STATES.get(owner);
            if (state != null) { state.pending.set(true); }
        }
    }

    static void stop(Object owner)
    {
        synchronized (STATES)
        {
            SeasonalSceneSync state = STATES.remove(owner);
            if (state != null) { state.close(); }
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        // Loading events only request work. Scene reads and recoloring stay on
        // the client thread after the complete scene becomes available.
        if (active) { pending.set(true); }
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (!active || !client.isClientThread() || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        WorldView world = client.getTopLevelWorldView();
        Scene scene = world == null ? null : world.getScene();
        if (scene == null || client.getLocalPlayer() == null) { return; }
        int currentBaseX = scene.getBaseX();
        int currentBaseY = scene.getBaseY();
        boolean changed = scene != lastScene || currentBaseX != baseX || currentBaseY != baseY;
        if (!pending.getAndSet(false) && !changed) { return; }

        try
        {
            refresh.run();
            lastScene = scene;
            baseX = currentBaseX;
            baseY = currentBaseY;
        }
        catch (RuntimeException | Error error)
        {
            pending.set(true);
            throw error;
        }
    }

    @Subscribe(priority = 100)
    public void onPostClientTick(PostClientTick event)
    {
        // GPU rebuilds invalidated zones at default priority on this event.
        // Recolor first so it uploads the seasonal version before drawing.
        onBeforeRender(null);
    }

    private void close()
    {
        active = false;
        eventBus.unregister(this);
        lastScene = null;
    }
}

package com.seasonalscape;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class SeasonalStatusOverlay extends OverlayPanel
{
    private final SeasonalScapePlugin plugin;
    private final SeasonalScapeConfig config;
    private final Client client;

    @Inject
    SeasonalStatusOverlay(SeasonalScapePlugin plugin, SeasonalScapeConfig config, Client client)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showStatus() || client.getGameState() != GameState.LOGGED_IN) { return null; }
        panelComponent.setPreferredSize(new Dimension(245, 0));
        panelComponent.getChildren().add(TitleComponent.builder().text("SeasonalScape").color(new Color(224, 190, 114)).build());
        Season season = plugin.getActiveSeason();
        panelComponent.getChildren().add(LineComponent.builder().left("Season").right(season == null ? "Loading" : season.toString()).build());
        panelComponent.getChildren().add(LineComponent.builder().left(plugin.getStatus()).build());
        return super.render(graphics);
    }
}

package com.seasonalscape;

import net.runelite.api.Client;
import net.runelite.client.plugins.gpu.GpuPlugin;
import net.runelite.client.plugins.gpu.GpuPluginConfig;

/** GPU's bright-texture mode multiplies texture pixels by the face HSL color. */
final class SeasonalTextureTint
{
    private SeasonalTextureTint() {}

    static boolean supported(Client client)
    {
        if (!(client.getDrawCallbacks() instanceof GpuPlugin)) { return false; }
        GpuPlugin gpu = (GpuPlugin) client.getDrawCallbacks();
        return gpu.getInjector() != null
            && gpu.getInjector().getInstance(GpuPluginConfig.class).brightTextures();
    }

    static boolean isLeafTexture(int texture)
    {
        // Verified foliage textures in RuneLite 1.13.1's current game cache.
        return texture == 8 || texture == 30 || texture == 60;
    }

    static int autumn(int brightness, int texture)
    {
        // Negative values are face sentinels. Already-colored values belong to
        // another renderer/plugin and must not be interpreted as brightness.
        if (brightness < 0 || brightness > 127) { return brightness; }
        int hue = texture == 30 ? 6 : texture == 60 ? 4 : 5;
        int lightness = 24 + brightness * 64 / 127;
        return hue << 10 | 6 << 7 | lightness;
    }

    static int foliage(int brightness, int texture, Season season)
    {
        // Keep the cutout texture itself untouched; GPU multiplies its pixels
        // by this face tint, preserving the spaces between leaves.
        if (!isLeafTexture(texture) || brightness < 0 || brightness > 127) { return brightness; }
        switch (season)
        {
            case SPRING:
                return (texture == 30 ? 20 : 21) << 10 | 4 << 7
                    | 34 + brightness * 64 / 127;
            case SUMMER:
                return (texture == 30 ? 21 : 22) << 10 | 5 << 7
                    | 26 + brightness * 60 / 127;
            case AUTUMN:
                return autumn(brightness, texture);
            default:
                return brightness;
        }
    }
}

package com.seasonalscape;

import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Map;
import java.util.Random;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.config.ConfigManager;
import org.slf4j.LoggerFactory;

/** Optional, locally generated ambience. Device I/O never runs on the client or UI thread. */
final class SeasonalWinterAudio
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();
    private static final String GROUP = "seasonalscape";
    private static final String ENABLED = "winterAudio";
    private static final String VOLUME = "winterAudioVolume";
    private static final int SAMPLE_RATE = 22050;
    private static final int CHUNK_FRAMES = SAMPLE_RATE / 4;
    private static final long CHUNK_NANOS = CHUNK_FRAMES * 1_000_000_000L / SAMPLE_RATE;

    private SeasonalWinterAudio() {}

    static synchronized void start(Object owner, Client client, ConfigManager configs, AudioPlayer audioPlayer)
    {
        stop(owner);
        State state = new State(client, configs, audioPlayer);
        STATES.put(owner, state);
        state.readSettings();
        state.worker.start();
    }

    /** Call on the client thread; the audio worker reads only the resulting snapshot. */
    static synchronized void update(Object owner, Season season, boolean running)
    {
        State state = STATES.get(owner);
        if (state == null) { return; }
        GameState game = state.client.getGameState();
        state.inWorld = game == GameState.LOGGED_IN || (game == GameState.LOADING && state.inWorld);
        state.winter = running && season == Season.WINTER;
        state.readSettings();
    }

    static synchronized void stop(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return; }
        state.closed = true;
        state.signal();
        // AudioPlayer owns playback and exposes no stop handle. Stop submitting
        // new chunks; an already-started clip may finish its remaining <=250 ms.
    }

    static synchronized boolean isPlaying(Object owner)
    {
        State state = STATES.get(owner);
        return state != null && state.playing;
    }

    static synchronized String getStatus(Object owner)
    {
        State state = STATES.get(owner);
        return state == null ? "Disabled" : state.status();
    }

    /** Small in-memory PCM WAVs let RuneLite own all access to the audio device. */
    static byte[] wave(byte[] pcm)
    {
        if ((pcm.length & 3) != 0) { throw new IllegalArgumentException("Stereo PCM requires complete frames"); }
        return ByteBuffer.allocate(44 + pcm.length).order(ByteOrder.LITTLE_ENDIAN)
            .putInt(0x46464952).putInt(36 + pcm.length).putInt(0x45564157)
            .putInt(0x20746d66).putInt(16).putShort((short) 1).putShort((short) 2)
            .putInt(SAMPLE_RATE).putInt(SAMPLE_RATE * 4).putShort((short) 4).putShort((short) 16)
            .putInt(0x61746164).putInt(pcm.length).put(pcm).array();
    }

    static boolean hasSignal(byte[] pcm)
    {
        for (byte value : pcm) { if (value != 0) { return true; } }
        return false;
    }

    /** A two-millisecond edge fade avoids clicks between separately owned clips. */
    static void softenEdges(byte[] pcm)
    {
        int frames = pcm.length / 4;
        int fade = Math.min(SAMPLE_RATE / 500, frames / 2);
        for (int frame = 0; frame < fade; frame++)
        {
            double gain = frame / (double) fade;
            for (int channel = 0; channel < 2; channel++)
            {
                for (int offset : new int[]{frame * 4 + channel * 2, (frames - frame - 1) * 4 + channel * 2})
                {
                    int sample = (short) ((pcm[offset] & 255) | (pcm[offset + 1] << 8));
                    int scaled = (int) Math.round(sample * gain);
                    pcm[offset] = (byte) scaled;
                    pcm[offset + 1] = (byte) (scaled >> 8);
                }
            }
        }
    }

    static final class State
    {
        final Client client;
        final ConfigManager configs;
        final AudioPlayer audioPlayer;
        final Object wake = new Object();
        final Thread worker;
        volatile boolean enabled, inWorld, winter, closed, playing, failed;
        volatile int volume = 25;

        State(Client client, ConfigManager configs, AudioPlayer audioPlayer)
        {
            this.client = client;
            this.configs = configs;
            this.audioPlayer = audioPlayer;
            worker = new Thread(this::run, "SeasonalScape winter audio");
            worker.setDaemon(true);
        }

        synchronized void readSettings()
        {
            boolean nextEnabled = Boolean.parseBoolean(configs.getConfiguration(GROUP, ENABLED));
            if (nextEnabled && !enabled) { failed = false; }
            enabled = nextEnabled;
            String storedVolume = configs.getConfiguration(GROUP, VOLUME);
            try { volume = storedVolume == null ? 25 : Math.max(0, Math.min(100, Integer.parseInt(storedVolume))); }
            catch (NumberFormatException ignored) { volume = 25; }
            signal();
        }

        boolean wanted() { return !closed && enabled && winter && inWorld && volume > 0 && !failed; }

        String status()
        {
            if (closed) { return "Disabled"; }
            if (!enabled) { return "Winter audio is off"; }
            if (failed) { return "Audio unavailable. Toggle off and on to retry."; }
            if (!inWorld) { return "Ready when you log in"; }
            if (!winter) { return "Ready when winter is active"; }
            if (volume == 0) { return "Muted"; }
            return playing ? "Occasional snow and ice sounds are enabled" : "Starting winter ambience";
        }

        void signal() { synchronized (wake) { wake.notifyAll(); } }

        void run()
        {
            while (!closed)
            {
                synchronized (wake)
                {
                    while (!closed && !wanted())
                    {
                        try { wake.wait(); }
                        catch (InterruptedException ignored) { /* Recheck lifecycle state. */ }
                    }
                }
                if (closed) { return; }
                play();
            }
        }

        void play()
        {
            play(new SnowSound(0x534e4f5741554449L));
        }

        void play(SnowSound sound)
        {
            try
            {
                if (!wanted()) { return; }
                playing = true;
                byte[] buffer = new byte[CHUNK_FRAMES * 4];
                while (wanted())
                {
                    sound.render(buffer, volume / 100f * 0.8f);
                    if (!wanted()) { break; }
                    if (hasSignal(buffer))
                    {
                        softenEdges(buffer);
                        try (ByteArrayInputStream input = new ByteArrayInputStream(wave(buffer)))
                        {
                            // AudioPlayer's gain is decibels. Volume is already
                            // applied to PCM, so leave device gain at unity.
                            audioPlayer.play(input, 0);
                        }
                    }
                    // AudioPlayer starts a finite clip asynchronously. Pace even
                    // silent chunks, from completion of this submission, so a
                    // slow device never triggers a burst of catch-up playback.
                    if (!awaitChunk(System.nanoTime() + CHUNK_NANOS)) { break; }
                }
            }
            catch (Exception error)
            {
                failed = true;
                LoggerFactory.getLogger(SeasonalWinterAudio.class)
                    .warn("Winter ambience audio output is unavailable: {}", error.toString());
            }
            finally
            {
                playing = false;
            }
        }

        boolean awaitChunk(long deadline)
        {
            synchronized (wake)
            {
                while (wanted())
                {
                    long remaining = deadline - System.nanoTime();
                    if (remaining <= 0) { return true; }
                    try { wake.wait(remaining / 1_000_000L, (int) (remaining % 1_000_000L)); }
                    catch (InterruptedException ignored) { /* Recheck lifecycle and monotonic deadline. */ }
                }
            }
            return false;
        }
    }

    /** Deterministic, isolated snow-settling accents and faint icy overtones, with silent gaps. */
    static final class SnowSound
    {
        private static final int SNOW_FRAMES = SAMPLE_RATE * 3 / 4;
        private static final int ICE_FRAMES = SAMPLE_RATE * 4;
        private static final int ICE_FADE_FRAMES = SAMPLE_RATE / 4;
        private final Random random;
        private double snowLeft, snowRight, gain, chime, chimePhase, chimeStep;
        private int snowFrame = SNOW_FRAMES;
        private int iceFrame = ICE_FRAMES;
        private long sample;
        private long nextSnow = SAMPLE_RATE * 4L;
        private long nextChime = SAMPLE_RATE * 9L;

        SnowSound(long seed) { random = new Random(seed); }

        boolean isSilent() { return gain < 0.0001; }

        void render(byte[] pcm, float desiredGain)
        {
            if ((pcm.length & 3) != 0) { throw new IllegalArgumentException("Stereo PCM requires complete frames"); }
            double target = Float.isFinite(desiredGain) ? Math.max(0, Math.min(0.8, desiredGain)) : 0;
            for (int offset = 0; offset < pcm.length; offset += 4, sample++)
            {
                gain += (target - gain) * 0.001;
                if (target == 0 && gain < 0.0001) { gain = 0; }
                if (sample >= nextSnow)
                {
                    snowFrame = 0;
                    snowLeft = snowRight = 0;
                    nextSnow = sample + SAMPLE_RATE * (20L + random.nextInt(15));
                }
                if (sample >= nextChime)
                {
                    chime = 0.008;
                    iceFrame = 0;
                    chimePhase = 0;
                    chimeStep = (1800 + random.nextDouble() * 1400) * Math.PI * 2 / SAMPLE_RATE;
                    nextChime = sample + SAMPLE_RATE * (14 + random.nextInt(12));
                }
                double left = 0, right = 0;
                if (snowFrame < SNOW_FRAMES)
                {
                    // A small, muffled powder fall with a finite envelope; no continuous noise bed.
                    snowLeft += ((random.nextDouble() * 2 - 1) - snowLeft) * 0.12;
                    snowRight += ((random.nextDouble() * 2 - 1) - snowRight) * 0.12;
                    double progress = snowFrame++ / (double) (SNOW_FRAMES - 1);
                    double envelope = Math.sin(Math.PI * progress);
                    envelope *= envelope * 0.045;
                    left = (snowLeft * 0.75 + snowRight * 0.25) * envelope;
                    right = (snowRight * 0.75 + snowLeft * 0.25) * envelope;
                }
                if (iceFrame < ICE_FRAMES)
                {
                    chimePhase += chimeStep;
                    chime *= 0.99996;
                    double attack = Math.min(1, iceFrame / (SAMPLE_RATE * 0.015));
                    double release = Math.min(1, (ICE_FRAMES - 1 - iceFrame) / (double) ICE_FADE_FRAMES);
                    double ice = chime * attack * release
                        * (Math.sin(chimePhase) + 0.3 * Math.sin(chimePhase * 1.417));
                    left += ice;
                    right += ice * 0.75;
                    iceFrame++;
                }
                write(pcm, offset, left * gain);
                write(pcm, offset + 2, right * gain);
            }
        }

        private static void write(byte[] bytes, int offset, double value)
        {
            int sample = (int) Math.round(Math.max(-0.8, Math.min(0.8, value)) * 32767);
            bytes[offset] = (byte) sample;
            bytes[offset + 1] = (byte) (sample >> 8);
        }
    }
}

package com.seasonalscape;

/** Coordinate eligibility shared by terrain, foliage and seasonal decorations. */
final class SeasonalWorldArea
{
    private SeasonalWorldArea() {}

    /**
     * The supported main-overworld band is X 0..4095 and Y 0..4095. This
     * deliberately excludes underground and separately mapped areas, including
     * surface-looking pocket maps. Roof, bridge, plane and instance checks are
     * still required by each effect; coordinates alone do not prove clear sky.
     * Membership and world type do not affect eligibility.
     */
    static boolean contains(int worldX, int worldY)
    {
        return worldX >= 0 && worldX < 4096 && worldY >= 0 && worldY < 4096;
    }
}

package com.seasonalscape;

import java.util.BitSet;
import java.util.Map;
import java.util.WeakHashMap;
import net.runelite.api.Model;

/** Client-thread-only snow on solid canopy tops, preserving foliage cutout edges. */
final class WinterCanopySnow
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();

    private WinterCanopySnow() {}

    /** Bit 0 means affected; bit 1 means a GPU upload is required. */
    static int apply(Object owner, Model model)
    {
        short[] textures = model.getFaceTextures();
        if (textures == null) { return 0; }
        int[][] channels = {model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3()};
        if (channels[0] == null || channels[1] == null || channels[2] == null) { return 0; }
        State state = STATES.computeIfAbsent(owner, ignored -> new State());
        Textures saved = state.textures.computeIfAbsent(textures, Textures::new);
        float[] ys = model.getVerticesY();
        float minY = Float.POSITIVE_INFINITY, maxY = Float.NEGATIVE_INFINITY;
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        if (ys != null && a != null && b != null && c != null)
        {
            for (int face = 0; face < textures.length; face++)
            {
                if (saved.original[face] != 30) { continue; }
                for (int vertex : new int[]{a[face], b[face], c[face]})
                {
                    minY = Math.min(minY, ys[vertex]);
                    maxY = Math.max(maxY, ys[vertex]);
                }
            }
        }
        float capMinY = Float.POSITIVE_INFINITY, capMaxY = Float.NEGATIVE_INFINITY;
        if (ys != null && a != null && b != null && c != null)
        {
            for (int face = 0; face < textures.length; face++)
            {
                if (saved.original[face] != 60
                    && (saved.original[face] != 30 || !willowCap(model, face, minY, maxY))) { continue; }
                for (int vertex : new int[]{a[face], b[face], c[face]})
                {
                    capMinY = Math.min(capMinY, ys[vertex]);
                    capMaxY = Math.max(capMaxY, ys[vertex]);
                }
            }
        }
        int flags = 0;
        for (int face = 0; face < textures.length; face++)
        {
            int texture = saved.original[face];
            if (texture != 60 && (texture != 30 || !willowCap(model, face, minY, maxY))) { continue; }
            if (!saved.available(textures, face)) { continue; }
            boolean brightness = true;
            for (int[] channel : channels)
            {
                ColorState colors = state.colors.get(channel);
                int original = colors == null ? channel[face] : colors.original[face];
                if (original > 127) { brightness = false; break; }
            }
            // Existing HSL tint belongs to another modifier; do not reinterpret it as lighting.
            if (!brightness) { continue; }
            if (textures[face] != -1) { flags |= 2; }
            saved.set(textures, face, (short) -1);
            flags |= 1;
            ColorState first = state.colors.get(channels[0]), third = state.colors.get(channels[2]);
            int firstOriginal = first == null ? channels[0][face] : first.original[face];
            int thirdOriginal = third == null ? channels[2][face] : third.original[face];
            boolean flat = thirdOriginal == -1;
            boolean aliased = channels[0] == channels[1] || channels[0] == channels[2]
                || channels[1] == channels[2];
            for (int channelIndex = 0; channelIndex < channels.length; channelIndex++)
            {
                int[] channel = channels[channelIndex];
                ColorState colors = state.colors.computeIfAbsent(channel, ColorState::new);
                int original = flat ? firstOriginal : colors.original[face];
                if (original < 0 || thirdOriginal == -2) { continue; }
                double height = 1;
                if (Float.isFinite(capMinY) && Float.isFinite(capMaxY) && capMaxY > capMinY)
                {
                    float vertexY = aliased ? (ys[a[face]] + ys[b[face]] + ys[c[face]]) / 3f
                        : ys[channelIndex == 0 ? a[face] : channelIndex == 1 ? b[face] : c[face]];
                    height = Math.max(0, Math.min(1, (capMaxY - vertexY) / (capMaxY - capMinY)));
                    height = height * height * (3 - 2 * height);
                }
                // Gouraud shading blends pale snow at the apex into the canopy's
                // muted green rim instead of drawing an abrupt white polygon edge.
                int rimLight = 30 + original * 10 / 127;
                int topLight = 88 + original * 16 / 127;
                int light = (int) Math.round(rimLight + (topLight - rimLight) * height);
                // Snow stays below the vegetation saturation threshold so the
                // general winter foliage pass preserves this edge gradient.
                int saturation = (int) Math.round(1 - height);
                int desired = 16 << 10 | saturation << 7 | light;
                int before = channel[face];
                colors.saved.apply(channel, face, desired);
                if (channel[face] != before) { flags |= 2; }
            }
        }
        return flags;
    }

    static void restore(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return; }
        for (Map.Entry<int[], ColorState> entry : state.colors.entrySet())
        {
            entry.getValue().saved.restore(entry.getKey());
        }
        for (Map.Entry<short[], Textures> entry : state.textures.entrySet())
        {
            entry.getValue().restore(entry.getKey());
        }
    }

    private static boolean willowCap(Model model, int face, float minY, float maxY)
    {
        float[] x = model.getVerticesX(), y = model.getVerticesY(), z = model.getVerticesZ();
        int[] ai = model.getFaceIndices1(), bi = model.getFaceIndices2(), ci = model.getFaceIndices3();
        if (x == null || y == null || z == null || ai == null || bi == null || ci == null
            || !Float.isFinite(minY) || !Float.isFinite(maxY)) { return false; }
        int a = ai[face], b = bi[face], c = ci[face];
        // Model Y decreases upwards. Exclude the lower hanging leaf tiers.
        if ((y[a] + y[b] + y[c]) / 3f > (minY + maxY) / 2f) { return false; }
        double ux = x[b] - x[a], uy = y[b] - y[a], uz = z[b] - z[a];
        double vx = x[c] - x[a], vy = y[c] - y[a], vz = z[c] - z[a];
        double nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
        double length = Math.sqrt(nx * nx + ny * ny + nz * nz);
        return length > 0 && ny / length < -0.85;
    }

    private static final class State
    {
        private final Map<short[], Textures> textures = new WeakHashMap<>();
        private final Map<int[], ColorState> colors = new WeakHashMap<>();
    }

    private static final class ColorState
    {
        private final int[] original;
        private final SeasonalSceneRecolorer.Colors saved;
        private ColorState(int[] values)
        {
            original = values.clone();
            saved = new SeasonalSceneRecolorer.Colors(values);
        }
    }

    private static final class Textures
    {
        private final short[] original, last;
        private final BitSet conflicted = new BitSet();
        private Textures(short[] values) { original = values.clone(); last = values.clone(); }
        private boolean available(short[] values, int face)
        {
            if (values[face] != last[face]) { conflicted.set(face); }
            return !conflicted.get(face);
        }
        private void set(short[] values, int face, short texture) { values[face] = last[face] = texture; }
        private void restore(short[] values)
        {
            for (int face = 0; face < values.length; face++)
            {
                if (!conflicted.get(face) && values[face] == last[face]) { values[face] = original[face]; }
            }
        }
    }
}

package com.seasonalscape;

import java.util.BitSet;
import java.util.Map;
import java.util.WeakHashMap;
import net.runelite.api.Model;

/** Client-thread-only material changes on roof models selected by the caller. */
final class WinterRoofMaterial
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();

    private WinterRoofMaterial() {}

    /** Bit 0 means affected; bit 1 means a GPU upload is required. */
    static int apply(Object owner, Model model)
    {
        if (model == null) { return 0; }
        float[] x = model.getVerticesX(), y = model.getVerticesY(), z = model.getVerticesZ();
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        int[][] channels = {model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3()};
        if (x == null || y == null || z == null || a == null || b == null || c == null
            || channels[0] == null || channels[1] == null || channels[2] == null) { return 0; }
        short[] textures = model.getFaceTextures();
        int count = Math.min(model.getFaceCount(), Math.min(a.length, Math.min(b.length, c.length)));
        for (int[] channel : channels) { count = Math.min(count, channel.length); }
        if (textures != null) { count = Math.min(count, textures.length); }
        int vertices = Math.min(model.getVerticesCount(), Math.min(x.length, Math.min(y.length, z.length)));
        State state = STATES.computeIfAbsent(owner, ignored -> new State());
        ColorState[] colors = new ColorState[3];
        int[] desired = new int[3];
        TextureState textureState = textures == null ? null : state.textures.get(textures);
        int flags = 0;
        for (int face = 0; face < count; face++)
        {
            int third = original(state, channels[2], face);
            if (third == -2) { continue; }
            int ai = a[face], bi = b[face], ci = c[face];
            if (ai < 0 || bi < 0 || ci < 0 || ai >= vertices || bi >= vertices || ci >= vertices) { continue; }
            double ux = x[bi] - x[ai], uy = y[bi] - y[ai], uz = z[bi] - z[ai];
            double vx = x[ci] - x[ai], vy = y[ci] - y[ai], vz = z[ci] - z[ai];
            double nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
            double lengthSquared = nx * nx + ny * ny + nz * nz;
            if (ny >= 0 || ny * ny <= 0.35 * 0.35 * lengthSquared) { continue; }

            if (textures != null && textureState == null)
            {
                textureState = state.textures.computeIfAbsent(textures, TextureState::new);
            }
            int texture = textureState == null ? -1 : textureState.original[face];
            boolean flat = third == -1;
            boolean available = textureState == null || textureState.available(textures, face);
            for (int channel = 0; channel < channels.length; channel++)
            {
                // Flat faces are shaded entirely from channel A. Preserve the
                // unused channel B and the channel C sentinel exactly.
                if (flat && channel > 0) { continue; }
                ColorState saved = colors[channel];
                if (saved == null)
                {
                    saved = state.colors.computeIfAbsent(channels[channel], ColorState::new);
                    colors[channel] = saved;
                }
                int source = saved.original[face];
                available &= saved.available(channels[channel], face);
                // Textured faces store brightness; packed colors here belong
                // to another modifier and must not be reinterpreted as light.
                if (source < 0 || (texture >= 0 && source > 127)) { available = false; }
                desired[channel] = snow(source & 127);
            }
            if (!available) { continue; }

            boolean affected = texture >= 0;
            boolean mutated = false;
            if (textureState != null) { mutated |= textureState.set(textures, face, (short) -1); }
            for (int channel = 0; channel < channels.length; channel++)
            {
                if (flat && channel > 0) { continue; }
                affected |= desired[channel] != colors[channel].original[face];
                mutated |= colors[channel].set(channels[channel], face, desired[channel]);
            }
            if (affected) { flags |= 1; }
            if (mutated) { flags |= 2; }
        }
        return flags;
    }

    /** Restores only values still owned by this modifier; returns whether anything changed. */
    static boolean restore(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return false; }
        boolean changed = false;
        for (Map.Entry<int[], ColorState> entry : state.colors.entrySet())
        {
            changed |= entry.getValue().restore(entry.getKey());
        }
        for (Map.Entry<short[], TextureState> entry : state.textures.entrySet())
        {
            changed |= entry.getValue().restore(entry.getKey());
        }
        return changed;
    }

    private static int original(State state, int[] values, int face)
    {
        ColorState colors = state.colors.get(values);
        return colors == null ? values[face] : colors.original[face];
    }

    private static int snow(int brightness)
    {
        return 36 << 10 | 86 + brightness * 22 / 127;
    }

    private static final class State
    {
        private final Map<int[], ColorState> colors = new WeakHashMap<>();
        private final Map<short[], TextureState> textures = new WeakHashMap<>();
    }

    private static final class ColorState
    {
        private final int[] original, last;
        private final BitSet touched = new BitSet();
        private final BitSet conflicted = new BitSet();

        private ColorState(int[] values) { original = values.clone(); last = values.clone(); }

        private boolean available(int[] values, int face)
        {
            if (values[face] != last[face]) { conflicted.set(face); }
            return !conflicted.get(face);
        }

        private boolean set(int[] values, int face, int value)
        {
            boolean changed = values[face] != value;
            values[face] = last[face] = value;
            touched.set(face);
            return changed;
        }

        private boolean restore(int[] values)
        {
            boolean changed = false;
            for (int face = touched.nextSetBit(0); face >= 0; face = touched.nextSetBit(face + 1))
            {
                if (!conflicted.get(face) && values[face] == last[face])
                {
                    changed |= values[face] != original[face];
                    values[face] = original[face];
                }
            }
            return changed;
        }
    }

    private static final class TextureState
    {
        private final short[] original, last;
        private final BitSet touched = new BitSet();
        private final BitSet conflicted = new BitSet();

        private TextureState(short[] values) { original = values.clone(); last = values.clone(); }

        private boolean available(short[] values, int face)
        {
            if (values[face] != last[face]) { conflicted.set(face); }
            return !conflicted.get(face);
        }

        private boolean set(short[] values, int face, short value)
        {
            boolean changed = values[face] != value;
            values[face] = last[face] = value;
            touched.set(face);
            return changed;
        }

        private boolean restore(short[] values)
        {
            boolean changed = false;
            for (int face = touched.nextSetBit(0); face >= 0; face = touched.nextSetBit(face + 1))
            {
                if (!conflicted.get(face) && values[face] == last[face])
                {
                    changed |= values[face] != original[face];
                    values[face] = original[face];
                }
            }
            return changed;
        }
    }
}

package com.seasonalscape;

import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;

/** Conservative camera bounds for scheduling snow work, not an occlusion test. */
final class WinterSnowVisibility
{
    static final int NEW_RADIUS = 22;
    static final int RETAIN_RADIUS = 24;
    private static final int TILE_SIZE = 128;
    private static final double ANGLE_UNIT = 2 * Math.PI / 16384;
    private static final double MOTION_ANGLE = Math.PI / 180;
    private static final int MOTION_DISTANCE = TILE_SIZE / 2;
    private static final int ENTER_MARGIN = 96;
    private static final int RETAIN_MARGIN = 160;

    private final int playerX, playerY, viewportWidth, viewportHeight, scale;
    private final double cameraX, cameraY, cameraZ, pitch, yaw;
    private final boolean hasCamera;
    private final Frustum entering, retaining;

    static WinterSnowVisibility capture(Client client, LocalPoint player)
    {
        int width = client.getViewportWidth(), height = client.getViewportHeight(), scale = client.getScale();
        // No usable projection during startup, in unsupported world views, or in test fixtures.
        // Keeping the distance cap here is safer than accidentally hiding every structure.
        if (width <= 0 || height <= 0 || scale <= 0 || player.getWorldView() != 0)
        {
            return new WinterSnowVisibility(player.getX(), player.getY(), 0, 0, 0, 0, 0, 0, 0, 0);
        }
        if (client.isGpu())
        {
            // RuneLite's GPU projection uses floating point positions and angles in radians.
            return new WinterSnowVisibility(player.getX(), player.getY(),
                client.getCameraFpX(), client.getCameraFpY(), client.getCameraFpZ(),
                client.getCameraFpPitch(), client.getCameraFpYaw(), width, height, scale);
        }
        // In RuneLite 1.13.1 integer camera angles use 14-bit Jagex angle units.
        return new WinterSnowVisibility(player.getX(), player.getY(),
            client.getCameraX(), client.getCameraY(), client.getCameraZ(),
            client.getCameraPitch() * ANGLE_UNIT, client.getCameraYaw() * ANGLE_UNIT,
            width, height, scale);
    }

    /** Angles are radians; package access also keeps projection tests independent of a live client. */
    WinterSnowVisibility(int playerX, int playerY, double cameraX, double cameraY, double cameraZ,
        double pitch, double yaw, int viewportWidth, int viewportHeight, int scale)
    {
        this.playerX = playerX;
        this.playerY = playerY;
        this.cameraX = cameraX;
        this.cameraY = cameraY;
        this.cameraZ = cameraZ;
        this.pitch = pitch;
        this.yaw = yaw;
        this.viewportWidth = viewportWidth;
        this.viewportHeight = viewportHeight;
        this.scale = scale;
        hasCamera = viewportWidth > 0 && viewportHeight > 0 && scale > 0
            && Double.isFinite(cameraX) && Double.isFinite(cameraY) && Double.isFinite(cameraZ)
            && Double.isFinite(pitch) && Double.isFinite(yaw);
        entering = hasCamera ? new Frustum(pitch, yaw,
            (viewportWidth * .5 + ENTER_MARGIN) / scale, (viewportHeight * .5 + ENTER_MARGIN) / scale) : null;
        retaining = hasCamera ? new Frustum(pitch, yaw,
            (viewportWidth * .5 + RETAIN_MARGIN) / scale, (viewportHeight * .5 + RETAIN_MARGIN) / scale) : null;
    }

    boolean similarTo(WinterSnowVisibility previous)
    {
        return previous != null && hasCamera == previous.hasCamera
            && viewportWidth == previous.viewportWidth && viewportHeight == previous.viewportHeight
            && scale == previous.scale
            && Math.abs(playerX - previous.playerX) < MOTION_DISTANCE
            && Math.abs(playerY - previous.playerY) < MOTION_DISTANCE
            && (!hasCamera || (Math.abs(cameraX - previous.cameraX) < MOTION_DISTANCE
                && Math.abs(cameraY - previous.cameraY) < MOTION_DISTANCE
                && Math.abs(cameraZ - previous.cameraZ) < MOTION_DISTANCE
                && angleDistance(pitch, previous.pitch) < MOTION_ANGLE
                && angleDistance(yaw, previous.yaw) < MOTION_ANGLE));
    }

    /** Includes tile corners, terrain slope, and roofs up to six tiles above this plane. */
    boolean visibleTile(int sceneX, int sceneY, int terrainHeight, boolean retained)
    {
        int x = sceneX * TILE_SIZE + TILE_SIZE / 2, y = sceneY * TILE_SIZE + TILE_SIZE / 2;
        return visibleBox(x, y, terrainHeight - 384, 96, 96, 448, retained);
    }

    boolean visibleSphere(int localX, int localY, int z, int radius, boolean retained)
    {
        // A box enclosing the sphere is intentionally conservative and avoids model bounds queries.
        int extent = Math.max(0, radius);
        return visibleBox(localX, localY, z, extent, extent, extent, retained);
    }

    private boolean visibleBox(int x, int y, int z, int halfX, int halfY, int halfZ, boolean retained)
    {
        double dx = (double) x - playerX, dy = (double) y - playerY;
        // Measure distance to the box, so a roof intersecting the boundary is not discarded.
        double distanceX = Math.max(0, Math.abs(dx) - halfX);
        double distanceY = Math.max(0, Math.abs(dy) - halfY);
        int range = (retained ? RETAIN_RADIUS : NEW_RADIUS) * TILE_SIZE;
        if (distanceX * distanceX + distanceY * distanceY > (double) range * range) { return false; }
        if (!hasCamera) { return true; }
        return (retained ? retaining : entering).intersects(
            x - cameraX, y - cameraY, z - cameraZ, halfX, halfY, halfZ);
    }

    private static double angleDistance(double a, double b)
    {
        return Math.abs(Math.IEEEremainder(a - b, 2 * Math.PI));
    }

    /** Five world-space planes, precomputed once per snapshot; no per-tile allocation/projection. */
    private static final class Frustum
    {
        private final double[][] planes = new double[5][3];

        Frustum(double pitch, double yaw, double horizontalSlope, double verticalSlope)
        {
            double sp = Math.sin(pitch), cp = Math.cos(pitch);
            double sy = Math.sin(yaw), cy = Math.cos(yaw);
            double[] depth = {-sy * cp, cy * cp, sp};
            double[] horizontal = {cy, sy, 0};
            double[] vertical = {sy * sp, -cy * sp, cp};
            for (int axis = 0; axis < 3; axis++)
            {
                planes[0][axis] = depth[axis];
                planes[1][axis] = depth[axis] * horizontalSlope + horizontal[axis];
                planes[2][axis] = depth[axis] * horizontalSlope - horizontal[axis];
                planes[3][axis] = depth[axis] * verticalSlope + vertical[axis];
                planes[4][axis] = depth[axis] * verticalSlope - vertical[axis];
            }
        }

        boolean intersects(double x, double y, double z, int halfX, int halfY, int halfZ)
        {
            for (int i = 0; i < planes.length; i++)
            {
                double[] plane = planes[i];
                double furthest = plane[0] * x + plane[1] * y + plane[2] * z
                    + Math.abs(plane[0]) * halfX + Math.abs(plane[1]) * halfY + Math.abs(plane[2]) * halfZ;
                if (furthest < (i == 0 ? 50 : 0)) { return false; }
            }
            return true;
        }
    }
}

package com.seasonalscape;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Small depth-tested flakes. All state and animation run on the client thread. */
final class WinterSnowfall
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();
    private static final int PARTICLE_COUNT = 384;
    private static final int LOWER_PARTICLES = 256;
    private static final int RADIUS = 10 * 128;
    private static final int MODEL_ID = 27835;
    private static final float LOWER_CEILING = 1500;
    private static final float UPPER_FLOOR = 1100;
    private static final float MIN_CEILING = 3200, MAX_CEILING = 6400;

    private WinterSnowfall() {}

    /** The caller enables this only during winter. */
    static void update(Object owner, Client client, Scene scene)
    {
        WorldView world = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        LocalPoint point = player == null ? null : player.getLocalLocation();
        DrawCallbacks renderer = client.getDrawCallbacks();
        if (client.getGameState() != GameState.LOGGED_IN || world == null || scene == null
            || (renderer != null && !(renderer instanceof GpuPlugin))
            || !world.isTopLevel() || world.isInstance() || scene.isInstance()
            || world.getPlane() != 0 || world.getScene() != scene || point == null
            || point.getWorldView() != world.getId()
            || !SeasonalWorldArea.contains(scene.getBaseX() + point.getSceneX(), scene.getBaseY() + point.getSceneY())
            || !clearSky(world.getTileSettings(), point.getSceneX(), point.getSceneY()))
        {
            clear(owner);
            return;
        }
        State state = STATES.get(owner);
        if (state != null && (state.scene != scene || state.baseX != scene.getBaseX()
            || state.baseY != scene.getBaseY() || state.world != world))
        {
            clear(owner);
            state = null;
        }
        if (state == null)
        {
            Model[] models = createModels(client);
            if (models == null) { return; }
            state = new State(client, world, scene, models);
            STATES.put(owner, state);
        }
        state.center = point;
        state.refreshTiles();
        state.refreshCeiling();
        // A failed outdoor placement remains inactive until the next game tick.
        for (Flake flake : state.flakes)
        {
            if (!flake.isActive()) { flake.respawn(true); }
        }
    }

    static void clear(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return; }
        state.cleared = true;
        for (Flake flake : state.flakes) { flake.setActive(false); }
    }

    static int getCount(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return 0; }
        int count = 0;
        for (Flake flake : state.flakes) { if (flake.isActive()) { count++; } }
        return count;
    }

    private static Model[] createModels(Client client)
    {
        ModelData source = client.loadModelData(MODEL_ID);
        if (source == null || source.getVerticesCount() < 3 || source.getVerticesCount() > 8192
            || source.getFaceCount() == 0 || source.getFaceCount() > 8192) { return null; }
        Model[] models = new Model[6];
        for (int variant = 0; variant < models.length; variant++)
        {
            ModelData data = source.shallowCopy().cloneVertices().cloneColors();
            if (data.getFaceTextures() != null)
            {
                data.cloneTextures();
                Arrays.fill(data.getFaceTextures(), (short) -1);
            }
            data.cloneTransparencies(true);
            Arrays.fill(data.getFaceTransparencies(), (byte) (24 + variant % 3 * 8));
            Arrays.fill(data.getFaceColors(), (short) 120);
            // Upper flakes are slightly larger so the raised layer remains
            // legible at far zoom without adding more animated objects.
            reshape(source, data, (variant < 3 ? 4.4f : 7.0f) + variant % 3 * 0.8f);
            data.translate(0, 0, 0);
            models[variant] = data.light(100, ModelData.DEFAULT_CONTRAST,
                ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
        }
        return models;
    }

    static float ceilingForCamera(float groundHeight, double cameraZ)
    {
        if (!Float.isFinite(groundHeight) || !Double.isFinite(cameraZ)) { return MIN_CEILING; }
        // Scene Z becomes more negative above the ground. Follow camera height,
        // with headroom for the upper view, while keeping the volume bounded.
        return (float) Math.max(MIN_CEILING, Math.min(MAX_CEILING, groundHeight - cameraZ + 1024));
    }

    /** Retain one cache flake; collapse other components without modifying face indices. */
    static void reshape(ModelData source, ModelData target, float radius)
    {
        int count = source.getVerticesCount();
        int[] roots = new int[count];
        for (int i = 0; i < count; i++) { roots[i] = i; }
        int[] a = source.getFaceIndices1(), b = source.getFaceIndices2(), c = source.getFaceIndices3();
        for (int face = 0; face < source.getFaceCount(); face++)
        {
            union(roots, a[face], b[face]);
            union(roots, a[face], c[face]);
        }
        int selected = root(roots, a[0]);
        float[] sx = source.getVerticesX(), sy = source.getVerticesY(), sz = source.getVerticesZ();
        float[] x = target.getVerticesX(), y = target.getVerticesY(), z = target.getVerticesZ();
        float minX = Float.POSITIVE_INFINITY, minY = minX, minZ = minX;
        float maxX = Float.NEGATIVE_INFINITY, maxY = maxX, maxZ = maxX;
        for (int i = 0; i < count; i++)
        {
            if (root(roots, i) != selected) { continue; }
            minX = Math.min(minX, sx[i]); maxX = Math.max(maxX, sx[i]);
            minY = Math.min(minY, sy[i]); maxY = Math.max(maxY, sy[i]);
            minZ = Math.min(minZ, sz[i]); maxZ = Math.max(maxZ, sz[i]);
        }
        float scale = radius * 2 / Math.max(1, Math.max(maxX - minX, Math.max(maxY - minY, maxZ - minZ)));
        for (int i = 0; i < count; i++)
        {
            boolean visible = root(roots, i) == selected;
            x[i] = visible ? (sx[i] - (minX + maxX) / 2) * scale : 0;
            y[i] = visible ? (sy[i] - (minY + maxY) / 2) * scale : 0;
            z[i] = visible ? (sz[i] - (minZ + maxZ) / 2) * scale : 0;
        }
    }

    private static int root(int[] roots, int value)
    {
        while (roots[value] != value)
        {
            roots[value] = roots[roots[value]];
            value = roots[value];
        }
        return value;
    }

    private static void union(int[] roots, int a, int b) { roots[root(roots, b)] = root(roots, a); }

    private static final class State
    {
        final Client client;
        final WorldView world;
        final Scene scene;
        final int baseX, baseY;
        final Random random;
        final List<Flake> flakes = new ArrayList<>();
        Tile[][][] tiles;
        byte[][][] flags;
        int[][] heights;
        LocalPoint center;
        float ceiling = MIN_CEILING;
        int lastVolumeCycle = Integer.MIN_VALUE;
        boolean cleared;

        State(Client client, WorldView world, Scene scene, Model[] models)
        {
            this.client = client;
            this.world = world;
            this.scene = scene;
            baseX = scene.getBaseX();
            baseY = scene.getBaseY();
            random = new Random(((long) baseX << 32) ^ baseY ^ 0x534e4f57L);
            refreshTiles();
            for (int i = 0; i < PARTICLE_COUNT; i++)
            {
                flakes.add(new Flake(this, models[i % 3 + (i >= LOWER_PARTICLES ? 3 : 0)], i));
            }
        }

        void refreshTiles()
        {
            // Some scene accessors translate extended arrays. Read once per game
            // tick rather than once per particle on every rendered frame.
            tiles = scene.getTiles();
            flags = world.getTileSettings();
            int[][][] allHeights = world.getTileHeights();
            heights = allHeights == null || allHeights.length == 0 ? null : allHeights[0];
        }

        void refreshCeiling()
        {
            int cycle = client.getGameCycle();
            if (cycle == lastVolumeCycle || center == null) { return; }
            double cameraZ = client.isGpu() ? client.getCameraFpZ() : client.getCameraZ();
            float target = ceilingForCamera(GroundCoverPlacement.height(heights, center.getX(), center.getY()), cameraZ);
            // Follow zoom changes within about a second, without stretching the
            // whole upper layer abruptly on one frame. Compute once per cycle.
            ceiling = lastVolumeCycle == Integer.MIN_VALUE ? target
                : ceiling + Math.max(-80, Math.min(80, target - ceiling));
            lastVolumeCycle = cycle;
        }

        boolean outdoors(int localX, int localY)
        {
            int x = localX >> 7, y = localY >> 7;
            if (x < 1 || y < 1 || !SeasonalWorldArea.contains(baseX + x, baseY + y)) { return false; }
            if (tiles == null || tiles.length == 0 || tiles[0] == null
                || x >= tiles[0].length - 1 || tiles[0][x] == null
                || y >= tiles[0][x].length - 1) { return false; }
            Tile tile = tiles[0][x][y];
            if (tile == null || tile.getRenderLevel() != 0 || tile.getBridge() != null) { return false; }
            return clearSky(flags, x, y)
                && Float.isFinite(GroundCoverPlacement.height(heights, localX, localY));
        }
    }

    /** Ordinary WorldView coordinates, unlike Scene's extended tile settings. */
    static boolean clearSky(byte[][][] flags, int x, int y)
    {
        if (flags == null || flags.length < 2 || x < 0 || y < 0) { return false; }
        for (int plane = 1; plane < flags.length; plane++)
        {
            if (flags[plane] == null || x >= flags[plane].length || flags[plane][x] == null
                || y >= flags[plane][x].length) { return false; }
            int value = flags[plane][x][y];
            if ((value & 4) != 0 || (plane == 1 && (value & 2) != 0)) { return false; }
        }
        return true;
    }

    private static final class Flake extends RuneLiteObject
    {
        final State state;
        final float speed;
        final float phase;
        final boolean upperLayer;
        final int layerIndex, layerCount;
        float x, y, altitude, age;
        float altitudeCeiling;

        Flake(State state, Model model, int index)
        {
            super(state.client);
            this.state = state;
            upperLayer = index >= LOWER_PARTICLES;
            layerIndex = upperLayer ? index - LOWER_PARTICLES : index;
            layerCount = upperLayer ? PARTICLE_COUNT - LOWER_PARTICLES : LOWER_PARTICLES;
            speed = 1.5f + state.random.nextFloat() * 1.2f;
            phase = state.random.nextFloat() * 6.2831853f;
            setModel(model);
            setWorldView(state.world.getId());
            setLevel(0);
            setOrientation(state.random.nextInt(2048));
        }

        boolean respawn(boolean spreadVertically)
        {
            if (state.cleared || state.center == null) { return false; }
            for (int attempt = 0; attempt < 24; attempt++)
            {
                double angle = state.random.nextDouble() * Math.PI * 2;
                double radius = Math.sqrt(state.random.nextDouble()) * RADIUS;
                x = state.center.getX() + (float) (Math.cos(angle) * radius);
                y = state.center.getY() + (float) (Math.sin(angle) * radius);
                if (!state.outdoors((int) x, (int) y)) { continue; }
                // Keep two thirds of the flakes in the original dense lower
                // volume, with a separate upper layer for distant camera views.
                // Stratified initial heights populate both layers immediately.
                float floor = upperLayer ? UPPER_FLOOR : 30;
                altitudeCeiling = upperLayer ? state.ceiling : LOWER_CEILING;
                float fraction = spreadVertically ? (layerIndex + state.random.nextFloat()) / layerCount
                    : 0.75f + state.random.nextFloat() * 0.25f;
                altitude = floor + fraction * (altitudeCeiling - floor);
                place();
                if (!isActive()) { setActive(true); }
                return true;
            }
            setActive(false);
            return false;
        }

        @Override
        public void tick(int ticksSinceLastFrame)
        {
            if (state.cleared || state.client.getGameState() != GameState.LOGGED_IN
                || state.world.getScene() != state.scene || state.world.getPlane() != 0)
            {
                setActive(false);
                return;
            }
            Player player = state.client.getLocalPlayer();
            LocalPoint point = player == null ? null : player.getLocalLocation();
            if (point == null || point.getWorldView() != getWorldView())
            {
                setActive(false);
                return;
            }
            state.center = point;
            state.refreshCeiling();
            if (upperLayer && altitudeCeiling != state.ceiling)
            {
                // Preserve each flake's position within its layer as the camera
                // zoom changes; no respawn, extra object or model rebuild needed.
                altitude = UPPER_FLOOR + (altitude - UPPER_FLOOR)
                    * (state.ceiling - UPPER_FLOOR) / (altitudeCeiling - UPPER_FLOOR);
                altitudeCeiling = state.ceiling;
            }
            int elapsed = Math.max(0, Math.min(10, ticksSinceLastFrame));
            age += elapsed;
            altitude -= speed * elapsed;
            x += (0.5f + (float) Math.sin(age * 0.035f + phase) * 0.55f) * elapsed;
            y += (float) Math.cos(age * 0.024f + phase) * 0.45f * elapsed;
            float dx = x - point.getX(), dy = y - point.getY();
            if (altitude <= (upperLayer ? UPPER_FLOOR : 6)
                || dx * dx + dy * dy > (RADIUS + 128f) * (RADIUS + 128f)
                || !state.outdoors((int) x, (int) y))
            {
                respawn(false);
                return;
            }
            place();
        }

        private void place()
        {
            // Use cached regular-scene heights and absolute coordinates, avoiding
            // per-frame LocalPoint allocation and repeated scene array access.
            setX((int) x);
            setY((int) y);
            setZ(Math.round(GroundCoverPlacement.height(state.heights, (int) x, (int) y) - altitude));
        }
    }
}

package com.seasonalscape;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Arrays;
import java.util.BitSet;
import java.util.Collections;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Thin winter coatings on exposed structures; furniture source meshes remain untouched. */
final class WinterSurfaceSnow
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();
    private static final int RADIUS = 22, SCAN_RADIUS = 24, MAX_OBJECTS = 128, MAX_FACES = 59;
    private static final int TILES_PER_CYCLE = 192, MODELS_PER_CYCLE = 2, GPU_ZONES_PER_CYCLE = 2;
    private static final long WORK_BUDGET_NANOS = 2_000_000L;
    private static final int[][] OFFSETS = scanOffsets();
    private static final int HIDDEN = 12345678;

    private WinterSurfaceSnow() {}

    /** Starts snow; subsequent client ticks continue a bounded amount of work. */
    static void update(Object owner, Client client, Scene scene, boolean enabled)
    {
        if (!enabled) { restore(owner); return; }
        if (client.getGameState() == GameState.LOADING) { return; }
        if (client.getGameState() != GameState.LOGGED_IN || !SeasonalSceneRecolorer.supports(scene))
        {
            restore(owner); return;
        }
        State state = STATES.get(owner);
        if (state == null || state.scene != scene || state.baseX != scene.getBaseX() || state.baseY != scene.getBaseY())
        {
            restore(owner);
            Tile[][][] tiles = scene.getExtendedTiles();
            if (tiles == null || tiles.length == 0 || tiles[0] == null) { return; }
            state = new State(client, scene);
            STATES.put(owner, state);
        }
        tick(owner);
    }

    static void tick(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return; }
        Client client = state.client;
        if (client.getGameState() == GameState.LOADING) { return; }
        if (client.getGameState() != GameState.LOGGED_IN || !SeasonalSceneRecolorer.supports(state.scene))
        {
            restore(owner); return;
        }
        Object renderer = client.getDrawCallbacks();
        if (renderer != null && !(renderer instanceof GpuPlugin)) { restore(owner); return; }
        WorldView world = client.getTopLevelWorldView();
        if (world != null && world.getScene() != state.scene) { return; }
        int cycle = client.getGameCycle();
        if (cycle == state.lastCycle) { return; }
        state.lastCycle = cycle;
        state.lastTiles = state.lastModels = state.lastCandidates = state.lastBuilds = state.lastGpuZones = 0;
        long start = System.nanoTime();
        Player player = client.getLocalPlayer();
        LocalPoint point = player == null ? null : player.getLocalLocation();
        if (point == null) { return; }
        if (point.getWorldView() != WorldView.TOPLEVEL) { restore(owner); return; }
        if (!inRegion(state.scene, point.getSceneX(), point.getSceneY())) { restore(owner); return; }
        WinterSnowVisibility view = WinterSnowVisibility.capture(client, point);
        int plane = world == null ? 0 : world.getPlane();
        if (state.scan == null && (state.rescan || !view.similarTo(state.lastView)
            || state.lastPlane != plane || cycle >= state.retryAt))
        {
            Tile[][][] tiles = state.scene.getExtendedTiles();
            byte[][][] flags = state.scene.getExtendedTileSettings();
            if (tiles == null || tiles.length == 0 || flags == null) { return; }
            state.scan = new Scan(state, point, view, tiles, flags, world == null ? null : world.getTileHeights());
            state.rescan = false;
            state.retryAt = Integer.MAX_VALUE;
            state.lastPlane = plane;
        }
        Scan scan = state.scan;
        if (scan != null)
        {
            // Finish each snapshot before taking the newest view: continuous camera
            // movement must never restart the scan and starve the remaining work.
            while (state.lastTiles < TILES_PER_CYCLE && state.lastModels < MODELS_PER_CYCLE
                && state.lastCandidates < 32
                && System.nanoTime() - start < WORK_BUDGET_NANOS)
            {
                if (!scan.pending.isEmpty()) { process(state, scan, scan.pending.removeFirst()); }
                else if (scan.position < OFFSETS.length * scan.tiles.length)
                {
                    scanTile(state, scan); state.lastTiles++;
                }
                else
                {
                    state.lastTiles++;
                    if (cleanup(state, scan))
                    {
                        state.lastView = scan.view; state.scan = null; break;
                    }
                }
            }
        }
        state.invalidate(GPU_ZONES_PER_CYCLE);
        state.lastWorkNanos = System.nanoTime() - start;
        state.maxWorkNanos = Math.max(state.maxWorkNanos, state.lastWorkNanos);
    }

    static void markDirty(Object owner)
    {
        State state = STATES.get(owner);
        if (state != null) { state.rescan = true; }
    }

    private static int[][] scanOffsets()
    {
        List<int[]> offsets = new ArrayList<>();
        for (int x = -SCAN_RADIUS; x <= SCAN_RADIUS; x++)
        {
            for (int y = -SCAN_RADIUS; y <= SCAN_RADIUS; y++)
            {
                if (x * x + y * y <= SCAN_RADIUS * SCAN_RADIUS) { offsets.add(new int[]{x, y}); }
            }
        }
        offsets.sort(Comparator.comparingInt(offset -> offset[0] * offset[0] + offset[1] * offset[1]));
        return offsets.toArray(new int[0][]);
    }

    private static void scanTile(State state, Scan scan)
    {
        int position = scan.position++;
        int[] offset = OFFSETS[position / scan.tiles.length];
        int plane = scan.tiles.length - 1 - position % scan.tiles.length;
        int x = scan.point.getSceneX() + offset[0], y = scan.point.getSceneY() + offset[1];
        int tx = x + state.offset, ty = y + state.offset;
        if (scan.tiles[plane] == null || tx < 0 || tx >= scan.tiles[plane].length
            || scan.tiles[plane][tx] == null || ty < 0 || ty >= scan.tiles[plane][tx].length
            || !inRegion(state.scene, x, y)) { return; }
        Tile tile = scan.tiles[plane][tx][ty];
        if (tile == null) { return; }
        int height = 0;
        if (scan.heights != null && plane < scan.heights.length && scan.heights[plane] != null
            && x >= 0 && x < scan.heights[plane].length && scan.heights[plane][x] != null
            && y >= 0 && y < scan.heights[plane][x].length) { height = scan.heights[plane][x][y]; }
        boolean retained = state.roofs.containsKey(tile) || state.retainedColumns.get(tx * state.size + ty);
        if (!scan.view.visibleTile(x, y, height, retained) || tile.getBridge() != null
            || !exposed(scan.tiles, scan.flags, plane, x, y)) { return; }
        boolean indoors = underRoof(scan.flags, plane, x, y);
        if (plane > 0 && !indoors && visibleFloor(tile) && !roofObjectOn(tile))
        {
            Roof roof = state.roofs.get(tile);
            if (roof != null && (roof.paint != tile.getSceneTilePaint() || roof.model != tile.getSceneTileModel()))
            {
                if (roof.restore()) { state.dirty(x, y); }
                roof = null;
            }
            if (roof == null)
            {
                roof = new Roof(tile, x, y); state.roofs.put(tile, roof);
                if (roof.apply()) { state.dirty(x, y); }
            }
            roof.seen = true;
        }
        GameObject[] objects = tile.getGameObjects();
        if (objects != null)
        {
            for (GameObject object : objects)
            {
                if (object == null || !scan.seen.add(object)) { continue; }
                String name = name(state.client, object);
                boolean roof = isRoof(name, object.getConfig());
                if ((!roof && !furnitureOrStructure(name)) || vegetation(name)) { continue; }
                if ((!roof && indoors) || !footprintExposed(scan.tiles, scan.flags, object, roof)) { continue; }
                int type = object.getConfig() & 31;
                candidate(state, scan.pending, object, object.getRenderable(), 0, object.getModelOrientation(), 0, 0,
                    roof, plane > 0 && type >= 12 && type <= 21, scan.point);
            }
        }
        WallObject wall = tile.getWallObject();
        if (!indoors && wall != null && scan.seen.add(wall) && !vegetation(name(state.client, wall)))
        {
            candidate(state, scan.pending, wall, wall.getRenderable1(), 0, 0, 0, 0, false, false, scan.point);
            candidate(state, scan.pending, wall, wall.getRenderable2(), 1, 0, 0, 0, false, false, scan.point);
        }
        DecorativeObject decoration = tile.getDecorativeObject();
        if (decoration != null && scan.seen.add(decoration))
        {
            String name = name(state.client, decoration);
            boolean roof = isRoof(name, decoration.getConfig());
            if ((roof || furnitureOrStructure(name)) && !vegetation(name) && (roof || !indoors))
            {
                candidate(state, scan.pending, decoration, decoration.getRenderable(), 0, 0,
                    decoration.getXOffset(), decoration.getYOffset(), roof, false, scan.point);
                candidate(state, scan.pending, decoration, decoration.getRenderable2(), 1, 0,
                    decoration.getXOffset2(), decoration.getYOffset2(), roof, false, scan.point);
            }
        }
    }

    private static void process(State state, Scan scan, Candidate candidate)
    {
        state.lastCandidates++;
        if (candidate.nativeMaterial)
        {
            Integer result = state.nativeModels.get(candidate.model);
            if (result == null)
            {
                state.lastModels++;
                result = WinterRoofMaterial.apply(state, candidate.model);
                state.nativeModels.put(candidate.model, result & 1);
                if ((result & 2) != 0)
                {
                    scan.nativeChanged = true;
                    LocalPoint point = candidate.object.getLocalLocation();
                    state.dirty(point.getSceneX(), point.getSceneY());
                }
            }
            if ((result & 1) != 0) { scan.nativeRoofs++; }
            return;
        }
        if (scan.active >= MAX_OBJECTS) { return; }
        List<Entry> entries = state.entries.computeIfAbsent(candidate.object, ignored -> new ArrayList<>());
        Entry entry = null;
        for (Entry old : entries) { if (old.slot == candidate.slot) { entry = old; break; } }
        if (entry != null && !entry.matches(candidate))
        {
            entry.clear(); entries.remove(entry); entry = null;
        }
        if (entry == null)
        {
            Map<Model, Model> cache = candidate.roof ? state.roofModels : state.surfaceModels;
            Model snow = cache.get(candidate.model);
            if (snow == null && !cache.containsKey(candidate.model))
            {
                state.lastModels++;
                Map<Model, List<Triangle>> geometry = candidate.roof ? state.roofGeometry : state.surfaceGeometry;
                List<Triangle> triangles = geometry.computeIfAbsent(candidate.model, model -> surfaces(model, candidate.roof));
                snow = build(state.client, triangles);
                state.lastBuilds++;
                if (snow != null || triangles.isEmpty()) { cache.put(candidate.model, snow); }
                else { state.retryAt = Math.min(state.retryAt, state.lastCycle + 50); }
            }
            if (snow == null) { return; }
            RuneLiteObject object = state.client.createRuneLiteObject();
            object.setModel(snow);
            LocalPoint location = candidate.object.getLocalLocation();
            object.setLocation(new LocalPoint(location.getX() + candidate.offsetX,
                location.getY() + candidate.offsetY, location.getWorldView()), candidate.object.getPlane());
            object.setZ(candidate.object.getZ()); object.setOrientation(candidate.orientation); object.setActive(true);
            entry = new Entry(candidate, object); entries.add(entry);
        }
        entry.seen = true; scan.active++;
        LocalPoint location = candidate.object.getLocalLocation();
        state.retainedColumns.set((location.getSceneX() + state.offset) * state.size
            + location.getSceneY() + state.offset);
    }

    /** Cleanup is also incremental, so a camera turn cannot restore hundreds of roofs in one frame. */
    private static boolean cleanup(State state, Scan scan)
    {
        if (scan.cleanupObjects == null)
        {
            scan.cleanupObjects = state.entries.entrySet().iterator();
            scan.cleanupRoofs = state.roofs.values().iterator();
            state.retainedColumns.clear();
        }
        if (scan.cleanupObjects.hasNext())
        {
            Map.Entry<TileObject, List<Entry>> object = scan.cleanupObjects.next();
            List<Entry> entries = object.getValue();
            entries.removeIf(entry -> { if (!entry.seen) { entry.clear(); return true; } return false; });
            if (entries.isEmpty()) { scan.cleanupObjects.remove(); }
            else
            {
                LocalPoint point = object.getKey().getLocalLocation();
                state.retainedColumns.set((point.getSceneX() + state.offset) * state.size + point.getSceneY() + state.offset);
            }
            return false;
        }
        if (scan.cleanupRoofs.hasNext())
        {
            Roof roof = scan.cleanupRoofs.next();
            if (!roof.seen)
            {
                if (roof.restore()) { state.dirty(roof.x, roof.y); }
                scan.cleanupRoofs.remove();
            }
            return false;
        }
        state.nativeRoofs = scan.nativeRoofs;
        // Native models share material arrays across zones. A fresh mutation
        // needs all aliases refreshed, but uploads drain a few zones each cycle.
        if (scan.nativeChanged) { state.dirty.set(0, state.width * state.width); }
        return true;
    }

    static void restore(Object owner)
    {
        State state = STATES.remove(owner);
        if (state == null) { return; }
        for (List<Entry> entries : state.entries.values()) { for (Entry entry : entries) { entry.clear(); } }
        for (Roof roof : state.roofs.values()) { if (roof.restore()) { state.dirty(roof.x, roof.y); } }
        if (WinterRoofMaterial.restore(state)) { state.dirty.set(0, state.width * state.width); }
        state.invalidate(Integer.MAX_VALUE);
    }

    static int getCount(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return 0; }
        int count = state.roofs.size() + state.nativeRoofs;
        for (List<Entry> entries : state.entries.values()) { count += entries.size(); }
        return count;
    }

    private static boolean inRegion(Scene scene, int x, int y)
    {
        int wx = scene.getBaseX() + x, wy = scene.getBaseY() + y;
        return SeasonalWorldArea.contains(wx, wy);
    }

    static boolean exposed(Scene scene, int plane, int x, int y)
    {
        return exposed(scene.getExtendedTiles(), scene.getExtendedTileSettings(), plane, x, y);
    }

    private static boolean exposed(Tile[][][] tiles, byte[][][] flags, int plane, int x, int y)
    {
        if (tiles == null || tiles.length == 0 || tiles[0] == null
            || flags == null || flags.length == 0 || flags[0] == null) { return false; }
        int tileOffset = (tiles[0].length - Constants.SCENE_SIZE) / 2;
        int offset = (flags[0].length - Constants.SCENE_SIZE) / 2;
        for (int upper = plane + 1; upper < tiles.length; upper++)
        {
            int fx = x + offset, fy = y + offset;
            if (upper < flags.length && flags[upper] != null && fx >= 0 && fx < flags[upper].length
                && flags[upper][fx] != null && fy >= 0 && fy < flags[upper][fx].length
                && (flags[upper][fx][fy] & Constants.TILE_FLAG_UNDER_ROOF) != 0) { return false; }
            int tx = x + tileOffset, ty = y + tileOffset;
            if (tiles[upper] == null || tx < 0 || tx >= tiles[upper].length || tiles[upper][tx] == null
                || ty < 0 || ty >= tiles[upper][tx].length) { continue; }
            Tile cover = tiles[upper][tx][ty];
            if (visibleFloor(cover) || roofObjectOn(cover)) { return false; }
        }
        return true;
    }

    static boolean underRoof(Scene scene, int plane, int x, int y)
    {
        return underRoof(scene.getExtendedTileSettings(), plane, x, y);
    }

    private static boolean underRoof(byte[][][] flags, int plane, int x, int y)
    {
        if (flags == null || flags.length == 0 || flags[0] == null || plane < 0 || plane >= flags.length) { return true; }
        int offset = (flags[0].length - Constants.SCENE_SIZE) / 2;
        int fx = x + offset, fy = y + offset;
        return flags[plane] == null || fx < 0 || fx >= flags[plane].length || flags[plane][fx] == null
            || fy < 0 || fy >= flags[plane][fx].length
            || (flags[plane][fx][fy] & Constants.TILE_FLAG_UNDER_ROOF) != 0;
    }

    private static boolean footprintExposed(Tile[][][] tiles, byte[][][] flags, GameObject object, boolean roof)
    {
        if (object.getSceneMinLocation() == null || object.getSceneMaxLocation() == null) { return false; }
        for (int x = object.getSceneMinLocation().getX(); x <= object.getSceneMaxLocation().getX(); x++)
        {
            for (int y = object.getSceneMinLocation().getY(); y <= object.getSceneMaxLocation().getY(); y++)
            {
                if (!exposed(tiles, flags, object.getPlane(), x, y)
                    || !roof && underRoof(flags, object.getPlane(), x, y)) { return false; }
            }
        }
        return true;
    }

    static boolean visibleFloor(Tile tile)
    {
        if (tile == null) { return false; }
        SceneTilePaint paint = tile.getSceneTilePaint();
        if (paint != null) { return paint.getNeColor() != HIDDEN; }
        SceneTileModel model = tile.getSceneTileModel();
        if (model == null || model.getTriangleColorA() == null) { return false; }
        for (int color : model.getTriangleColorA()) { if (color != HIDDEN && color >= 0) { return true; } }
        return false;
    }

    private static boolean roofObjectOn(Tile tile)
    {
        if (tile == null || tile.getGameObjects() == null) { return false; }
        for (GameObject object : tile.getGameObjects())
        {
            if (object != null) { int type = object.getConfig() & 31; if (type >= 12 && type <= 21) { return true; } }
        }
        return false;
    }

    private static String name(Client client, TileObject object)
    {
        ObjectComposition definition = client.getObjectDefinition(object.getId());
        String name = definition == null ? null : definition.getName();
        return name == null ? "" : name.toLowerCase(java.util.Locale.ROOT);
    }

    private static boolean vegetation(String name)
    {
        return name.contains("tree") || name.contains("bush") || name.contains("branch")
            || name.contains("vine") || name.contains("plant") || name.contains("hedge");
    }

    private static boolean furnitureOrStructure(String name)
    {
        return name.contains("chair") || name.contains("stool") || name.contains("bench")
            || name.contains("fence") || name.contains("wall") || name.contains("railing")
            || name.contains("battlement") || name.contains("parapet");
    }

    private static boolean isRoof(String name, int config)
    {
        int type = config & 31;
        return name.contains("roof") || type >= 12 && type <= 21;
    }

    private static void candidate(State state, Deque<Candidate> candidates, TileObject object, Renderable renderable,
        int slot, int orientation, int offsetX, int offsetY, boolean roof, boolean nativeMaterial, LocalPoint player)
    {
        if (!(renderable instanceof Model) || object.getLocalLocation() == null) { return; }
        long dx = object.getLocalLocation().getX() - player.getX();
        long dy = object.getLocalLocation().getY() - player.getY();
        long distance = dx * dx + dy * dy;
        int radius = state.entries.containsKey(object) ? SCAN_RADIUS : RADIUS;
        if (distance <= (long) radius * radius * 128 * 128)
        {
            candidates.add(new Candidate(object, (Model) renderable, slot, orientation,
                offsetX, offsetY, roof, nativeMaterial, distance));
        }
    }

    private static Model build(Client client, List<Triangle> triangles)
    {
        if (triangles.isEmpty()) { return null; }
        ModelData template = client.loadModelData(27835);
        if (template == null) { return null; }
        ModelData data = client.mergeModels(template);
        if (data == null || data.getFaceIndices1() == template.getFaceIndices1()
            || data.getFaceIndices2() == template.getFaceIndices2()
            || data.getFaceIndices3() == template.getFaceIndices3()) { return null; }
        data.cloneVertices().cloneColors().cloneTransparencies(true);
        if (data.getFaceTextures() != null) { data.cloneTextures(); }
        if (writeTriangles(data, triangles) == 0) { return null; }
        data.translate(0, 0, 0);
        return data.light(88, ModelData.DEFAULT_CONTRAST, ModelData.DEFAULT_X,
            ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
    }

    static List<Triangle> surfaces(Model model, boolean roof)
    {
        List<Triangle> triangles = new ArrayList<>();
        float[] x = model.getVerticesX(), y = model.getVerticesY(), z = model.getVerticesZ();
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        if (x == null || y == null || z == null || a == null || b == null || c == null) { return triangles; }
        int[] colors = model.getFaceColors3();
        byte[] alpha = model.getFaceTransparencies();
        short[] textures = model.getFaceTextures();
        int count = Math.min(model.getFaceCount(), Math.min(a.length, Math.min(b.length, c.length)));
        if (colors != null) { count = Math.min(count, colors.length); }
        if (alpha != null) { count = Math.min(count, alpha.length); }
        if (textures != null) { count = Math.min(count, textures.length); }
        int vertices = Math.min(model.getVerticesCount(), Math.min(x.length, Math.min(y.length, z.length)));
        for (int face = 0; face < count; face++)
        {
            if (colors != null && colors[face] == -2 || alpha != null && (alpha[face] & 255) > 128) { continue; }
            if (textures != null && SeasonalTextureTint.isLeafTexture(textures[face])) { continue; }
            if (a[face] < 0 || b[face] < 0 || c[face] < 0
                || a[face] >= vertices || b[face] >= vertices || c[face] >= vertices) { continue; }
            Triangle triangle = new Triangle(x[a[face]], y[a[face]], z[a[face]],
                x[b[face]], y[b[face]], z[b[face]], x[c[face]], y[c[face]], z[c[face]]);
            if (triangle.area >= 1 && triangle.ny < (roof ? -0.35 : -0.85)) { triangles.add(triangle); }
        }
        // A chair seat shelters the tops of its legs; upper rails similarly
        // shield surfaces directly below. Use the mesh itself for this local cover.
        List<Triangle> exposed = new ArrayList<>();
        for (Triangle triangle : triangles)
        {
            boolean covered = false;
            double cx = (triangle.xyz[0] + triangle.xyz[3] + triangle.xyz[6]) / 3.0;
            double cy = (triangle.xyz[1] + triangle.xyz[4] + triangle.xyz[7]) / 3.0;
            double cz = (triangle.xyz[2] + triangle.xyz[5] + triangle.xyz[8]) / 3.0;
            for (Triangle above : triangles)
            {
                if (above == triangle) { continue; }
                double ax = above.xyz[0], az = above.xyz[2];
                double bx = above.xyz[3], bz = above.xyz[5], tx = above.xyz[6], tz = above.xyz[8];
                double denominator = (bz - tz) * (ax - tx) + (tx - bx) * (az - tz);
                if (Math.abs(denominator) < 0.001) { continue; }
                double u = ((bz - tz) * (cx - tx) + (tx - bx) * (cz - tz)) / denominator;
                double v = ((tz - az) * (cx - tx) + (ax - tx) * (cz - tz)) / denominator;
                double w = 1 - u - v;
                if (u >= -0.001 && v >= -0.001 && w >= -0.001
                    && u * above.xyz[1] + v * above.xyz[4] + w * above.xyz[7] < cy - 1)
                {
                    covered = true; break;
                }
            }
            if (!covered) { exposed.add(triangle); }
        }
        triangles = exposed;
        triangles.sort(Comparator.comparingDouble((Triangle triangle) -> triangle.area).reversed());
        return triangles;
    }

    /** Writes independently owned template arrays; never edits the source object's mesh. */
    static int writeTriangles(ModelData data, List<Triangle> triangles)
    {
        float[] x = data.getVerticesX(), y = data.getVerticesY(), z = data.getVerticesZ();
        int[] a = data.getFaceIndices1(), b = data.getFaceIndices2(), c = data.getFaceIndices3();
        short[] colors = data.getFaceColors();
        byte[] alpha = data.getFaceTransparencies();
        if (x == null || y == null || z == null || a == null || b == null || c == null
            || colors == null || alpha == null) { return 0; }
        Arrays.fill(x, 0); Arrays.fill(y, 0); Arrays.fill(z, 0);
        Arrays.fill(a, 0); Arrays.fill(b, 0); Arrays.fill(c, 0);
        Arrays.fill(alpha, (byte) 255);
        if (data.getFaceTextures() != null) { Arrays.fill(data.getFaceTextures(), (short) -1); }
        int vertices = Math.min(data.getVerticesCount(), Math.min(x.length, Math.min(y.length, z.length)));
        int faces = Math.min(data.getFaceCount(), Math.min(a.length, Math.min(b.length, c.length)));
        int count = Math.min(Math.min(MAX_FACES, triangles.size()), Math.min(faces, vertices / 3));
        for (int face = 0; face < count; face++)
        {
            Triangle triangle = triangles.get(face);
            for (int vertex = 0; vertex < 3; vertex++)
            {
                int index = face * 3 + vertex;
                x[index] = (float) (triangle.xyz[vertex * 3] + triangle.nx * 0.9);
                y[index] = (float) (triangle.xyz[vertex * 3 + 1] + triangle.ny * 0.9);
                z[index] = (float) (triangle.xyz[vertex * 3 + 2] + triangle.nz * 0.9);
            }
            a[face] = face * 3; b[face] = face * 3 + 1; c[face] = face * 3 + 2;
            colors[face] = (short) (36 << 10 | 104);
            alpha[face] = 0;
        }
        return count;
    }

    static final class Triangle
    {
        final float[] xyz;
        final double nx, ny, nz, area;
        Triangle(float... xyz)
        {
            this.xyz = xyz.clone();
            double ux = xyz[3] - xyz[0], uy = xyz[4] - xyz[1], uz = xyz[5] - xyz[2];
            double vx = xyz[6] - xyz[0], vy = xyz[7] - xyz[1], vz = xyz[8] - xyz[2];
            double ax = uy * vz - uz * vy, ay = uz * vx - ux * vz, az = ux * vy - uy * vx;
            double length = Math.sqrt(ax * ax + ay * ay + az * az);
            area = length * 0.5;
            nx = length == 0 ? 0 : ax / length;
            ny = length == 0 ? 0 : ay / length;
            nz = length == 0 ? 0 : az / length;
        }
    }

    private static final class Candidate
    {
        final TileObject object;
        final Model model;
        final int slot, orientation, offsetX, offsetY;
        final boolean roof, nativeMaterial;
        final long distance;
        Candidate(TileObject object, Model model, int slot, int orientation, int offsetX, int offsetY,
            boolean roof, boolean nativeMaterial, long distance)
        {
            this.object = object; this.model = model; this.slot = slot; this.orientation = orientation;
            this.offsetX = offsetX; this.offsetY = offsetY; this.roof = roof;
            this.nativeMaterial = nativeMaterial; this.distance = distance;
        }
    }

    private static final class Entry
    {
        final Model model;
        final RuneLiteObject snow;
        final int slot, orientation, offsetX, offsetY, x, y, z, plane;
        boolean seen;
        Entry(Candidate candidate, RuneLiteObject snow)
        {
            this.model = candidate.model; this.snow = snow; slot = candidate.slot;
            orientation = candidate.orientation; offsetX = candidate.offsetX; offsetY = candidate.offsetY;
            x = candidate.object.getX(); y = candidate.object.getY(); z = candidate.object.getZ();
            plane = candidate.object.getPlane();
        }
        boolean matches(Candidate candidate)
        {
            return candidate.model == model && orientation == candidate.orientation
                && offsetX == candidate.offsetX && offsetY == candidate.offsetY
                && x == candidate.object.getX() && y == candidate.object.getY()
                && z == candidate.object.getZ() && plane == candidate.object.getPlane();
        }
        void clear() { snow.setActive(false); }
    }

    private static final class Scan
    {
        final LocalPoint point;
        final WinterSnowVisibility view;
        final Tile[][][] tiles;
        final byte[][][] flags;
        final int[][][] heights;
        final Set<TileObject> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        final Deque<Candidate> pending = new ArrayDeque<>();
        int position, active, nativeRoofs;
        Iterator<Map.Entry<TileObject, List<Entry>>> cleanupObjects;
        Iterator<Roof> cleanupRoofs;
        boolean nativeChanged;
        Scan(State state, LocalPoint point, WinterSnowVisibility view, Tile[][][] tiles, byte[][][] flags,
            int[][][] heights)
        {
            this.point = point; this.view = view; this.tiles = tiles; this.flags = flags; this.heights = heights;
            for (Roof roof : state.roofs.values()) { roof.seen = false; }
            for (List<Entry> entries : state.entries.values()) { for (Entry entry : entries) { entry.seen = false; } }
        }
    }

    private static final class State
    {
        final Client client;
        final Scene scene;
        final Map<Tile, Roof> roofs = new IdentityHashMap<>();
        final Map<TileObject, List<Entry>> entries = new IdentityHashMap<>();
        final BitSet dirty = new BitSet(), urgent = new BitSet(), retainedColumns = new BitSet();
        final Map<Model, Integer> nativeModels = new IdentityHashMap<>();
        final Map<Model, Model> roofModels = new IdentityHashMap<>(), surfaceModels = new IdentityHashMap<>();
        final Map<Model, List<Triangle>> roofGeometry = new IdentityHashMap<>(), surfaceGeometry = new IdentityHashMap<>();
        Scan scan;
        WinterSnowVisibility lastView;
        boolean rescan = true;
        int uploadCursor, lastTiles, lastModels, lastCandidates, lastBuilds, lastGpuZones, lastPlane = -1;
        int retryAt = Integer.MAX_VALUE;
        long lastWorkNanos, maxWorkNanos;
        final int offset, width, size, baseX, baseY;
        int lastCycle = Integer.MIN_VALUE, nativeRoofs;
        State(Client client, Scene scene)
        {
            this.client = client; this.scene = scene;
            baseX = scene.getBaseX(); baseY = scene.getBaseY();
            size = scene.getExtendedTiles()[0].length;
            offset = (size - Constants.SCENE_SIZE) / 2;
            width = (size + 7) >> 3;
        }
        void dirty(int x, int y)
        {
            int bit = ((x + offset) >> 3) * width + ((y + offset) >> 3);
            dirty.set(bit); urgent.set(bit);
        }
        void invalidate(int budget)
        {
            if (client.getDrawCallbacks() instanceof GpuPlugin && client.getTopLevelWorldView() != null)
            {
                Scene current = client.getTopLevelWorldView().getScene();
                if (current == scene)
                {
                    int uploaded = 0;
                    while (!dirty.isEmpty() && uploaded < budget)
                    {
                        int bit = urgent.nextSetBit(0);
                        boolean nearby = bit >= 0 && (uploaded & 1) == 0;
                        if (!nearby)
                        {
                            bit = dirty.nextSetBit(uploadCursor);
                            if (bit < 0) { bit = dirty.nextSetBit(0); }
                            uploadCursor = bit + 1;
                        }
                        client.getDrawCallbacks().invalidateZone(scene, bit / width, bit % width);
                        dirty.clear(bit); urgent.clear(bit);
                        uploaded++; lastGpuZones++;
                    }
                    return;
                }
                else if (current != null && !dirty.isEmpty())
                {
                    // The replacement scene may already have uploaded shared
                    // roof models before their old seasonal state was restored.
                    Tile[][][] tiles = current.getExtendedTiles();
                    if (tiles != null && tiles.length > 0 && tiles[0] != null)
                    {
                        int currentWidth = (tiles[0].length + 7) >> 3;
                        for (int x = 0; x < currentWidth; x++)
                        {
                            for (int y = 0; y < currentWidth; y++)
                            {
                                client.getDrawCallbacks().invalidateZone(current, x, y);
                            }
                        }
                    }
                }
            }
            dirty.clear(); urgent.clear();
        }
    }

    private static final class Values
    {
        final int[] original, last;
        final BitSet conflicts = new BitSet();
        Values(int[] values) { original = values.clone(); last = values.clone(); }
        boolean set(int[] current, int index, int desired)
        {
            if (current[index] != last[index]) { conflicts.set(index); }
            if (conflicts.get(index)) { return false; }
            boolean changed = current[index] != desired;
            current[index] = last[index] = desired;
            return changed;
        }
        boolean restore(int[] current)
        {
            boolean changed = false;
            for (int i = 0; i < current.length; i++)
            {
                if (!conflicts.get(i) && current[i] == last[i])
                {
                    changed |= current[i] != original[i]; current[i] = original[i];
                }
            }
            return changed;
        }
    }

    private static final class Roof
    {
        final Tile tile;
        final int x, y;
        final SceneTilePaint paint;
        final SceneTileModel model;
        final Values[] colors;
        final Values textures;
        final int originalTexture;
        int lastTexture;
        boolean textureConflict, seen;
        Roof(Tile tile, int x, int y)
        {
            this.tile = tile; this.x = x; this.y = y;
            paint = tile.getSceneTilePaint(); model = tile.getSceneTileModel();
            if (paint != null)
            {
                colors = new Values[]{new Values(paintColors())}; textures = null;
                originalTexture = lastTexture = paint.getTexture();
            }
            else
            {
                colors = new Values[]{new Values(model.getTriangleColorA()), new Values(model.getTriangleColorB()),
                    new Values(model.getTriangleColorC())};
                textures = model.getTriangleTextureId() == null ? null : new Values(model.getTriangleTextureId());
                originalTexture = lastTexture = -1;
            }
        }
        int[] paintColors() { return new int[]{paint.getSwColor(), paint.getSeColor(), paint.getNeColor(), paint.getNwColor()}; }
        void setPaint(int[] values)
        {
            paint.setSwColor(values[0]); paint.setSeColor(values[1]); paint.setNeColor(values[2]); paint.setNwColor(values[3]);
        }
        boolean apply()
        {
            boolean changed = false;
            if (paint != null)
            {
                if (paint.getTexture() != lastTexture) { textureConflict = true; }
                if (textureConflict) { return false; }
                changed = paint.getTexture() != -1;
                paint.setTexture(lastTexture = -1);
                int[] current = paintColors();
                for (int corner = 0; corner < 4; corner++)
                {
                    changed |= colors[0].set(current, corner, snow(colors[0].original[corner]));
                }
                setPaint(current);
            }
            else
            {
                int[][] current = {model.getTriangleColorA(), model.getTriangleColorB(), model.getTriangleColorC()};
                int[] texture = model.getTriangleTextureId();
                for (int face = 0; face < current[0].length; face++)
                {
                    if (colors[0].original[face] == HIDDEN) { continue; }
                    if (texture != null) { changed |= textures.set(texture, face, -1); }
                    for (int channel = 0; channel < current.length; channel++)
                    {
                        changed |= colors[channel].set(current[channel], face, snow(colors[channel].original[face]));
                    }
                }
            }
            return changed;
        }
        boolean restore()
        {
            boolean changed = false;
            if (paint != null)
            {
                int[] current = paintColors(); changed |= colors[0].restore(current); setPaint(current);
                if (!textureConflict && paint.getTexture() == lastTexture)
                {
                    changed |= paint.getTexture() != originalTexture; paint.setTexture(originalTexture);
                }
            }
            else
            {
                changed |= colors[0].restore(model.getTriangleColorA());
                changed |= colors[1].restore(model.getTriangleColorB());
                changed |= colors[2].restore(model.getTriangleColorC());
                if (textures != null) { changed |= textures.restore(model.getTriangleTextureId()); }
            }
            return changed;
        }
        int snow(int original) { return original < 0 || original == HIDDEN ? original : 36 << 10 | 96 + (original & 127) * 16 / 127; }
    }
}

package com.seasonalscape;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.WeakHashMap;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Small snow deposits that follow foliage surfaces without replacing their cutout texture. */
final class WinterTreeFrost
{
    private static final Map<Object, State> STATES = new WeakHashMap<>();
    private static final int MAX_TREES = 24;
    private static final int RADIUS = 24 * 128, RETAIN_RADIUS = 26 * 128;
    private static final int MAX_CACHED_MODELS = 48;

    private WinterTreeFrost() {}

    static void begin(Object owner)
    {
        State state = STATES.get(owner);
        if (state != null)
        {
            for (Entry entry : state.entries.values()) { entry.seen = false; }
        }
    }

    /** Records the existing, already oriented tree mesh; creation is distance limited in refresh. */
    static boolean update(Object owner, Client client, GameObject tree, Model model)
    {
        short[] textures = model.getFaceTextures();
        if (textures == null) { return false; }
        boolean leaves = false;
        for (short texture : textures) { leaves |= SeasonalTextureTint.isLeafTexture(texture); }
        if (!leaves) { return false; }
        WorldView world = client.getTopLevelWorldView();
        Scene scene = world == null ? null : world.getScene();
        State state = STATES.get(owner);
        if (state != null && (state.scene != scene || scene == null
            || state.baseX != scene.getBaseX() || state.baseY != scene.getBaseY()))
        {
            restore(owner);
            state = null;
        }
        if (state == null)
        {
            state = new State();
            state.scene = scene;
            state.baseX = scene == null ? 0 : scene.getBaseX();
            state.baseY = scene == null ? 0 : scene.getBaseY();
            STATES.put(owner, state);
        }
        state.client = client;
        Entry entry = state.entries.get(tree);
        if (entry == null || entry.model != model)
        {
            if (entry != null) { entry.clear(); state.models.remove(entry); }
            entry = new Entry(tree, model);
            state.entries.put(tree, entry);
        }
        entry.seen = true;
        return true;
    }

    static void end(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return; }
        Iterator<Entry> iterator = state.entries.values().iterator();
        while (iterator.hasNext())
        {
            Entry entry = iterator.next();
            if (!entry.seen) { entry.clear(); state.models.remove(entry); iterator.remove(); }
        }
        refresh(owner, state.client);
    }

    /** Called each game tick so walking does not require a full terrain scan. */
    static void refresh(Object owner, Client client)
    {
        State state = STATES.get(owner);
        if (state == null || client == null) { return; }
        if (!ready(state, client)) { restore(owner); return; }
        Player player = client.getLocalPlayer();
        LocalPoint point = player == null ? null : player.getLocalLocation();
        List<Entry> nearby = new ArrayList<>();
        for (Entry entry : state.entries.values())
        {
            LocalPoint location = entry.tree.getLocalLocation();
            entry.wanted = false;
            if (point == null || location == null || location.getWorldView() != point.getWorldView()
                || entry.tree.getPlane() != player.getWorldLocation().getPlane()) { continue; }
            long dx = location.getX() - point.getX(), dy = location.getY() - point.getY();
            entry.distance = dx * dx + dy * dy;
            int radius = entry.object == null ? RADIUS : RETAIN_RADIUS;
            if (entry.distance <= (long) radius * radius) { nearby.add(entry); }
        }
        nearby.sort(Comparator.comparingLong(entry -> entry.distance));
        state.selected.clear();
        for (int i = 0; i < Math.min(MAX_TREES, nearby.size()); i++)
        {
            Entry entry = nearby.get(i);
            entry.wanted = true;
            state.selected.add(entry);
        }
        for (Entry entry : state.entries.values())
        {
            if (!entry.wanted) { entry.clear(); }
        }
    }

    /** At most one model build/object activation per client cycle, never on camera rotation. */
    static void tick(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return; }
        Client client = state.client;
        if (!ready(state, client)) { restore(owner); return; }
        int cycle = client.getGameCycle();
        if (state.lastCycle == cycle) { return; }
        state.lastCycle = cycle;
        state.lastBuilds = 0;
        for (Entry entry : state.selected)
        {
            if (!entry.wanted || entry.object != null || cycle < entry.retryCycle) { continue; }
            Model snow = state.models.get(entry);
            if (snow == null)
            {
                state.lastBuilds = 1;
                snow = createModel(client, entry.model,
                    ((long) entry.tree.getX() << 32) ^ entry.tree.getY() ^ entry.tree.getId());
                if (snow == null) { entry.retryCycle = cycle + 50; return; }
                state.models.put(entry, snow);
                if (state.models.size() > MAX_CACHED_MODELS)
                {
                    state.models.remove(state.models.keySet().iterator().next());
                }
            }
            RuneLiteObject object = client.createRuneLiteObject();
            object.setModel(snow);
            object.setLocation(entry.tree.getLocalLocation(), entry.tree.getPlane());
            object.setZ(entry.tree.getZ());
            object.setOrientation(entry.tree.getModelOrientation());
            object.setActive(true);
            entry.object = object;
            return;
        }
    }

    private static boolean ready(State state, Client client)
    {
        WorldView world = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        LocalPoint point = player == null ? null : player.getLocalLocation();
        return client.getGameState() == GameState.LOGGED_IN && world != null && world.isTopLevel()
            && !world.isInstance() && world.getPlane() == 0 && world.getScene() == state.scene
            && SeasonalSceneRecolorer.supports(state.scene) && point != null
            && state.scene.getBaseX() == state.baseX && state.scene.getBaseY() == state.baseY
            && point.getWorldView() == world.getId()
            && SeasonalWorldArea.contains(state.scene.getBaseX() + point.getSceneX(),
                state.scene.getBaseY() + point.getSceneY())
            && (client.getDrawCallbacks() == null || client.getDrawCallbacks() instanceof GpuPlugin);
    }

    static int getCount(Object owner)
    {
        State state = STATES.get(owner);
        if (state == null) { return 0; }
        int count = 0;
        for (Entry entry : state.entries.values()) { if (entry.object != null) { count++; } }
        return count;
    }

    static void remove(Object owner, GameObject tree)
    {
        State state = STATES.get(owner);
        if (state == null) { return; }
        Entry entry = state.entries.remove(tree);
        if (entry == null) { return; }
        entry.clear();
        state.selected.remove(entry);
        state.models.remove(entry);
    }

    static void restore(Object owner)
    {
        State state = STATES.remove(owner);
        if (state != null) { for (Entry entry : state.entries.values()) { entry.clear(); } }
    }

    private static Model createModel(Client client, Model tree, long seed)
    {
        ModelData source = client.loadModelData(27835);
        if (source == null || source.getVerticesCount() < 3 || source.getVerticesCount() > 8192
            || source.getFaceCount() == 0 || source.getFaceCount() > 8192) { return null; }
        List<Surface> surfaces = surfaces(tree);
        if (surfaces.isEmpty()) { return null; }
        ModelData data = source.shallowCopy().cloneVertices().cloneColors();
        if (data.getFaceTextures() != null)
        {
            data.cloneTextures();
            Arrays.fill(data.getFaceTextures(), (short) -1);
        }
        data.cloneTransparencies(true);
        Arrays.fill(data.getFaceTransparencies(), (byte) 0);
        GroundCover.reshapeFlakes(source, data, Season.WINTER, 0);
        fit(source, data, surfaces, seed);
        data.translate(0, 0, 0);
        return data.light(90, ModelData.DEFAULT_CONTRAST,
            ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
    }

    /** Fits each connected particle to one triangle, keeping every patch inside its leaf surface. */
    static void fit(ModelData source, ModelData target, List<Surface> surfaces, long seed)
    {
        int[] parents = new int[source.getVerticesCount()];
        for (int i = 0; i < parents.length; i++) { parents[i] = i; }
        int[] a = source.getFaceIndices1(), b = source.getFaceIndices2(), c = source.getFaceIndices3();
        for (int i = 0; i < source.getFaceCount(); i++)
        {
            parents[root(parents, b[i])] = root(parents, a[i]);
            parents[root(parents, c[i])] = root(parents, a[i]);
        }
        Map<Integer, List<Integer>> groups = new LinkedHashMap<>();
        for (int i = 0; i < parents.length; i++)
        {
            groups.computeIfAbsent(root(parents, i), unused -> new ArrayList<>()).add(i);
        }
        float[] x = target.getVerticesX(), y = target.getVerticesY(), z = target.getVerticesZ();
        Random random = new Random(seed);
        double total = 0;
        for (Surface surface : surfaces) { total += surface.area; }
        int visible = 0;
        for (List<Integer> vertices : groups.values())
        {
            double minX = Double.POSITIVE_INFINITY, maxX = Double.NEGATIVE_INFINITY;
            double minZ = Double.POSITIVE_INFINITY, maxZ = Double.NEGATIVE_INFINITY;
            for (int vertex : vertices)
            {
                minX = Math.min(minX, x[vertex]); maxX = Math.max(maxX, x[vertex]);
                minZ = Math.min(minZ, z[vertex]); maxZ = Math.max(maxZ, z[vertex]);
            }
            if (vertices.size() < 3 || maxX - minX < 0.01 || maxZ - minZ < 0.01
                || visible++ >= 16 || total == 0)
            {
                for (int vertex : vertices) { x[vertex] = 0; y[vertex] = 0; z[vertex] = 0; }
                continue;
            }
            double chosen = random.nextDouble() * total;
            Surface surface = surfaces.get(surfaces.size() - 1);
            for (Surface candidate : surfaces)
            {
                chosen -= candidate.area;
                if (chosen <= 0) { surface = candidate; break; }
            }
            // Keep centers away from polygon edges where leaf textures become transparent.
            double u = 0.18 + random.nextDouble() * 0.46;
            double v = 0.18 + random.nextDouble() * (0.82 - u - 0.18);
            double[] center = add(surface.a, add(scale(surface.ab, u), scale(surface.ac, v)));
            double clearance = Math.min(distanceToLine(center, surface.a, surface.b),
                Math.min(distanceToLine(center, surface.b, surface.c), distanceToLine(center, surface.c, surface.a)));
            double radius = Math.min(14 + random.nextDouble() * 10, clearance * 0.72);
            double centerX = (minX + maxX) / 2, centerZ = (minZ + maxZ) / 2;
            double oldRadius = 0;
            for (int vertex : vertices)
            {
                oldRadius = Math.max(oldRadius, Math.hypot(x[vertex] - centerX, z[vertex] - centerZ));
            }
            for (int vertex : vertices)
            {
                double dx = x[vertex] - centerX, dz = z[vertex] - centerZ;
                double distance = Math.hypot(dx, dz);
                double along = 0, across = 0;
                if (distance > Math.max(0.001, oldRadius * 0.04))
                {
                    // The cache particle has a pointed star silhouette. Move
                    // its perimeter onto a gently uneven oval, preserving the
                    // angular order and central vertices of the existing mesh.
                    double angle = Math.atan2(dz, dx);
                    double edge = radius * (0.89 + 0.09 * Math.sin(angle * 3 + visible * 1.7));
                    along = dx / distance * edge;
                    across = dz / distance * edge * 0.78;
                }
                double[] fitted = add(center, add(scale(surface.tangent, along),
                    add(scale(surface.bitangent, across), scale(surface.normal, 1.4))));
                x[vertex] = (float) fitted[0]; y[vertex] = (float) fitted[1]; z[vertex] = (float) fitted[2];
            }
        }
        short[] colors = target.getFaceColors();
        for (int i = 0; i < colors.length; i++)
        {
            colors[i] = JagexColor.packHSL(36, 0, 106 + Math.floorMod(root(parents, a[i]), 4) * 3);
        }
    }

    static List<Surface> surfaces(Model tree)
    {
        List<Surface> surfaces = new ArrayList<>();
        short[] textures = tree.getFaceTextures();
        float[] x = tree.getVerticesX(), y = tree.getVerticesY(), z = tree.getVerticesZ();
        int[] a = tree.getFaceIndices1(), b = tree.getFaceIndices2(), c = tree.getFaceIndices3();
        if (textures == null || x == null || y == null || z == null || a == null || b == null || c == null)
        {
            return surfaces;
        }
        int faces = Math.min(Math.min(textures.length, a.length), Math.min(b.length, c.length));
        if (faces > 8192) { return surfaces; }
        float top = Float.POSITIVE_INFINITY, bottom = Float.NEGATIVE_INFINITY;
        for (int face = 0; face < faces; face++)
        {
            if (!SeasonalTextureTint.isLeafTexture(textures[face])) { continue; }
            for (int vertex : new int[]{a[face], b[face], c[face]})
            {
                if (vertex < 0 || vertex >= x.length || vertex >= y.length || vertex >= z.length)
                { return new ArrayList<>(); }
                top = Math.min(top, y[vertex]); bottom = Math.max(bottom, y[vertex]);
            }
        }
        float cutoff = top + (bottom - top) * 0.72f;
        for (int face = 0; face < faces; face++)
        {
            if (!SeasonalTextureTint.isLeafTexture(textures[face])
                || (y[a[face]] + y[b[face]] + y[c[face]]) / 3f > cutoff) { continue; }
            Surface surface = new Surface(point(x, y, z, a[face]), point(x, y, z, b[face]), point(x, y, z, c[face]));
            // Snow rests on upper, upward-facing foliage; keep hanging skirts and undersides green.
            if (Double.isFinite(surface.area) && surface.area >= 40 && surface.normal[1] < -0.2)
            { surfaces.add(surface); }
        }
        return surfaces;
    }

    private static int root(int[] parents, int i)
    {
        while (parents[i] != i) { parents[i] = parents[parents[i]]; i = parents[i]; }
        return i;
    }

    private static double[] point(float[] x, float[] y, float[] z, int i) { return new double[]{x[i], y[i], z[i]}; }
    private static double[] add(double[] a, double[] b) { return new double[]{a[0] + b[0], a[1] + b[1], a[2] + b[2]}; }
    private static double[] subtract(double[] a, double[] b) { return new double[]{a[0] - b[0], a[1] - b[1], a[2] - b[2]}; }
    private static double[] scale(double[] a, double n) { return new double[]{a[0] * n, a[1] * n, a[2] * n}; }
    private static double length(double[] a) { return Math.sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]); }
    private static double[] cross(double[] a, double[] b) { return new double[]{a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]}; }
    private static double distanceToLine(double[] p, double[] a, double[] b)
    {
        double[] edge = subtract(b, a);
        return length(cross(subtract(p, a), edge)) / Math.max(0.001, length(edge));
    }

    static final class Surface
    {
        final double[] a, b, c, ab, ac, normal, tangent, bitangent;
        final double area;
        Surface(double[] a, double[] b, double[] c)
        {
            this.a = a; this.b = b; this.c = c;
            ab = subtract(b, a); ac = subtract(c, a);
            double[] n = cross(ab, ac);
            area = length(n) / 2;
            normal = scale(n, 1 / Math.max(0.001, area * 2));
            tangent = scale(ab, 1 / Math.max(0.001, length(ab)));
            bitangent = cross(normal, tangent);
        }
    }

    private static final class State
    {
        final Map<GameObject, Entry> entries = new IdentityHashMap<>();
        final List<Entry> selected = new ArrayList<>();
        final Map<Entry, Model> models = new LinkedHashMap<>(64, 0.75f, true);
        Client client;
        Scene scene;
        int baseX, baseY;
        int lastCycle = Integer.MIN_VALUE, lastBuilds;
    }

    private static final class Entry
    {
        final GameObject tree;
        final Model model;
        RuneLiteObject object;
        boolean seen, wanted;
        int retryCycle;
        long distance;
        Entry(GameObject tree, Model model) { this.tree = tree; this.model = model; }
        void clear() { if (object != null) { object.setActive(false); object = null; } }
    }
}

package com.seasonalscape;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.gpu.GpuPlugin;

/** Development-launcher graphics preference; not included in the plugin JAR. */
public final class DevelopmentGraphics
{
    private DevelopmentGraphics() {}

    public static void useGpu(Consumer<String> report)
    {
        Thread worker = new Thread(() -> {
            try
            {
                PluginManager manager = RuneLite.getInjector().getInstance(PluginManager.class);
                ClientThread clientThread = RuneLite.getInjector().getInstance(ClientThread.class);
                Client client = RuneLite.getInjector().getInstance(Client.class);
                GpuPlugin[] gpu = new GpuPlugin[1];
                SwingUtilities.invokeAndWait(() -> {
                    for (Plugin plugin : manager.getPlugins())
                    {
                        if (plugin instanceof GpuPlugin) { gpu[0] = (GpuPlugin) plugin; }
                    }
                    if (gpu[0] == null) { throw new IllegalStateException("Built-in GPU plugin unavailable"); }
                    for (Plugin plugin : manager.getPlugins())
                    {
                        PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
                        if ("rs117.hd.HdPlugin".equals(plugin.getClass().getName())
                            || (descriptor != null && "117 HD".equals(descriptor.name())))
                        {
                            manager.setPluginEnabled(plugin, false);
                            try { manager.stopPlugin(plugin); }
                            catch (Exception exception) { throw new IllegalStateException("HD shutdown failed", exception); }
                        }
                    }
                });
                awaitClient(clientThread, () -> client.getDrawCallbacks() == null || client.getDrawCallbacks() == gpu[0]);
                SwingUtilities.invokeAndWait(() -> {
                    manager.setPluginEnabled(gpu[0], true);
                    try { manager.startPlugin(gpu[0]); }
                    catch (Exception exception) { throw new IllegalStateException("GPU startup failed", exception); }
                });
                awaitClient(clientThread, () -> client.getDrawCallbacks() == gpu[0]);
                RuneLite.getInjector().getInstance(ConfigManager.class)
                    .setConfiguration("gpu", "brightTextures", true);
                SwingUtilities.invokeAndWait(() -> {
                    if (!manager.isPluginActive(gpu[0]) || !manager.isPluginEnabled(gpu[0]))
                    {
                        throw new IllegalStateException("GPU was disabled during startup");
                    }
                });
                report.accept("GPU_ACTIVE: built-in RuneLite GPU verified; 117 HD disabled.");
            }
            catch (Exception exception)
            {
                report.accept("GPU_SWITCH_FAILED: " + exception.getClass().getSimpleName());
            }
        }, "SeasonalScapeGraphicsSetup");
        worker.setDaemon(true);
        worker.start();
    }

    private static void awaitClient(ClientThread clientThread, BooleanSupplier ready) throws Exception
    {
        CompletableFuture<Void> complete = new CompletableFuture<>();
        clientThread.invokeLater(() -> {
            if (complete.isDone()) { return true; }
            try
            {
                if (!ready.getAsBoolean()) { return false; }
                complete.complete(null);
            }
            catch (Exception exception) { complete.completeExceptionally(exception); }
            return true;
        });
        try { complete.get(20, TimeUnit.SECONDS); }
        finally { complete.cancel(false); }
    }
}

