    /** Models GPU uploads separately from the mutable CPU model color arrays. */
    private static final class RecordingGpu extends GpuPlugin
    {
        private final Map<Long, int[]> sources = new HashMap<>();
        private final Map<Long, int[]> uploaded = new HashMap<>();
        private final Set<Long> invalidated = new HashSet<>();
        private boolean brightTextures;

        private RecordingGpu()
        {
            GpuPluginConfig config = proxy(GpuPluginConfig.class,
                (name, args) -> name.equals("brightTextures") ? brightTextures : null);
            injector = proxy(Injector.class, (name, args) -> name.equals("getInstance") ? config : null);
        }

        private long track(int x, int y, int[] colors)
        {
            long key = (long) x << 32 | y & 0xffffffffL;
            sources.put(key, colors);
            uploaded.put(key, colors.clone());
            return key;
        }

        @Override
        public void invalidateZone(Scene scene, int x, int y)
        {
            invalidated.add((long) x << 32 | y & 0xffffffffL);
        }

        private void rebuildInvalidatedZones()
        {
            for (Long key : invalidated)
            {
                int[] source = sources.get(key);
                if (source != null) { uploaded.put(key, source.clone()); }
            }
            invalidated.clear();
        }
    }

    private static <T> T proxy(Class<T> type, BiFunction<String, Object[], Object> handler)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (object, method, args) -> {
            if (method.getName().equals("hashCode")) { return System.identityHashCode(object); }
            if (method.getName().equals("equals")) { return object == args[0]; }
            if (method.getName().equals("toString")) { return type.getSimpleName() + " test proxy"; }
            Object result = handler.apply(method.getName(), args);
            if (result != null || !method.getReturnType().isPrimitive() || method.getReturnType() == void.class)
            {
                return result;
            }
            if (method.getReturnType() == boolean.class) { return false; }
            if (method.getReturnType() == int.class) { return 0; }
            throw new AssertionError("Unexpected primitive method: " + method);
        }));
    }
}

package com.seasonalscape;

import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.function.BiFunction;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PostClientTick;
import net.runelite.client.eventbus.EventBus;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class SeasonalSceneSyncTest
{
    @Test
    public void postTickRefreshPrecedesDefaultPriorityUploadAndDoesNotRepeatBeforeRender()
    {
        try (Fixture f = new Fixture())
        {
            SeasonalSceneSync.stop(f.owner);
            int[] observedAtUpload = {-1};
            // Register the simulated GPU first, proving priority rather than
            // registration order places seasonal changes before its upload.
            EventBus.Subscriber gpu = f.bus.register(PostClientTick.class,
                event -> observedAtUpload[0] = f.refreshes, 0);
            SeasonalSceneSync.start(f.owner, f.client, () -> f.refreshes++, f.bus);
            f.state = GameState.LOGGED_IN;

            f.bus.post(new PostClientTick());
            assertEquals("GPU upload observes the already refreshed scene", 1, observedAtUpload[0]);
            f.frame();
            assertEquals("BeforeRender reuses the completed post-tick refresh", 1, f.refreshes);

            SeasonalSceneSync.requestRefresh(f.owner);
            f.bus.post(new PostClientTick());
            assertEquals(2, observedAtUpload[0]);
            f.frame();
            assertEquals(2, f.refreshes);
            f.bus.unregister(gpu);
        }
    }

    @Test
    public void loadingRefreshesOnTheFirstLoggedInFrameWithoutWaitingForAGameTick()
    {
        try (Fixture f = new Fixture())
        {
            f.frame();
            SeasonalSceneSync.requestRefresh(f.owner);
            f.changeState(GameState.LOADING);
            f.frame();
            assertEquals("Loading retains pending work", 0, f.refreshes);

            f.changeState(GameState.LOGGED_IN);
            assertEquals("State events do not read or modify the scene", 0, f.refreshes);
            f.frame();
            assertEquals(1, f.refreshes);
            f.frame();
            f.frame();
            assertEquals("Stable frames do not rescan", 1, f.refreshes);
        }
    }

    @Test
    public void identityAndBothBaseCoordinatesDetectSceneChanges()
    {
        try (Fixture f = new Fixture())
        {
            f.state = GameState.LOGGED_IN;
            f.frame();
            f.scene = f.newScene();
            f.frame();
            assertEquals("A replacement Scene triggers refresh", 2, f.refreshes);
            f.baseX += 8;
            f.frame();
            assertEquals("A reused Scene with a changed X base triggers refresh", 3, f.refreshes);
            f.baseY += 8;
            f.frame();
            assertEquals("A reused Scene with a changed Y base triggers refresh", 4, f.refreshes);
            f.frame();
            assertEquals(4, f.refreshes);
        }
    }

    @Test
    public void requestsCoalesceAndWaitForClientThreadAndCompleteScene()
    {
        try (Fixture f = new Fixture())
        {
            f.state = GameState.LOGGED_IN;
            f.clientThread = false;
            f.frame();
            assertEquals(0, f.refreshes);
            f.clientThread = true;
            f.worldAvailable = false;
            f.frame();
            f.worldAvailable = true;
            Scene scene = f.scene;
            f.scene = null;
            f.frame();
            f.scene = scene;
            f.playerAvailable = false;
            f.frame();
            assertEquals("Incomplete scenes preserve pending work", 0, f.refreshes);
            f.playerAvailable = true;
            f.frame();
            assertEquals(1, f.refreshes);

            SeasonalSceneSync.requestRefresh(f.owner);
            SeasonalSceneSync.requestRefresh(f.owner);
            SeasonalSceneSync.requestRefresh(f.owner);
            f.frame();
            f.frame();
            assertEquals("Many spawn events need one refresh", 2, f.refreshes);
        }
    }

    @Test
    public void replacingAndStoppingAnOwnerUnregistersItsSubscribers()
    {
        try (Fixture f = new Fixture())
        {
            assertEquals(1, f.bus.registered.size());
            SeasonalSceneSync.start(f.owner, f.client, () -> f.refreshes += 10, f.bus);
            assertEquals("Replacing an owner leaves one subscriber", 1, f.bus.registered.size());
            f.state = GameState.LOGGED_IN;
            f.frame();
            assertEquals(10, f.refreshes);

            SeasonalSceneSync.stop(f.owner);
            assertEquals(0, f.bus.registered.size());
            SeasonalSceneSync.requestRefresh(f.owner);
            f.changeState(GameState.LOADING);
            f.changeState(GameState.LOGGED_IN);
            f.frame();
            assertEquals("Stopped owners receive no later refresh", 10, f.refreshes);
        }
    }

    private static final class Fixture implements AutoCloseable
    {
        private final Object owner = new Object();
        private final RecordingEventBus bus = new RecordingEventBus();
        private GameState state = GameState.LOADING;
        private boolean clientThread = true;
        private boolean worldAvailable = true;
        private boolean playerAvailable = true;
        private int baseX = 3200;
        private int baseY = 3200;
        private int refreshes;
        private Scene scene = newScene();
        private final Player player = proxy(Player.class, (name, args) -> null);
        private final WorldView world = proxy(WorldView.class,
            (name, args) -> name.equals("getScene") ? scene : null);
        private final Client client = proxy(Client.class, (name, args) -> {
            switch (name)
            {
                case "isClientThread": return clientThread;
                case "getGameState": return state;
                case "getTopLevelWorldView": return worldAvailable ? world : null;
                case "getLocalPlayer": return playerAvailable ? player : null;
                default: return null;
            }
        });

        private Fixture()
        {
            SeasonalSceneSync.start(owner, client, () -> refreshes++, bus);
        }

        private Scene newScene()
        {
            return proxy(Scene.class, (name, args) -> {
                if (name.equals("getBaseX")) { return baseX; }
                if (name.equals("getBaseY")) { return baseY; }
                return null;
            });
        }

        private void changeState(GameState next)
        {
            state = next;
            GameStateChanged event = new GameStateChanged();
            event.setGameState(next);
            bus.post(event);
        }

        private void frame()
        {
            bus.post(new BeforeRender());
        }

        @Override
        public void close()
        {
            SeasonalSceneSync.stop(owner);
        }
    }

    private static final class RecordingEventBus extends EventBus
    {
        private final Set<Object> registered = Collections.newSetFromMap(new IdentityHashMap<>());

        private RecordingEventBus()
        {
            super(error -> { throw new AssertionError(error); });
        }

        @Override
        public synchronized void register(Object subscriber)
        {
            super.register(subscriber);
            registered.add(subscriber);
        }

        @Override
        public synchronized void unregister(Object subscriber)
        {
            super.unregister(subscriber);
            registered.remove(subscriber);
        }
    }

    private static <T> T proxy(Class<T> type, BiFunction<String, Object[], Object> handler)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
            (object, method, args) -> {
                if (method.getName().equals("hashCode")) { return System.identityHashCode(object); }
                if (method.getName().equals("equals")) { return object == args[0]; }
                if (method.getName().equals("toString")) { return type.getSimpleName() + " test proxy"; }
                Object result = handler.apply(method.getName(), args);
                if (result != null || !method.getReturnType().isPrimitive()) { return result; }
                if (method.getReturnType() == boolean.class) { return false; }
                if (method.getReturnType() == int.class) { return 0; }
                throw new AssertionError("Unexpected method: " + method);
            }));
    }
}

package com.seasonalscape;

import org.junit.Test;
import static org.junit.Assert.*;

public class SeasonalTextureTintTest
{
    @Test
    public void preservesFaceSentinelsAndValuesThatAreNotTextureBrightness()
    {
        int[] unchanged = {Integer.MIN_VALUE, -2, -1, 128, 5642,
            20 << 10 | 4 << 7 | 50, 65535, 12345678, Integer.MAX_VALUE};
        for (int texture : new int[]{8, 30, 60})
        {
            for (int color : unchanged)
            {
                assertEquals("Texture " + texture + " must preserve " + color,
                    color, SeasonalTextureTint.autumn(color, texture));
                for (Season season : Season.values())
                {
                    assertEquals("Season " + season + " must preserve " + color,
                        color, SeasonalTextureTint.foliage(color, texture, season));
                }
            }
        }
    }

    @Test
    public void autumnTintKeepsFaceShadowsOrderedWithinVisibleHslBounds()
    {
        for (int texture : new int[]{8, 30, 60})
        {
            int previousLightness = -1;
            for (int brightness = 0; brightness <= 127; brightness++)
            {
                int tint = SeasonalTextureTint.autumn(brightness, texture);
                int hue = tint >>> 10;
                int lightness = tint & 127;
                assertTrue(tint >= 0 && tint <= 65535);
                assertTrue("Tint should remain orange or amber", hue >= 4 && hue <= 6);
                assertTrue("Shadows must remain visible", lightness >= 24);
                assertTrue("Highlights must retain color", lightness <= 88);
                assertTrue("A brighter face cannot become darker", lightness >= previousLightness);
                previousLightness = lightness;
            }
            int shadow = SeasonalTextureTint.autumn(33, texture) & 127;
            int highlight = SeasonalTextureTint.autumn(126, texture) & 127;
            assertTrue("Foliage needs visible shading contrast", highlight - shadow >= 40);
        }
    }

    @Test
    public void selectsOnlyTheThreeVerifiedLeafTextures()
    {
        for (int texture = Short.MIN_VALUE; texture <= Short.MAX_VALUE; texture++)
        {
            boolean expected = texture == 8 || texture == 30 || texture == 60;
            assertEquals("Unexpected texture selection: " + texture,
                expected, SeasonalTextureTint.isLeafTexture(texture));
        }
        assertFalse(SeasonalTextureTint.isLeafTexture(Integer.MIN_VALUE));
        assertFalse(SeasonalTextureTint.isLeafTexture(Integer.MAX_VALUE));
    }

    @Test
    public void springAndSummerTintsStayGreenAndRetainShading()
    {
        for (int texture : new int[]{8, 30, 60})
        {
            for (Season season : new Season[]{Season.SPRING, Season.SUMMER})
            {
                int previousLightness = -1;
                for (int brightness = 0; brightness <= 127; brightness++)
                {
                    int color = SeasonalTextureTint.foliage(brightness, texture, season);
                    int hue = color >>> 10;
                    int lightness = color & 127;
                    assertTrue("Foliage stays green", hue >= 20 && hue <= 22);
                    assertTrue("Texture shadows remain visible", lightness >= 26);
                    assertTrue("Highlights keep their color", lightness <= 98);
                    assertTrue(lightness >= previousLightness);
                    previousLightness = lightness;
                    assertTrue("Spring leaves are brighter than summer leaves",
                        (SeasonalTextureTint.foliage(brightness, texture, Season.SPRING) & 127)
                            > (SeasonalTextureTint.foliage(brightness, texture, Season.SUMMER) & 127));
                }
            }
        }
    }

    @Test
    public void tintLeavesWinterAndUnknownTexturesUntouched()
    {
        for (int brightness = 0; brightness <= 127; brightness++)
        {
            for (Season season : Season.values())
            {
                assertEquals(brightness, SeasonalTextureTint.foliage(brightness, 7, season));
                assertEquals(brightness, SeasonalTextureTint.foliage(brightness, -1, season));
            }
            assertEquals(brightness, SeasonalTextureTint.foliage(brightness, 8, Season.WINTER));
            assertEquals(SeasonalTextureTint.autumn(brightness, 8),
                SeasonalTextureTint.foliage(brightness, 8, Season.AUTUMN));
        }
    }
}

package com.seasonalscape;

import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import net.runelite.client.audio.AudioPlayer;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SeasonalWinterAudioTest
{
    private static final int SAMPLE_RATE = 22050;

    @Test
    public void wavContainsExactStereoPcmAndAConsistentPlayableHeader()
    {
        byte[] pcm = {0, 0, -1, 127, 0, -128, 4, 0};
        byte[] wav = SeasonalWinterAudio.wave(pcm);
        ByteBuffer header = ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);
        assertEquals("RIFF", new String(wav, 0, 4, StandardCharsets.US_ASCII));
        assertEquals(wav.length - 8, header.getInt(4));
        assertEquals("WAVE", new String(wav, 8, 4, StandardCharsets.US_ASCII));
        assertEquals("fmt ", new String(wav, 12, 4, StandardCharsets.US_ASCII));
        assertEquals(16, header.getInt(16));
        assertEquals(1, header.getShort(20));
        assertEquals(2, header.getShort(22));
        assertEquals(SAMPLE_RATE, header.getInt(24));
        assertEquals(SAMPLE_RATE * 4, header.getInt(28));
        assertEquals(4, header.getShort(32));
        assertEquals(16, header.getShort(34));
        assertEquals("data", new String(wav, 36, 4, StandardCharsets.US_ASCII));
        assertEquals(pcm.length, header.getInt(40));
        assertArrayEquals(pcm, Arrays.copyOfRange(wav, 44, wav.length));
    }

    @Test
    public void supportedPlayerReceivesAQuietBoundedChunkAndDisableStopsFurtherSubmission()
    {
        SeasonalWinterAudio.State[] state = new SeasonalWinterAudio.State[1];
        byte[][] received = {null};
        int[] calls = {0};
        AudioPlayer player = new AudioPlayer()
        {
            @Override public void play(InputStream input, float gain) throws IOException
            {
                calls[0]++;
                assertEquals("PCM already controls volume; device gain stays at zero decibels", 0, gain, 0);
                received[0] = input.readAllBytes();
                state[0].enabled = false;
                state[0].signal();
            }
        };
        state[0] = ready(player);
        state[0].volume = 25;
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(123);
        sound.render(new byte[SAMPLE_RATE * 4 * 4], 0.2f); // Advance the initial silent four seconds.
        state[0].play(sound);
        assertEquals("Turning off prevents the next chunk", 1, calls[0]);
        assertFalse(state[0].playing);
        assertFalse(state[0].failed);
        int bytes = ByteBuffer.wrap(received[0]).order(ByteOrder.LITTLE_ENDIAN).getInt(40);
        assertEquals(received[0].length - 44, bytes);
        assertTrue("Already-started playback has at most a quarter-second tail", bytes / 4.0 / SAMPLE_RATE <= 0.25);
        byte[] pcm = Arrays.copyOfRange(received[0], 44, received[0].length);
        assertTrue(SeasonalWinterAudio.hasSignal(pcm));
        assertTrue("The user's quarter-volume setting is in the actual PCM", peak(pcm) < 400);
        assertArrayEquals("A finite clip starts at zero to avoid clicks", new byte[4], Arrays.copyOf(pcm, 4));
        assertArrayEquals("A finite clip ends at zero to avoid clicks", new byte[4], Arrays.copyOfRange(pcm, pcm.length - 4, pcm.length));
        state[0].play(sound);
        assertEquals("A disabled state cannot submit another clip", 1, calls[0]);
    }

    @Test
    public void quietGapsDoNotSubmitAudioAndEveryLifecycleGatePreventsPlayback()
    {
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(123);
        byte[] silence = new byte[SAMPLE_RATE * 4];
        sound.render(silence, 0.8f);
        assertFalse("The silent lead-in never needs an AudioPlayer call", SeasonalWinterAudio.hasSignal(silence));
        for (int scenario = 0; scenario < 6; scenario++)
        {
            AudioPlayer player = new AudioPlayer()
            {
                @Override public void play(InputStream input, float gain)
                {
                    throw new AssertionError("Inactive audio must not touch device playback");
                }
            };
            SeasonalWinterAudio.State state = ready(player);
            switch (scenario)
            {
                case 0: state.enabled = false; break;
                case 1: state.closed = true; break;
                case 2: state.inWorld = false; break;
                case 3: state.winter = false; break;
                case 4: state.volume = 0; break;
                case 5: state.failed = true; break;
                default: throw new AssertionError();
            }
            state.play(sound);
            assertFalse(state.playing);
        }
    }

    @Test
    public void unavailablePlayerStopsTheSessionUntilTheUserRetries()
    {
        AudioPlayer player = new AudioPlayer()
        {
            @Override public void play(InputStream input, float gain) throws IOException
            {
                throw new IOException("Test device unavailable");
            }
        };
        SeasonalWinterAudio.State state = ready(player);
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(123);
        sound.render(new byte[SAMPLE_RATE * 4 * 4], 0.2f);
        state.play(sound);
        assertTrue(state.failed);
        assertFalse(state.playing);
        assertFalse(state.wanted());
        assertTrue(state.status().contains("Toggle off and on"));
    }

    @Test
    public void pacingIgnoresSettingsWakeupsAndStopsPromptlyOnClose() throws Exception
    {
        SeasonalWinterAudio.State state = ready(new AudioPlayer());
        assertTrue("An elapsed deadline permits one next chunk", state.awaitChunk(System.nanoTime() - 1));
        CountDownLatch entered = new CountDownLatch(1), finished = new CountDownLatch(1);
        boolean[] result = {true};
        Thread waiter = new Thread(() -> {
            entered.countDown();
            result[0] = state.awaitChunk(System.nanoTime() + TimeUnit.SECONDS.toNanos(30));
            finished.countDown();
        });
        waiter.setDaemon(true);
        waiter.start();
        try
        {
            assertTrue(entered.await(2, TimeUnit.SECONDS));
            for (int wakeup = 0; wakeup < 4; wakeup++) { state.signal(); }
            assertFalse("Configuration notifications cannot accelerate the playback clock",
                finished.await(100, TimeUnit.MILLISECONDS));
            state.closed = true;
            state.signal();
            assertTrue("Closing wakes the worker rather than waiting through its deadline",
                finished.await(2, TimeUnit.SECONDS));
            assertFalse("A closed state never permits another chunk", result[0]);
        }
        finally
        {
            state.closed = true;
            state.signal();
            waiter.join(2000);
        }
        assertFalse(waiter.isAlive());
    }

    private static SeasonalWinterAudio.State ready(AudioPlayer player)
    {
        SeasonalWinterAudio.State state = new SeasonalWinterAudio.State(null, null, player);
        state.enabled = state.inWorld = state.winter = true;
        return state;
    }

    @Test
    public void DisabledAudioProducesExactDigitalSilence()
    {
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(123);
        byte[] buffer = new byte[2048];
        for (int i = 0; i < 4; i++) { sound.render(buffer, 0); }
        assertArrayEquals(new byte[buffer.length], buffer);
        assertTrue(sound.isSilent());
    }

    @Test
    public void SnowAndIceAccentsHaveSilentGapsInsteadOfContinuousWind()
    {
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(123);
        assertSilence(renderSeconds(sound, 4));
        assertTrue("The replacement snow-settling accent is audible", peak(renderSeconds(sound, 1)) > 100);
        assertSilence(renderSeconds(sound, 4));
        assertTrue("The original faint icy overtones remain audible", peak(renderSeconds(sound, 4)) > 100);
        assertSilence(renderSeconds(sound, 10));
    }

    @Test
    public void PcmIsDeterministicBoundedAndFadesToSilence()
    {
        SeasonalWinterAudio.SnowSound first = new SeasonalWinterAudio.SnowSound(567);
        SeasonalWinterAudio.SnowSound second = new SeasonalWinterAudio.SnowSound(567);
        byte[] a = new byte[2048], b = new byte[2048];
        int peak = 0;
        // Includes the initial icy overtone at nine seconds.
        for (int block = 0; block < 450; block++)
        {
            first.render(a, 0.8f);
            second.render(b, 0.8f);
            assertArrayEquals(a, b);
            peak = Math.max(peak, peak(a));
        }
        assertTrue("Audible signal is generated", peak > 100);
        assertTrue("Even full-volume accents remain quiet", peak < 1500);
        for (int i = 0; i < 40; i++) { first.render(a, 0); }
        assertArrayEquals("Switching off settles at exact silence", new byte[a.length], a);
        assertTrue(first.isSilent());
    }

    @Test
    public void RepeatedAccentsLeaveMostOfTheSessionSilent()
    {
        SeasonalWinterAudio.SnowSound sound = new SeasonalWinterAudio.SnowSound(567);
        byte[] buffer = new byte[SAMPLE_RATE * 4];
        int silentFrames = 0;
        for (int second = 0; second < 120; second++)
        {
            sound.render(buffer, 0.8f);
            assertTrue("Accents stay quiet throughout the session", peak(buffer) < 1500);
            for (int offset = 0; offset < buffer.length; offset += 4)
            {
                if ((buffer[offset] | buffer[offset + 1] | buffer[offset + 2] | buffer[offset + 3]) == 0)
                {
                    silentFrames++;
                }
            }
        }
        assertTrue("Long quiet gaps keep ambience from masking game sounds",
            silentFrames > SAMPLE_RATE * 120L * 0.70);
    }

    @Test(expected = IllegalArgumentException.class)
    public void RejectsIncompleteStereoFrames()
    {
        new SeasonalWinterAudio.SnowSound(1).render(new byte[3], 0.2f);
    }

    private static byte[] renderSeconds(SeasonalWinterAudio.SnowSound sound, int seconds)
    {
        byte[] result = new byte[seconds * SAMPLE_RATE * 4];
        sound.render(result, 0.8f);
        return result;
    }

    private static void assertSilence(byte[] pcm)
    {
        assertArrayEquals("No wind or lingering noise between accents", new byte[pcm.length], pcm);
    }

    private static int peak(byte[] pcm)
    {
        int peak = 0;
        for (int offset = 0; offset < pcm.length; offset += 2)
        {
            int value = (short) ((pcm[offset] & 255) | ((pcm[offset + 1] & 255) << 8));
            peak = Math.max(peak, Math.abs(value));
        }
        return peak;
    }
}

