package com.seasonalscape;

import java.lang.reflect.Proxy;
import net.runelite.api.Model;
import org.junit.Test;
import static org.junit.Assert.*;

public class WinterCanopySnowTest
{
    @Test
    public void coversSolidCanopyAndFlatUpperWillowLeavesButPreservesSkirtsAndTrunks()
    {
        Fixture f = new Fixture();
        assertEquals(3, WinterCanopySnow.apply(f, f.model()));
        assertArrayEquals(new short[]{-1, 8, -1, 30, -1, 7}, f.textures);
        assertEquals("A flat cap receives visible pale snow", 0, f.a[0] >>> 7 & 7);
        assertTrue((f.a[0] & 127) >= 88);
        assertEquals("Flat faces use the original first-channel lighting", f.a[0], f.b[0]);
        assertEquals("Flat caps become Gouraud shaded", f.a[0], f.c[0]);
        assertEquals("Hidden faces remain hidden and retain their lighting", 90, f.a[2]);
        assertEquals(60, f.a[1]);
        assertEquals(50, f.a[3]);
        assertEquals(5642, f.a[4]);
        assertEquals(-2, f.c[2]);
        WinterCanopySnow.restore(f);
        assertArrayEquals(new short[]{60, 8, 30, 30, -1, 7}, f.textures);
        assertArrayEquals(new int[]{70, 60, 90, 50, 5642, 77}, f.a);
        assertEquals("Restoration recovers the flat-shading sentinel", -1, f.c[0]);
    }

    @Test
    public void repeatedScansAndSharedArraysRetainOriginalBrightness()
    {
        Fixture f = new Fixture();
        Model first = f.model(), second = f.model();
        assertEquals(3, WinterCanopySnow.apply(f, first));
        int[] after = f.a.clone();
        assertEquals(1, WinterCanopySnow.apply(f, second));
        assertEquals(1, WinterCanopySnow.apply(f, first));
        assertArrayEquals(after, f.a);
        WinterCanopySnow.restore(f);
        assertEquals(70, f.a[0]);
        assertEquals(90, f.a[2]);
        assertEquals(60, f.textures[0]);
    }

    @Test
    public void preservesExternalTextureAndColorWritesOnRepeatAndRestore()
    {
        Fixture f = new Fixture();
        WinterCanopySnow.apply(f, f.model());
        f.textures[0] = 13;
        f.a[2] = 999;
        WinterCanopySnow.apply(f, f.model());
        assertEquals(13, f.textures[0]);
        assertEquals(999, f.a[2]);
        WinterCanopySnow.restore(f);
        assertEquals(13, f.textures[0]);
        assertEquals(999, f.a[2]);
        assertEquals(30, f.textures[2]);
        assertEquals(80, f.b[0]);
    }

    @Test
    public void leavesPreviouslyColoredTextureFacesUntouched()
    {
        Fixture f = new Fixture();
        f.a[0] = 12345;
        WinterCanopySnow.apply(f, f.model());
        assertEquals(60, f.textures[0]);
        assertEquals(12345, f.a[0]);
        assertEquals(80, f.b[0]);
        WinterCanopySnow.restore(f);
        assertEquals(12345, f.a[0]);
    }

    @Test
    public void blendsTheSnowApexIntoTheGreenRimAndRestoresFlatShading()
    {
        Fixture f = new Fixture();
        f.y[0] = -130;
        WinterCanopySnow.apply(f, f.model());
        assertEquals("Apex is neutral snow", 0, f.a[0] >>> 7 & 7);
        assertTrue("Apex stays light", (f.a[0] & 127) >= 88);
        assertEquals("Rim has a muted green hue", 16, f.b[0] >>> 10);
        assertEquals(1, f.b[0] >>> 7 & 7);
        assertFalse("The foliage pass must not whiten the blended edge again", SeasonalPalette.isVegetation(f.b[0]));
        assertTrue("Rim merges into leaves", (f.b[0] & 127) >= 30 && (f.b[0] & 127) <= 40);
        assertEquals(f.b[0], f.c[0]);
        int[] firstPass = f.a.clone();
        assertEquals(1, WinterCanopySnow.apply(f, f.model()));
        assertArrayEquals(firstPass, f.a);
        WinterCanopySnow.restore(f);
        assertEquals(70, f.a[0]);
        assertEquals(80, f.b[0]);
        assertEquals(-1, f.c[0]);
    }

    private static final class Fixture
    {
        private final short[] textures = {60, 8, 30, 30, -1, 7};
        private final int[] a = {70, 60, 90, 50, 5642, 77};
        private final int[] b = {80, 60, 95, 50, 5650, 77};
        private final int[] c = {-1, 60, -2, 50, 5655, 77};
        private final float[] x = {0, 10, 0, 0, 10, 0};
        private final float[] y = {-100, -100, -100, -20, -20, -20};
        private final float[] z = {0, 0, 10, 0, 0, 10};
        private final int[] ai = {0, 0, 0, 3, 3, 3};
        private final int[] bi = {1, 1, 1, 4, 4, 4};
        private final int[] ci = {2, 2, 2, 5, 5, 5};

        private Model model()
        {
            return (Model) Proxy.newProxyInstance(Model.class.getClassLoader(), new Class<?>[]{Model.class},
                (proxy, method, args) -> {
                    switch (method.getName())
                    {
                        case "getFaceTextures": return textures;
                        case "getFaceColors1": return a;
                        case "getFaceColors2": return b;
                        case "getFaceColors3": return c;
                        case "getVerticesX": return x;
                        case "getVerticesY": return y;
                        case "getVerticesZ": return z;
                        case "getFaceIndices1": return ai;
                        case "getFaceIndices2": return bi;
                        case "getFaceIndices3": return ci;
                        case "getFaceCount": return textures.length;
                        case "hashCode": return System.identityHashCode(proxy);
                        case "equals": return proxy == args[0];
                        default: return null;
                    }
                });
        }
    }
}

package com.seasonalscape;

import java.lang.reflect.Proxy;
import net.runelite.api.Model;
import org.junit.Test;

import static org.junit.Assert.*;

public class WinterRoofMaterialTest
{
    @Test
    public void steepAndDegenerateRoofFacesDoNotReceiveSnow()
    {
        Object owner = new Object();
        Roof roof = new Roof();
        roof.faceCount = 1;
        roof.y[roof.b[0]] = -170;
        roof.y[roof.c[0]] = 0;
        int[][] original = roof.copyColors();
        try
        {
            assertEquals("Upward slope just within the snow limit", 3, WinterRoofMaterial.apply(owner, roof.model()));
            assertTrue(WinterRoofMaterial.restore(owner));

            roof.y[roof.b[0]] = -172;
            assertEquals("Steeper slope stays bare", 0, WinterRoofMaterial.apply(owner, roof.model()));
            for (int channel = 0; channel < 3; channel++) { assertArrayEquals(original[channel], roof.colors[channel]); }
            assertFalse(WinterRoofMaterial.restore(owner));

            roof.b[0] = roof.c[0] = roof.a[0];
            assertEquals("Zero-area face stays bare", 0, WinterRoofMaterial.apply(owner, roof.model()));
            assertFalse(WinterRoofMaterial.restore(owner));
        }
        finally { WinterRoofMaterial.restore(owner); }
    }

    @Test
    public void onlyActiveFacesAndVerticesReceiveSnow()
    {
        for (boolean limitedVertices : new boolean[]{true, false})
        {
            Object owner = new Object();
            Roof roof = new Roof();
            roof.vertexCount = limitedVertices ? 3 : roof.x.length;
            roof.faceCount = limitedVertices ? roof.a.length : 1;
            int[][] original = roof.copyColors();
            try
            {
                assertEquals(3, WinterRoofMaterial.apply(owner, roof.model()));
                assertArrayEquals(new short[]{-1, 45, 45, 45, 45, -1}, roof.textures);
                for (int channel = 0; channel < 3; channel++)
                {
                    assertSnow(roof.colors[channel][0]);
                    for (int face = 1; face < roof.a.length; face++)
                    {
                        assertEquals("Unused model capacity stays unchanged", original[channel][face], roof.colors[channel][face]);
                    }
                }
                WinterRoofMaterial.restore(owner);
                for (int channel = 0; channel < 3; channel++) { assertArrayEquals(original[channel], roof.colors[channel]); }
            }
            finally { WinterRoofMaterial.restore(owner); }
        }
    }

    @Test
    public void snowCoversRoofSlopesButPreservesSidesUndersidesAndFaceSentinels()
    {
        Object owner = new Object();
        Roof roof = new Roof();
        int[][] original = roof.copyColors();
        short[] originalTextures = roof.textures.clone();
        float[] originalY = roof.y.clone();
        try
        {
            assertEquals(3, WinterRoofMaterial.apply(owner, roof.model()));
            assertArrayEquals(new short[]{-1, 45, 45, -1, 45, -1}, roof.textures);
            for (int channel = 0; channel < 3; channel++)
            {
                assertSnow(roof.colors[channel][0]);
                assertSnow(roof.colors[channel][5]);
                assertEquals("Vertical roof side is unchanged", original[channel][1], roof.colors[channel][1]);
                assertEquals("Roof underside is unchanged", original[channel][2], roof.colors[channel][2]);
                assertEquals("Hidden face is unchanged", original[channel][4], roof.colors[channel][4]);
            }
            assertTrue("Snow retains relative roof lighting", roof.colors[0][0] < roof.colors[1][0]);
            assertTrue(roof.colors[1][0] <= roof.colors[2][0]);
            assertSnow(roof.colors[0][3]);
            assertEquals("Unused flat channel is unchanged", 0, roof.colors[1][3]);
            assertEquals("Flat face sentinel survives", -1, roof.colors[2][3]);
            assertEquals("Hidden face sentinel survives", -2, roof.colors[2][4]);
            assertArrayEquals("Native geometry is preserved", originalY, roof.y, 0);

            int[][] snowy = roof.copyColors();
            assertEquals("Repeated refresh needs no GPU upload", 1, WinterRoofMaterial.apply(owner, roof.model()));
            for (int channel = 0; channel < 3; channel++) { assertArrayEquals(snowy[channel], roof.colors[channel]); }
            assertTrue(WinterRoofMaterial.restore(owner));
            assertArrayEquals(originalTextures, roof.textures);
            for (int channel = 0; channel < 3; channel++) { assertArrayEquals(original[channel], roof.colors[channel]); }
            assertFalse("Restoration is idempotent", WinterRoofMaterial.restore(owner));
        }
        finally { WinterRoofMaterial.restore(owner); }
    }

    @Test
    public void sharedColorAndTextureArraysDoNotAccumulateSnowAcrossRoofCopies()
    {
        Object owner = new Object();
        Roof roof = new Roof();
        int[] shared = {96, 96, 96, 100, -2, 5 << 10 | 4 << 7 | 40};
        roof.colors = new int[][]{shared, shared, shared};
        int[] original = shared.clone();
        short[] originalTextures = roof.textures.clone();
        try
        {
            assertEquals(3, WinterRoofMaterial.apply(owner, roof.model()));
            int[] first = shared.clone();
            assertEquals(1, WinterRoofMaterial.apply(owner, roof.model()));
            assertArrayEquals(first, shared);
            assertTrue(WinterRoofMaterial.restore(owner));
            assertArrayEquals(original, shared);
            assertArrayEquals(originalTextures, roof.textures);
        }
        finally { WinterRoofMaterial.restore(owner); }
    }

    @Test
    public void restoresOwnedValuesWithoutOverwritingAnotherModifiersChanges()
    {
        Object owner = new Object();
        Roof roof = new Roof();
        int[][] original = roof.copyColors();
        try
        {
            WinterRoofMaterial.apply(owner, roof.model());
            roof.colors[0][0] = 12345;
            roof.textures[3] = 7;
            WinterRoofMaterial.apply(owner, roof.model());
            assertEquals(12345, roof.colors[0][0]);
            assertEquals(7, roof.textures[3]);
            assertTrue(WinterRoofMaterial.restore(owner));
            assertEquals("External color survives restoration", 12345, roof.colors[0][0]);
            assertEquals("External texture survives restoration", 7, roof.textures[3]);
            assertEquals(original[1][0], roof.colors[1][0]);
            assertEquals(original[2][0], roof.colors[2][0]);
            assertEquals(45, roof.textures[0]);
            assertEquals(original[0][3], roof.colors[0][3]);
        }
        finally { WinterRoofMaterial.restore(owner); }
    }

    private static void assertSnow(int color)
    {
        assertEquals("Snow is neutral", 0, color >>> 7 & 7);
        assertTrue("Snow is softly shaded", (color & 127) >= 86 && (color & 127) <= 108);
    }

    private static final class Roof
    {
        private final float[] x = new float[18], y = new float[18], z = new float[18];
        private final int[] a = new int[6], b = new int[6], c = new int[6];
        private int[][] colors = {
            {96, 96, 96, 100, 80, 5 << 10 | 4 << 7 | 40},
            {116, 116, 116, 0, 80, 5 << 10 | 4 << 7 | 50},
            {120, 120, 120, -1, -2, 5 << 10 | 4 << 7 | 60}
        };
        private final short[] textures = {45, 45, 45, 45, 45, -1};
        private int vertexCount = x.length, faceCount = a.length;

        private Roof()
        {
            for (int face = 0; face < a.length; face++)
            {
                a[face] = face * 3;
                b[face] = face * 3 + 1;
                c[face] = face * 3 + 2;
                x[b[face]] = 64;
                z[c[face]] = 64;
            }
            // Face 0 is a sloped roof; face 1 a vertical side; face 2 faces down.
            y[b[0]] = -30;
            y[c[0]] = -30;
            z[c[1]] = 0;
            y[c[1]] = -64;
            x[b[2]] = 0;
            z[b[2]] = 64;
            x[c[2]] = 64;
            z[c[2]] = 0;
        }

        private int[][] copyColors()
        {
            return new int[][]{colors[0].clone(), colors[1].clone(), colors[2].clone()};
        }

        private Model model()
        {
            return (Model) Proxy.newProxyInstance(Model.class.getClassLoader(), new Class<?>[]{Model.class},
                (proxy, method, args) -> {
                    switch (method.getName())
                    {
                        case "getVerticesX": return x;
                        case "getVerticesY": return y;
                        case "getVerticesZ": return z;
                        case "getVerticesCount": return vertexCount;
                        case "getFaceCount": return faceCount;
                        case "getFaceIndices1": return a;
                        case "getFaceIndices2": return b;
                        case "getFaceIndices3": return c;
                        case "getFaceColors1": return colors[0];
                        case "getFaceColors2": return colors[1];
                        case "getFaceColors3": return colors[2];
                        case "getFaceTextures": return textures;
                        default: throw new UnsupportedOperationException(method.getName());
                    }
                });
        }
    }
}

package com.seasonalscape;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class WinterSnowVisibilityTest
{
    @Test
    public void rejectsStructuresBehindCameraAndOutsideThePaddedViewport()
    {
        WinterSnowVisibility view = view(0, 0);
        assertTrue(view.visibleSphere(0, 1000, 0, 20, false));
        assertFalse(view.visibleSphere(0, -1000, 0, 20, false));
        assertFalse(view.visibleSphere(1300, 1000, 0, 20, false));
        assertFalse(view.visibleSphere(-1300, 1000, 0, 20, false));
        assertFalse(view.visibleSphere(0, 1000, 1300, 20, false));
        assertFalse(view.visibleSphere(0, 1000, -1300, 20, false));
    }

    @Test
    public void rotatesAndPitchesVisibilityWithTheCamera()
    {
        WinterSnowVisibility west = view(0, Math.PI / 2);
        assertTrue(west.visibleSphere(-1000, 0, 0, 20, false));
        assertFalse(west.visibleSphere(1000, 0, 0, 20, false));
        WinterSnowVisibility tilted = view(Math.PI / 4, 0);
        assertTrue(tilted.visibleSphere(0, 1000, 1000, 20, false));
        assertFalse(tilted.visibleSphere(0, 1000, -1000, 20, false));
    }

    @Test
    public void preservesPartlyVisibleCornersAndNearPlaneIntersections()
    {
        WinterSnowVisibility view = view(0, 0);
        assertFalse("The center is outside two viewport edges", view.visibleSphere(1000, 1000, 800, 0, false));
        assertTrue("Part of the structure is still visible", view.visibleSphere(1000, 1000, 800, 60, false));
        assertTrue("Camera inside bounds must not hide the roof", view.visibleSphere(0, 0, 0, 100, false));
        assertTrue(view.visibleSphere(0, 40, 0, 20, false));
        assertFalse(view.visibleSphere(0, 10, 0, 10, false));
    }

    @Test
    public void keepsHighRoofsWhenTheirGroundTileIsBelowTheViewport()
    {
        WinterSnowVisibility view = view(0, 0);
        assertFalse(view.visibleSphere(64, 960, 1200, 0, false));
        assertTrue("The roof above the offscreen ground is visible", view.visibleTile(0, 7, 1200, false));
        assertFalse("An entirely offscreen column still gets culled", view.visibleTile(0, 7, 3000, false));
    }

    @Test
    public void retainsExistingSnowInAWiderFrustumToAvoidEdgeFlicker()
    {
        WinterSnowVisibility view = view(0, 0);
        assertFalse(view.visibleSphere(1050, 1000, 0, 0, false));
        assertTrue(view.visibleSphere(1050, 1000, 0, 0, true));
        assertFalse(view.visibleSphere(1200, 1000, 0, 0, true));
    }

    @Test
    public void distanceCapWorksWithoutAViewportAndHasRetentionHysteresis()
    {
        int player = 4000;
        WinterSnowVisibility view = new WinterSnowVisibility(player, player, 0, 0, 0, 0, 0, 0, 0, 0);
        assertTrue(view.visibleSphere(player + 22 * 128, player, 0, 0, false));
        assertFalse(view.visibleSphere(player + 23 * 128, player, 0, 0, false));
        assertTrue(view.visibleSphere(player + 23 * 128, player, 0, 0, true));
        assertFalse(view.visibleSphere(player + 25 * 128, player, 0, 0, true));
        assertTrue("Part of a large structure overlaps the range", view.visibleSphere(player + 23 * 128, player, 0, 256, false));
    }

    @Test
    public void rescanThresholdTracksMeaningfulMotionZoomAndViewportChanges()
    {
        WinterSnowVisibility previous = view(0, 0);
        assertTrue(previous.similarTo(view(0, 0)));
        assertTrue(previous.similarTo(view(0, 2 * Math.PI - .005)));
        assertFalse(previous.similarTo(view(0, .05)));
        assertFalse(previous.similarTo(view(.05, 0)));
        assertFalse(previous.similarTo(null));
        assertTrue(previous.similarTo(new WinterSnowVisibility(40, 40, 40, 40, 40, 0, 0, 800, 600, 512)));
        assertFalse(previous.similarTo(new WinterSnowVisibility(128, 0, 0, 0, 0, 0, 0, 800, 600, 512)));
        assertFalse(previous.similarTo(new WinterSnowVisibility(0, 0, 0, 128, 0, 0, 0, 800, 600, 512)));
        assertFalse(previous.similarTo(new WinterSnowVisibility(0, 0, 0, 0, 0, 0, 0, 900, 600, 512)));
        assertFalse(previous.similarTo(new WinterSnowVisibility(0, 0, 0, 0, 0, 0, 0, 800, 600, 700)));
    }

    @Test
    public void capturesCpuFourteenBitAnglesAndGpuRadianAngles()
    {
        Map<String, Object> values = new HashMap<>();
        values.put("getViewportWidth", 800);
        values.put("getViewportHeight", 600);
        values.put("getScale", 512);
        values.put("getCameraYaw", 4096);
        Client client = client(values);
        WinterSnowVisibility cpu = WinterSnowVisibility.capture(client, new LocalPoint(0, 0, 0));
        assertTrue(cpu.visibleSphere(-1000, 0, 0, 20, false));
        assertFalse(cpu.visibleSphere(1000, 0, 0, 20, false));
        values.put("isGpu", true);
        values.put("getCameraFpYaw", (float) -Math.PI / 2);
        values.put("getCameraFpX", 128f);
        WinterSnowVisibility gpu = WinterSnowVisibility.capture(client, new LocalPoint(0, 0, 0));
        assertTrue(gpu.visibleSphere(1000, 0, 0, 20, false));
        assertFalse(gpu.visibleSphere(-1000, 0, 0, 20, false));
    }

    @Test
    public void unavailableProjectionFallsBackToDistanceOnly()
    {
        Map<String, Object> values = new HashMap<>();
        WinterSnowVisibility missing = WinterSnowVisibility.capture(client(values), new LocalPoint(0, 0, 0));
        assertTrue(missing.visibleSphere(0, -1000, 0, 20, false));
        values.put("getViewportWidth", 800);
        values.put("getViewportHeight", 600);
        values.put("getScale", 512);
        WinterSnowVisibility subview = WinterSnowVisibility.capture(client(values), new LocalPoint(0, 0, 1));
        assertTrue(subview.visibleSphere(0, -1000, 0, 20, false));
        assertFalse(subview.visibleSphere(0, -4000, 0, 20, false));
    }

    private static WinterSnowVisibility view(double pitch, double yaw)
    {
        return new WinterSnowVisibility(0, 0, 0, 0, 0, pitch, yaw, 800, 600, 512);
    }

    private static Client client(Map<String, Object> values)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> {
                Object value = values.get(method.getName());
                if (value != null) { return value; }
                if (method.getReturnType() == boolean.class) { return false; }
                if (method.getReturnType() == float.class) { return 0f; }
                if (method.getReturnType() == int.class) { return 0; }
                return null;
            });
    }
}

