                    (int) stateField(owner, "lastModels") <= 2);
                assertTrue("At most two overlays are built in any one client cycle",
                    (int) stateField(owner, "lastBuilds") <= 2);
                cycle[0]++; WinterSurfaceSnow.tick(owner);
